window.WMA12_QUESTIONS = [{"id":"WMA12-01_2021_Jan_Q05","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":5,"marks":4,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q05_M04_01_Proof.png","downloadName":"WMA12-01_Y2021_Jan_Q05_M04_01_Proof.png","finalAnswer":"$(i)$ Proven. $\\quad (ii)$ For example, $5+7+11=23$, which is not a multiple of $5$.","steps":[{"title":"Start from a square","body":"For $x\\geq0$, $\\sqrt{3x}$ is real and $(\\sqrt{3x}-1)^2\\geq0$."},{"title":"Expand the square","body":"$(\\sqrt{3x}-1)^2=3x-2\\sqrt{3x}+1\\geq0$."},{"title":"Rearrange the inequality","body":"Therefore $3x+1\\geq2\\sqrt{3x}$, as required."},{"title":"Give a counterexample","body":"The consecutive prime numbers $5$, $7$, and $11$ have sum $5+7+11=23$."},{"title":"Complete the disproof","body":"$23$ is not a multiple of $5$, so the statement is not true."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q03","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":3,"marks":5,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q03_M05_01_Proof.png","downloadName":"WMA12-01_Y2021_MayJune_Q03_M05_01_Proof.png","finalAnswer":"$(i)$ Proven by checking $p=2,3,5,7$. $\\quad (ii)$ Proven: $(n+1)^3-n^3$ leaves remainder $1$ on division by $3$.","steps":[{"title":"List the cases","body":"The single digit prime numbers are $2$, $3$, $5$, and $7$."},{"title":"Check each prime","body":"$2^3+2=10$, $3^3+3=30$, $5^3+5=130$, and $7^3+7=350$."},{"title":"Conclude part one","body":"Each result is a multiple of $10$, so $p^3+p$ is a multiple of $10$ for all single digit primes."},{"title":"Expand the difference of cubes","body":"$(n+1)^3-n^3=(n^3+3n^2+3n+1)-n^3=3n^2+3n+1$."},{"title":"Factor the multiple of three","body":"$3n^2+3n+1=3n(n+1)+1$."},{"title":"Use the remainder","body":"$3n(n+1)$ is a multiple of $3$, so $3n(n+1)+1$ is one more than a multiple of $3$. Therefore it is not a multiple of $3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q09","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":9,"marks":4,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q09_M04_01_Proof.png","downloadName":"WMA12-01_Y2021_Oct_Q09_M04_01_Proof.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ For example, $x=y=-1$ gives $-1\\not\\geq1$.","steps":[{"title":"Start with a square","body":"For positive $x$ and $y$, both $\\sqrt{x}$ and $\\sqrt{y}$ are real, so $(\\sqrt{x}-\\sqrt{y})^2\\geq0$."},{"title":"Expand","body":"$(\\sqrt{x}-\\sqrt{y})^2=x-2\\sqrt{xy}+y\\geq0$."},{"title":"Rearrange","body":"Thus $x+y\\geq2\\sqrt{xy}$, and dividing by $2$ gives $\\dfrac{x+y}{2}\\geq\\sqrt{xy}$."},{"title":"Give a negative counterexample","body":"Take $x=-1$ and $y=-1$. Then $\\dfrac{x+y}{2}=-1$, while $\\sqrt{xy}=\\sqrt1=1$."},{"title":"Conclude","body":"Since $-1\\geq1$ is false, the inequality does not hold for all negative $x$ and $y$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q10","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":10,"marks":5,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q10_M05_01_Proof.png","downloadName":"WMA12-01_Y2022_Jan_Q10_M05_01_Proof.png","finalAnswer":"$(i)$ For $p=7$, $2p+1=15$, not prime. $\\quad (ii)$ Proven.","steps":[{"title":"Give a counterexample","body":"Take $p=7$, which is prime."},{"title":"Show the statement fails","body":"$2p+1=2(7)+1=15$, and $15$ is not prime. So the statement is false."},{"title":"Case one: n even","body":"If $n$ is even, let $n=2k$. Then $5n^2+n+12=5(2k)^2+2k+12=20k^2+2k+12=2(10k^2+k+6)$, which is even."},{"title":"Case two: n odd","body":"If $n$ is odd, let $n=2k+1$. Then $5n^2+n+12=5(2k+1)^2+(2k+1)+12$."},{"title":"Simplify the odd case","body":"$5(2k+1)^2+(2k+1)+12=20k^2+22k+18=2(10k^2+11k+9)$, which is even."},{"title":"Conclude by exhaustion","body":"Every integer is either even or odd, and both cases give an even result. Therefore $5n^2+n+12$ is always even."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q03","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":3,"marks":7,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":["03_Circles"],"secondaryTopicNames":["Circles"],"topics":["01_Proof","03_Circles"],"topicNames":["Proof","Circles"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q03_M07_01_Proof.png","downloadName":"WMA12-01_Y2022_MayJune_Q03_M07_01_Proof.png","finalAnswer":"$(i)$ Counterexample: $n=5$ gives $91$, not prime. $\\quad (ii)$ Proven: $AB$ is a diameter.","steps":[{"title":"Choose a counterexample","body":"Take $n=5$."},{"title":"Evaluate the expression","body":"$(5+1)^3-5^3=216-125=91$."},{"title":"Show it is not prime","body":"$91=7\\times13$, so the statement is false."},{"title":"Find the gradient CA","body":"For $A(1,0)$ and $C(7,-6)$, the gradient of $CA$ is $\\dfrac{0-(-6)}{1-7}=-1$."},{"title":"Find the gradient CB","body":"For $B(3,-10)$ and $C(7,-6)$, the gradient of $CB$ is $\\dfrac{-10-(-6)}{3-7}=1$."},{"title":"Show the right angle","body":"The product of the gradients is $-1$, so $CA$ is perpendicular to $CB$ and $\\angle ACB=90^\\circ$."},{"title":"Conclude the diameter","body":"An angle of $90^\\circ$ at the circumference subtends a diameter, so $AB$ is a diameter of the circle."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q01","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":1,"marks":3,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q01_M03_01_Proof.png","downloadName":"WMA12-01_Y2022_Oct_Q01_M03_01_Proof.png","finalAnswer":"The possible triples are $(6,1,3)$, $(4,2,4)$ and $(2,3,5)$, giving products $18$, $32$ and $30$. Each product is even, so $abc$ is always even.","steps":[{"title":"Use the two conditions","body":"Since $c=b+2$ and $a+b+c=10$, substitute for $c$: $a+b+(b+2)=10$."},{"title":"Write a in terms of b","body":"This gives $a+2b+2=10$, so $a=8-2b$."},{"title":"List the possible b values","body":"The integers $a,b,c$ are all positive. Since $b>0$ and $a=8-2b>0$, the only possible values are $b=1,2,3$."},{"title":"Exhaust the cases","body":"If $b=1$, then $a=6$ and $c=3$, so $abc=18$. If $b=2$, then $a=4$ and $c=4$, so $abc=32$. If $b=3$, then $a=2$ and $c=5$, so $abc=30$."},{"title":"Conclude the proof","body":"The list contains every possible case, and in every case the product is even. Therefore $abc$ is always even."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q10","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":10,"marks":4,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q10_M04_01_Proof.png","downloadName":"WMA12-01_Y2023_Jan_Q10_M04_01_Proof.png","finalAnswer":"For $n=3k$, $n=3k+1$ and $n=3k+2$, the expression has remainders $1$, $1$ and $2$ respectively when divided by $3$. Therefore $2n^2+n+1$ is never divisible by $3$.","steps":[{"title":"Use the three possible forms","body":"Every integer is exactly one of the forms $3k$, $3k+1$ or $3k+2$, where $k$ is an integer."},{"title":"First case already given","body":"For $n=3k$, the expression becomes $3(6k^2+k)+1$, so it leaves remainder $1$ when divided by $3$."},{"title":"Try n equals 3k plus 1","body":"If $n=3k+1$, then $2n^2+n+1=2(3k+1)^2+(3k+1)+1$."},{"title":"Simplify the second case","body":"$2(9k^2+6k+1)+3k+2=18k^2+15k+4=3(6k^2+5k+1)+1$, which is not divisible by $3$."},{"title":"Try n equals 3k plus 2","body":"If $n=3k+2$, then $2n^2+n+1=2(3k+2)^2+(3k+2)+1$."},{"title":"Simplify the third case","body":"$2(9k^2+12k+4)+3k+3=18k^2+27k+11=3(6k^2+9k+3)+2$, which is not divisible by $3$."},{"title":"Complete the exhaustion","body":"All possible integer forms have been checked, and none gives a multiple of $3$. Therefore $2n^2+n+1$ is not divisible by $3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q08","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":8,"marks":5,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q08_M05_01_Proof.png","downloadName":"WMA12-01_Y2023_MayJune_Q08_M05_01_Proof.png","finalAnswer":"$(i)$ A counterexample is $a=7,b=11$, since $7^2+11^2=170$. $\\quad (ii)$ Exhaustion proves the inequality for $(x,y)=(2,2),(2,4),(4,2),(4,4)$.","steps":[{"title":"Choose consecutive primes","body":"$7$ and $11$ are consecutive prime numbers."},{"title":"Check the statement","body":"$7^2+11^2=49+121=170$, which is a multiple of $10$."},{"title":"Conclude the counterexample","body":"This single counterexample proves the student's statement is not true."},{"title":"List the possible even values","body":"The even integers greater than $0$ and less than $6$ are $2$ and $4$. Therefore the possible ordered pairs are $(2,2),(2,4),(4,2),(4,4)$."},{"title":"Check x equals two","body":"If $(x,y)=(2,2)$, then $x^2-\\dfrac{xy}{4}=4-1=3$. If $(x,y)=(2,4)$, then $x^2-\\dfrac{xy}{4}=4-2=2$."},{"title":"Check x equals four","body":"If $(x,y)=(4,2)$, then $x^2-\\dfrac{xy}{4}=16-2=14$. If $(x,y)=(4,4)$, then $x^2-\\dfrac{xy}{4}=16-4=12$."},{"title":"Complete the exhaustion","body":"The possible values are $3,2,14,12$, and each lies strictly between $1$ and $15$. Hence $1<x^2-\\dfrac{xy}{4}<15$ in every possible case."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q01","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":1,"marks":3,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q01_M03_01_Proof.png","downloadName":"WMA12-01_Y2023_Oct_Q01_M03_01_Proof.png","finalAnswer":"The only possible triples are $(1,10,4)$, $(2,6,7)$ and $(3,2,10)$, giving products $40$, $84$ and $60$. Each is a multiple of $4$, so $abc$ is always a multiple of $4$.","steps":[{"title":"Use the conditions","body":"Since $c=3a+1$ and $a+b+c=15$, substitute for $c$ to get $a+b+3a+1=15$."},{"title":"Write b in terms of a","body":"This gives $b=14-4a$."},{"title":"List possible a values","body":"The integers $a,b,c$ are positive. Since $b=14-4a>0$, we need $a<3.5$. Therefore $a=1,2,3$."},{"title":"Check each case","body":"If $a=1$, then $b=10$ and $c=4$, so $abc=40$. If $a=2$, then $b=6$ and $c=7$, so $abc=84$. If $a=3$, then $b=2$ and $c=10$, so $abc=60$."},{"title":"Conclude the exhaustion","body":"The products $40$, $84$ and $60$ are all multiples of $4$. All possible cases have been checked, so $abc$ is always a multiple of $4$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q08","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":8,"marks":6,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q08_M06_01_Proof.png","downloadName":"WMA12-01_Y2024_Jan_Q08_M06_01_Proof.png","finalAnswer":"$(i)$ Counterexample: $n=6$ gives $55$, which is not prime. $\\quad (ii)$ Proven by considering $n=4k,4k+1,4k+2,4k+3$.","steps":[{"title":"Choose a counterexample","body":"Take $n=6$."},{"title":"Evaluate the expression","body":"$n^2+3n+1=6^2+3(6)+1=36+18+1=55$."},{"title":"Conclude false","body":"$55$ is not prime, so the statement is false."},{"title":"Use residues modulo four","body":"Every natural number is one of $4k$, $4k+1$, $4k+2$ or $4k+3$."},{"title":"Check n equals 4k","body":"If $n=4k$, then $n^2-2=16k^2-2=4(4k^2-1)+2$, not a multiple of $4$."},{"title":"Check n equals 4k plus one","body":"If $n=4k+1$, then $n^2-2=16k^2+8k-1=4(4k^2+2k-1)+3$, not a multiple of $4$."},{"title":"Check n equals 4k plus two","body":"If $n=4k+2$, then $n^2-2=16k^2+16k+2=4(4k^2+4k)+2$, not a multiple of $4$."},{"title":"Check n equals 4k plus three","body":"If $n=4k+3$, then $n^2-2=16k^2+24k+7=4(4k^2+6k+1)+3$, not a multiple of $4$."},{"title":"Complete the proof","body":"All possible cases leave remainder $2$ or $3$ when divided by $4$, so $n^2-2$ is not a multiple of $4$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q05","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":5,"marks":6,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q05_M06_01_Proof.png","downloadName":"WMA12-01_Y2024_MayJune_Q05_M06_01_Proof.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ For example, $x=1,y=-1$ satisfies the inequality but not $y>x$.","steps":[{"title":"Start from the inequality","body":"$(x-y)^3>x^3-y^3$."},{"title":"Expand the left side","body":"$x^3-3x^2y+3xy^2-y^3>x^3-y^3$."},{"title":"Cancel common terms","body":"Subtract $x^3-y^3$ from both sides to get $-3x^2y+3xy^2>0$."},{"title":"Factor","body":"$3xy(y-x)>0$."},{"title":"Use positivity","body":"Since $x$ and $y$ are positive, $3xy>0$. Therefore $y-x>0$, so $y>x$."},{"title":"Give a real-number counterexample","body":"Take $x=1$ and $y=-1$. Then $(x-y)^3=2^3=8$ and $x^3-y^3=1-(-1)=2$, so the given inequality is true."},{"title":"Show the conclusion fails","body":"But $y>x$ would mean $-1>1$, which is false. Therefore the result is not true for all real numbers."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q11","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":11,"marks":6,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q11_M06_01_Proof.png","downloadName":"WMA12-01_Y2024_Oct_Q11_M06_01_Proof.png","finalAnswer":"$(i)$ Counterexample: $n=5$ gives $3^5+2=245$, not prime. $\\quad (ii)$ Proven.","steps":[{"title":"Choose a prime value","body":"Take $n=5$, which is prime."},{"title":"Evaluate the expression","body":"$3^5+2=243+2=245=5\\times49$, so it is not prime. This disproves the statement."},{"title":"List the possible forms of m","body":"If integer $m$ is not divisible by $3$, then $m$ has remainder $1$ or $2$ on division by $3$."},{"title":"Case one","body":"If $m=3q+1$, then $m^2-1=(3q+1)^2-1=9q^2+6q=3(3q^2+2q)$, which is divisible by $3$."},{"title":"Case two","body":"If $m=3q+2$, then $m^2-1=(3q+2)^2-1=9q^2+12q+3=3(3q^2+4q+1)$, which is divisible by $3$."},{"title":"Conclude by exhaustion","body":"Both possible cases for an integer not divisible by $3$ have been checked, so $m^2-1$ is divisible by $3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q08","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":8,"marks":5,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q08_M05_01_Proof.png","downloadName":"WMA12-01_Y2025_Jan_Q08_M05_01_Proof.png","finalAnswer":"$(i)$ For example, $x=\\sqrt2$ and $y=\\dfrac1{\\sqrt2}$ give $xy=1$. $\\quad (ii)$ Proven.","steps":[{"title":"Give a counterexample","body":"Let $x=\\sqrt2$ and $y=\\dfrac1{\\sqrt2}$. Both are irrational and $x\\ne y$, but $xy=1$, which is rational."},{"title":"Represent an odd integer","body":"Let $n=2q+1$, where $q$ is an integer."},{"title":"Substitute into the expression","body":"$n^3+3n+2=(2q+1)^3+3(2q+1)+2$."},{"title":"Expand and factor","body":"$n^3+3n+2=8q^3+12q^2+12q+6=2(4q^3+6q^2+6q+3)$."},{"title":"Show it is even","body":"The expression has a factor of $2$, so it is even."},{"title":"Show it is not a multiple of four","body":"The bracket $4q^3+6q^2+6q+3$ is odd, because the first three terms are even and $3$ is odd. Therefore the expression is $2$ times an odd integer, so it is not divisible by $4$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q10","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":10,"marks":4,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":[],"secondaryTopicNames":[],"topics":["01_Proof"],"topicNames":["Proof"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q10_M04_01_Proof.png","downloadName":"WMA12-01_Y2025_MayJune_Q10_M04_01_Proof.png","finalAnswer":"Proven.","steps":[{"title":"List the possible cases","body":"A positive integer that is not a multiple of $3$ must have the form $m=3q+1$ or $m=3q+2$."},{"title":"Case one","body":"If $m=3q+1$, then $m^2+3m+2=(3q+1)^2+3(3q+1)+2=9q^2+15q+6=3(3q^2+5q+2)$."},{"title":"Case two","body":"If $m=3q+2$, then $m^2+3m+2=(3q+2)^2+3(3q+2)+2=9q^2+21q+12=3(3q^2+7q+4)$."},{"title":"Conclude by exhaustion","body":"Both possible cases give a factor of $3$, so $m^2+3m+2$ is always a multiple of $3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q06","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":6,"marks":8,"topic":"01_Proof","topicName":"Proof","primaryTopic":"01_Proof","primaryTopicName":"Proof","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["01_Proof","11_ApplicationsOfDifferentiation"],"topicNames":["Proof","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q06_M08_01_Proof.png","downloadName":"WMA12-01_Y2026_Jan_Q06_M08_01_Proof.png","finalAnswer":"$(i)$ Proven. $\\quad (ii)$ $C$ has no stationary points.","steps":[{"title":"Represent the consecutive odd numbers","body":"Let $q=2n-1$ and $p=2n+1$, where $n$ is a positive integer. Then $p>q>0$ and the numbers are consecutive odd numbers."},{"title":"Subtract the squares","body":"$p^2-q^2=(2n+1)^2-(2n-1)^2$."},{"title":"Simplify the expression","body":"$p^2-q^2=(4n^2+4n+1)-(4n^2-4n+1)=8n$."},{"title":"Conclude the proof","body":"Since $n$ is an integer, $8n$ is a multiple of $8$, so $p^2-q^2$ is a multiple of $8$."},{"title":"Differentiate the curve","body":"For $y=x^3+12x^2+49x+2$, $\\dfrac{dy}{dx}=3x^2+24x+49$."},{"title":"Show the gradient is never zero","body":"$3x^2+24x+49=3(x+4)^2+1$. This is always positive for real $x$."},{"title":"State the conclusion","body":"Since $\\dfrac{dy}{dx}$ is never $0$, the curve has no stationary points."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q04","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":4,"marks":8,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q04_M08_02_Polynomials.png","downloadName":"WMA12-01_Y2019_Oct_Q04_M08_02_Polynomials.png","finalAnswer":"$(a)\\ -35.\\quad (b)\\ a=-17.\\quad (c)\\ f(x)=(3x-2)(x+2)(x-4)$.","steps":[{"title":"Use the remainder theorem","body":"When $f(x)$ is divided by $(x-3)$, the remainder is $f(3)$. Since $f(3)=(3-3)(3\\cdot3^2+3+a)-35$, the remainder is $-35$."},{"title":"Use the given factor","body":"Since $(3x-2)$ is a factor, $x=\\dfrac23$ is a root and $f\\left(\\dfrac23\\right)=0$."},{"title":"Solve for a","body":"$0=\\left(\\dfrac23-3\\right)\\left(3\\left(\\dfrac23\\right)^2+\\dfrac23+a\\right)-35=-\\dfrac73(a+2)-35$. Hence $-7(a+2)=105$, so $a=-17$."},{"title":"Substitute a into f(x)","body":"$f(x)=(x-3)(3x^2+x-17)-35=3x^3-8x^2-20x+16$."},{"title":"Divide by the known factor","body":"Dividing $3x^3-8x^2-20x+16$ by $(3x-2)$ gives $x^2-2x-8$."},{"title":"Factorise fully","body":"$x^2-2x-8=(x+2)(x-4)$, so $f(x)=(3x-2)(x+2)(x-4)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q03","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":3,"marks":8,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":["10_TrigonometricEquations"],"secondaryTopicNames":["Trigonometric Equations"],"topics":["02_Polynomials","10_TrigonometricEquations"],"topicNames":["Polynomials","Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q03_M08_02_Polynomials.png","downloadName":"WMA12-01_Y2020_Jan_Q03_M08_02_Polynomials.png","finalAnswer":"$(a)$ Proven. $\\quad (b)\\ f(x)=(2x+3)(3x-2)(x+2).\\quad (c)\\ \\theta=2.03,\\ 2.16$ radians.","steps":[{"title":"Use the factor theorem","body":"For $(2x+3)$, use $x=-\\dfrac32$. Substituting gives $f\\left(-\\dfrac32\\right)=6\\left(-\\dfrac32\\right)^3+17\\left(-\\dfrac32\\right)^2+4\\left(-\\dfrac32\\right)-12=0$."},{"title":"State the factor result","body":"Since $f\\left(-\\dfrac32\\right)=0$, $(2x+3)$ is a factor of $f(x)$."},{"title":"Divide by the known factor","body":"$6x^3+17x^2+4x-12=(2x+3)(3x^2+4x-4)$."},{"title":"Factorise the quadratic","body":"$3x^2+4x-4=(3x-2)(x+2)$, so $f(x)=(2x+3)(3x-2)(x+2)$."},{"title":"Use the factorisation for tan theta","body":"Let $t=\\tan\\theta$. Then $(2t+3)(3t-2)(t+2)=0$, so $t=-\\dfrac32$, $t=\\dfrac23$, or $t=-2$."},{"title":"Choose the roots in the interval","body":"For $\\dfrac\\pi2<\\theta<\\pi$, $\\tan\\theta$ is negative, so use $\\tan\\theta=-\\dfrac32$ and $\\tan\\theta=-2$."},{"title":"Find theta","body":"This gives $\\theta=\\pi-\\tan^{-1}\\left(\\dfrac32\\right)=2.16$ and $\\theta=\\pi-\\tan^{-1}(2)=2.03$, to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q01","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":1,"marks":6,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q01_M06_02_Polynomials.png","downloadName":"WMA12-01_Y2021_Jan_Q01_M06_02_Polynomials.png","finalAnswer":"$(a)$ Proven: $a+b=-1$. $\\quad (b)\\ a=-5,\\ b=4$.","steps":[{"title":"Use the first remainder","body":"Dividing by $(x+1)$ means use $x=-1$. Hence $f(-1)=1-a-3-b+5=3-a-b$."},{"title":"Show the required relation","body":"The remainder is $4$, so $3-a-b=4$. Therefore $a+b=-1$."},{"title":"Use the second remainder","body":"Dividing by $(x-2)$ means use $x=2$. Hence $f(2)=16+8a-12+2b+5=9+8a+2b$."},{"title":"Form the second equation","body":"The remainder is $-23$, so $9+8a+2b=-23$, which gives $4a+b=-16$."},{"title":"Solve simultaneously","body":"Subtract $a+b=-1$ from $4a+b=-16$ to get $3a=-15$, so $a=-5$."},{"title":"Find b","body":"Using $a+b=-1$, $-5+b=-1$, hence $b=4$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q04","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":4,"marks":8,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q04_M08_02_Polynomials.png","downloadName":"WMA12-01_Y2021_Oct_Q04_M08_02_Polynomials.png","finalAnswer":"$(a)\\ -21.\\quad (b)$ Proven. $\\quad (c)(i)\\ f(x)=(x-3)(2x^2+3x+5).\\quad (c)(ii)$ Only real root: $x=3$.","steps":[{"title":"Use the remainder theorem","body":"Dividing by $(2x-3)$ means use $x=\\dfrac32$."},{"title":"Find the remainder","body":"$f\\left(\\dfrac32\\right)=\\left(\\dfrac94-2\\right)(0)-21=-21$."},{"title":"Check x equals three","body":"$f(3)=(9-2)(6-3)-21=7\\cdot3-21=0$."},{"title":"Use the factor theorem","body":"Since $f(3)=0$, $(x-3)$ is a factor of $f(x)$."},{"title":"Expand f","body":"$f(x)=(x^2-2)(2x-3)-21=2x^3-3x^2-4x-15$."},{"title":"Factorise","body":"Dividing by $(x-3)$ gives $2x^2+3x+5$, so $f(x)=(x-3)(2x^2+3x+5)$."},{"title":"Check the quadratic roots","body":"For $2x^2+3x+5$, the discriminant is $3^2-4(2)(5)=9-40=-31<0$."},{"title":"Conclude","body":"The quadratic has no real roots, so $f(x)=0$ has only one real root, $x=3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q05","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":5,"marks":8,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q05_M08_02_Polynomials.png","downloadName":"WMA12-01_Y2022_Jan_Q05_M08_02_Polynomials.png","finalAnswer":"$(a)$ Proven: $11A+9B=83$. $\\quad (b)\\ A=-8,\\ B=19.\\quad (c)\\ g(x)=x^2-2x+5$.","steps":[{"title":"Use x equals one","body":"$f(1)=3+A+B-10=A+B-7$, so $k=A+B-7$."},{"title":"Use x equals negative one","body":"$f(-1)=-3+A-B-10=A-B-13$."},{"title":"Use the second remainder relation","body":"Since $f(-1)=-10k$, $A-B-13=-10(A+B-7)$."},{"title":"Show the relation","body":"Rearranging gives $11A+9B=83$."},{"title":"Use the factor","body":"Since $(3x-2)$ is a factor, $f\\left(\\dfrac23\\right)=0$."},{"title":"Form the second equation","body":"$3\\left(\\dfrac23\\right)^3+A\\left(\\dfrac23\\right)^2+B\\left(\\dfrac23\\right)-10=0$. Multiplying by $9$ gives $2A+3B=41$."},{"title":"Solve for A and B","body":"Solving $11A+9B=83$ with $2A+3B=41$ gives $A=-8$ and $B=19$."},{"title":"Divide by the factor","body":"With these values, $f(x)=3x^3-8x^2+19x-10=(3x-2)(x^2-2x+5)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q05","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":5,"marks":9,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q05_M09_02_Polynomials.png","downloadName":"WMA12-01_Y2023_Jan_Q05_M09_02_Polynomials.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ Proven. $\\quad (c)$ $p=6,\\ q=-105$. $\\quad (d)$ $g(x)=x^2+12x+35$.","steps":[{"title":"Use the factor theorem","body":"Since $(x-3)$ is a factor, $f(3)=0$."},{"title":"Substitute x equals three","body":"$27+9(p+3)-3+q=0$, so $51+9p+q=0$."},{"title":"Show the first relation","body":"Therefore $9p+q=-51$."},{"title":"Use the remainder theorem","body":"Dividing by $(x+p)$ means substituting $x=-p$. The remainder is $f(-p)$."},{"title":"Substitute x equals negative p","body":"$f(-p)=-p^3+(p+3)p^2+p+q=3p^2+p+q$."},{"title":"Show the second relation","body":"The remainder is $9$, so $3p^2+p+q=9$, hence $3p^2+p+q-9=0$."},{"title":"Eliminate q","body":"From $9p+q=-51$, $q=-51-9p$. Substitute into $3p^2+p+q-9=0$."},{"title":"Solve for p","body":"$3p^2+p-51-9p-9=0$, so $3p^2-8p-60=0$. This gives $p=6$ or $p=-\\dfrac{10}{3}$."},{"title":"Use p greater than zero","body":"Since $p>0$, $p=6$. Then $q=-51-9(6)=-105$."},{"title":"Form f with p and q","body":"$f(x)=x^3+9x^2-x-105$."},{"title":"Divide by x minus three","body":"$x^3+9x^2-x-105=(x-3)(x^2+12x+35)$, so $g(x)=x^2+12x+35$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q02","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":2,"marks":6,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q02_M06_02_Polynomials.png","downloadName":"WMA12-01_Y2023_MayJune_Q02_M06_02_Polynomials.png","finalAnswer":"$(a)$ $a=-3$. $\\quad (b)$ $f(x)=0$ has only one real root, $x=\\dfrac32$.","steps":[{"title":"Use the factor theorem","body":"Since $(2x-3)$ is a factor, $x=\\dfrac32$ is a root, so $f\\left(\\dfrac32\\right)=0$."},{"title":"Substitute the root","body":"$4\\left(\\dfrac32\\right)^3-8\\left(\\dfrac32\\right)^2+5\\left(\\dfrac32\\right)+a=0$."},{"title":"Find a","body":"$13.5-18+7.5+a=0$, so $3+a=0$ and $a=-3$."},{"title":"Write the polynomial","body":"With $a=-3$, $f(x)=4x^3-8x^2+5x-3$."},{"title":"Factor using the known factor","body":"$4x^3-8x^2+5x-3=(2x-3)(2x^2-x+1)$."},{"title":"Check the quadratic","body":"The discriminant of $2x^2-x+1$ is $(-1)^2-4(2)(1)=1-8=-7$."},{"title":"Conclude about real roots","body":"Since the quadratic has negative discriminant, it has no real roots. Therefore $f(x)=0$ has only the one real root from $2x-3=0$, namely $x=\\dfrac32$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q04","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":4,"marks":9,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q04_M09_02_Polynomials.png","downloadName":"WMA12-01_Y2023_Oct_Q04_M09_02_Polynomials.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $4a+b=1$. $\\quad (c)(i)$ $a=4,\\ b=-15$. $\\quad (c)(ii)$ $f(x)=(2x+1)(x-2)(2x+15)$.","steps":[{"title":"Use the factor theorem","body":"Since $(2x+1)$ is a factor, $x=-\\dfrac12$ is a root, so $f\\left(-\\dfrac12\\right)=0$."},{"title":"Substitute x equals negative half","body":"$4\\left(-\\dfrac12\\right)^3+a\\left(-\\dfrac12\\right)^2-29\\left(-\\dfrac12\\right)+b=0$."},{"title":"Show the first relation","body":"$-\\dfrac12+\\dfrac a4+\\dfrac{29}{2}+b=0$. Multiplying by $4$ gives $a+4b+56=0$, so $a+4b=-56$."},{"title":"Use the remainder theorem","body":"Dividing by $(x-2)$ gives remainder $f(2)$."},{"title":"Substitute x equals two","body":"$f(2)=4(8)+4a-58+b=4a+b-26$."},{"title":"Find the second relation","body":"The remainder is $-25$, so $4a+b-26=-25$, hence $4a+b=1$."},{"title":"Solve the simultaneous equations","body":"Solve $a+4b=-56$ and $4a+b=1$. Multiplying the second equation by $4$ gives $16a+4b=4$."},{"title":"Find a and b","body":"Subtracting $a+4b=-56$ from $16a+4b=4$ gives $15a=60$, so $a=4$. Then $16+b=1$, so $b=-15$."},{"title":"Write f(x)","body":"Therefore $f(x)=4x^3+4x^2-29x-15$."},{"title":"Factorise","body":"Using the known factors $(2x+1)$ and $(x-2)$, division gives $f(x)=(2x+1)(x-2)(2x+15)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q01","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":1,"marks":3,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q01_M03_02_Polynomials.png","downloadName":"WMA12-01_Y2024_Jan_Q01_M03_02_Polynomials.png","finalAnswer":"$a=\\dfrac58$.","steps":[{"title":"Use the remainder theorem","body":"Dividing by $(x-2)$ means the remainder is $f(2)$."},{"title":"Substitute x equals two","body":"$f(2)=a(2)^3+3(2)^2-8(2)+2=8a+12-16+2=8a-2$."},{"title":"Use the given remainder","body":"The remainder is $3$, so $8a-2=3$."},{"title":"Solve for a","body":"$8a=5$, hence $a=\\dfrac58$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q04","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":4,"marks":8,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q04_M08_02_Polynomials.png","downloadName":"WMA12-01_Y2024_MayJune_Q04_M08_02_Polynomials.png","finalAnswer":"$(a)$ $21$. $\\quad (b)$ $k=11$. $\\quad (c)(i)$ $(2x-1)(x^2+x+1)$. $\\quad (c)(ii)$ One real solution.","steps":[{"title":"Use the remainder theorem","body":"The remainder on division by $(x-2)$ is $f(2)$."},{"title":"Find f of two","body":"$f(2)=(2-2)(2(2)^2+5(2)+k)+21=21$."},{"title":"Use the factor theorem","body":"Since $(2x-1)$ is a factor, $x=\\dfrac12$ is a root, so $f\\left(\\dfrac12\\right)=0$."},{"title":"Substitute x equals half","body":"$\\left(\\dfrac12-2\\right)\\left(2\\left(\\dfrac12\\right)^2+5\\left(\\dfrac12\\right)+k\\right)+21=0$."},{"title":"Solve for k","body":"$-\\dfrac32(3+k)+21=0$. Multiplying by $2$ gives $-3(k+3)+42=0$, so $k=11$."},{"title":"Write f with k equals eleven","body":"$f(x)=(x-2)(2x^2+5x+11)+21=2x^3+x^2+x-1$."},{"title":"Factorise","body":"$2x^3+x^2+x-1=(2x-1)(x^2+x+1)$."},{"title":"Count real solutions","body":"The quadratic $x^2+x+1$ has discriminant $1-4=-3$, so it has no real roots. Therefore $f(x)=0$ has one real solution."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q03","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":3,"marks":7,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q03_M07_02_Polynomials.png","downloadName":"WMA12-01_Y2024_Oct_Q03_M07_02_Polynomials.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $A=-26$, $B=40$. $\\quad (c)$ $2x^2+13x+65$.","steps":[{"title":"Use the remainder theorem","body":"Dividing by $x+3$ leaves remainder $55$, so $f(-3)=55$."},{"title":"Show the given equation","body":"$f(-3)=2(-3)^3-(-3)^2-3A+B=-63-3A+B$. Therefore $-63-3A+B=55$, so $3A-B=-118$."},{"title":"Use the factor theorem","body":"Since $2x-5$ is a factor, $x=\\dfrac52$ is a root and $f\\left(\\dfrac52\\right)=0$."},{"title":"Form a second equation","body":"$2\\left(\\dfrac52\\right)^3-\\left(\\dfrac52\\right)^2+\\dfrac52A+B=0$, so $25+\\dfrac52A+B=0$. Multiplying by $2$ gives $5A+2B=-50$."},{"title":"Solve simultaneously","body":"From $3A-B=-118$, $B=3A+118$. Substitute into $5A+2B=-50$ to get $11A=-286$, so $A=-26$ and $B=40$."},{"title":"Write the polynomial","body":"$f(x)=2x^3-x^2-26x+40$."},{"title":"Divide by x minus seven","body":"$2x^3-x^2-26x+40=(x-7)(2x^2+13x+65)+495$, so the quotient is $2x^2+13x+65$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q05","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":5,"marks":9,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q05_M09_02_Polynomials.png","downloadName":"WMA12-01_Y2025_Jan_Q05_M09_02_Polynomials.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $a=-1$, $b=8$. $\\quad (c)$ $f(x)=(x-1)(x+2)(3x-4)$.","steps":[{"title":"Use the factor theorem","body":"Since $3x-4$ is a factor, $x=\\dfrac43$ is a root and $f\\left(\\dfrac43\\right)=0$."},{"title":"Show the given equation","body":"$3\\left(\\dfrac43\\right)^3+a\\left(\\dfrac43\\right)^2-10\\left(\\dfrac43\\right)+b=0$, so $\\dfrac{64}{9}+\\dfrac{16a}{9}-\\dfrac{120}{9}+b=0$. Multiplying by $9$ gives $16a+9b=56$."},{"title":"Use the remainder condition","body":"When dividing by $x-2$, the remainder is $f(2)$. Given that the remainder is $b$, $f(2)=b$."},{"title":"Find a","body":"$f(2)=24+4a-20+b=4+4a+b$. Thus $4+4a+b=b$, so $a=-1$."},{"title":"Find b","body":"Substitute $a=-1$ into $16a+9b=56$: $-16+9b=56$, so $b=8$."},{"title":"Write f of x","body":"$f(x)=3x^3-x^2-10x+8$."},{"title":"Find another factor","body":"$f(1)=3-1-10+8=0$, so $(x-1)$ is a factor."},{"title":"Fully factorise","body":"Dividing by $(x-1)$ gives $3x^2+2x-8=(3x-4)(x+2)$. Hence $f(x)=(x-1)(x+2)(3x-4)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q04","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":4,"marks":9,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q04_M09_02_Polynomials.png","downloadName":"WMA12-01_Y2025_MayJune_Q04_M09_02_Polynomials.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $a=2$, $b=8$. $\\quad (c)$ Quotient $2x^2+12x+29$, remainder $55$.","steps":[{"title":"Use the factor theorem","body":"Since $x+3$ is a factor, $f(-3)=0$."},{"title":"Show the relation","body":"$f(-3)=-27a+9b-15-3=0$, so $9b=27a+18$ and therefore $b=3a+2$."},{"title":"Use the remainder theorem","body":"When dividing by $2x-1$, substitute $x=\\dfrac12$. The remainder is $\\dfrac74$, so $f\\left(\\dfrac12\\right)=\\dfrac74$."},{"title":"Form the second equation","body":"$\\dfrac a8+\\dfrac b4+\\dfrac52-3=\\dfrac74$. Multiplying by $8$ gives $a+2b-4=14$, so $a+2b=18$."},{"title":"Solve for a and b","body":"Substitute $b=3a+2$ into $a+2b=18$: $a+6a+4=18$, so $a=2$ and $b=8$."},{"title":"Write f of x","body":"$f(x)=2x^3+8x^2+5x-3$."},{"title":"Divide by x minus two","body":"$2x^3+8x^2+5x-3=(x-2)(2x^2+12x+29)+55$."},{"title":"State the result","body":"The quotient is $2x^2+12x+29$ and the remainder is $55$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q04","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":4,"marks":12,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["02_Polynomials","11_ApplicationsOfDifferentiation"],"topicNames":["Polynomials","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q04_M12_02_Polynomials.png","downloadName":"WMA12-01_Y2025_Oct_Q04_M12_02_Polynomials.png","finalAnswer":"$(a)(i)$ $Q(x)=4x^2+21x+32$. $\\quad (a)(ii)$ $R=72$. $\\quad (b)$ Proven; only real solution is $x=-4$. $\\quad (c)$ $-\\dfrac52<x<\\dfrac13$.","steps":[{"title":"Divide by x minus two","body":"$4x^3+13x^2-10x+8=(x-2)(4x^2+21x+32)+72$."},{"title":"State Q and R","body":"Hence $Q(x)=4x^2+21x+32$ and $R=72$."},{"title":"Use the factor theorem","body":"$f(-4)=4(-4)^3+13(-4)^2-10(-4)+8=-256+208+40+8=0$."},{"title":"Show the factor","body":"Since $f(-4)=0$, $(x+4)$ is a factor of $f(x)$."},{"title":"Factor the cubic","body":"Dividing by $(x+4)$ gives $f(x)=(x+4)(4x^2-3x+2)$."},{"title":"Check the quadratic","body":"The discriminant of $4x^2-3x+2$ is $(-3)^2-4(4)(2)=9-32=-23<0$, so this quadratic has no real roots."},{"title":"Conclude the real solution","body":"Therefore $f(x)=0$ has only one real solution, $x=-4$."},{"title":"Differentiate","body":"$f'(x)=12x^2+26x-10=2(3x-1)(2x+5)$."},{"title":"Find where f is decreasing","body":"$f(x)$ is decreasing when $f'(x)<0$, which is between the roots. Hence $-\\dfrac52<x<\\dfrac13$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q03","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":3,"marks":7,"topic":"02_Polynomials","topicName":"Polynomials","primaryTopic":"02_Polynomials","primaryTopicName":"Polynomials","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_Polynomials"],"topicNames":["Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q03_M07_02_Polynomials.png","downloadName":"WMA12-01_Y2026_Jan_Q03_M07_02_Polynomials.png","finalAnswer":"$(i)\\ 574.\\quad (ii)\\ Q(x)=3x^2-12x+\\dfrac{15}{2},\\ R=-\\dfrac{29}{2}$.","steps":[{"title":"Use the factor theorem","body":"Since $(x+2)$ is a factor of $f(x)=4x^3+6x+k$, we have $f(-2)=0$."},{"title":"Find k","body":"$4(-2)^3+6(-2)+k=0$, so $-32-12+k=0$ and $k=44$."},{"title":"Find the required remainder","body":"The remainder on division by $(x-5)$ is $f(5)=4(5)^3+6(5)+44=574$."},{"title":"Set up the division","body":"Write $6x^3-15x^2-21x+8=(2x+3)(Ax^2+Bx+C)+R$."},{"title":"Match coefficients","body":"Comparing coefficients gives $A=3$, $B=-12$, and $C=\\dfrac{15}{2}$."},{"title":"Find the remainder","body":"Then $(2x+3)\\left(3x^2-12x+\\dfrac{15}{2}\\right)=6x^3-15x^2-21x+\\dfrac{45}{2}$, so $R=8-\\dfrac{45}{2}=-\\dfrac{29}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q06","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":6,"marks":7,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_Circles"],"topicNames":["Circles"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q06_M07_03_Circles.png","downloadName":"WMA12-01_Y2019_Oct_Q06_M07_03_Circles.png","finalAnswer":"$(a)\\ y=-2x+7.\\quad (b)\\ (x-4)^2+(y+1)^2=\\dfrac{36}{5}$.","steps":[{"title":"Use perpendicular gradients","body":"The tangent has gradient $\\dfrac12$, so the radius $PN$ has gradient $-2$."},{"title":"Find the equation of PN","body":"Line $PN$ passes through $N(4,-1)$, so $y+1=-2(x-4)$. Therefore $y=-2x+7$."},{"title":"Find point P","body":"At $P$, the tangent $y=\\dfrac12x$ meets the radius $y=-2x+7$. Thus $\\dfrac12x=-2x+7$, so $x=\\dfrac{14}{5}$ and $y=\\dfrac75$."},{"title":"Find the radius squared","body":"$r^2=\\left(\\dfrac{14}{5}-4\\right)^2+\\left(\\dfrac75+1\\right)^2=\\left(-\\dfrac65\\right)^2+\\left(\\dfrac{12}{5}\\right)^2=\\dfrac{36}{5}$."},{"title":"Write the circle equation","body":"With centre $(4,-1)$ and radius squared $\\dfrac{36}{5}$, the circle is $(x-4)^2+(y+1)^2=\\dfrac{36}{5}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q06","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":6,"marks":8,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["03_Circles","11_ApplicationsOfDifferentiation"],"topicNames":["Circles","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q06_M08_03_Circles.png","downloadName":"WMA12-01_Y2020_Jan_Q06_M08_03_Circles.png","finalAnswer":"$(a)(i)\\ (-3,2).\\quad (a)(ii)\\ 3\\sqrt3.\\quad (b)\\ k=2\\pm3\\sqrt3.\\quad (c)\\ p=2-\\sqrt{23}$.","steps":[{"title":"Complete the square","body":"$x^2+6x=(x+3)^2-9$ and $y^2-4y=(y-2)^2-4$."},{"title":"Find the centre and radius","body":"The circle becomes $(x+3)^2+(y-2)^2=27$. Hence the centre is $(-3,2)$ and the radius is $\\sqrt{27}=3\\sqrt3$."},{"title":"Use horizontal tangents","body":"A horizontal tangent has equation $y=k$. The possible tangent levels are one radius above and below the centre, so $k=2\\pm3\\sqrt3$."},{"title":"Use half the chord length","body":"The chord has length $4$, so half the chord is $2$. If the chord is $y=p$, its perpendicular distance from the centre is $|p-2|$."},{"title":"Apply Pythagoras","body":"$(p-2)^2+2^2=(3\\sqrt3)^2=27$, so $(p-2)^2=23$."},{"title":"Choose the negative value","body":"Since $p$ is negative, $p=2-\\sqrt{23}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q09","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":9,"marks":10,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["12_Integration","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Integration","Applications of Differentiation"],"topics":["03_Circles","12_Integration","11_ApplicationsOfDifferentiation"],"topicNames":["Circles","Integration","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q09_M10_03_Circles.png","downloadName":"WMA12-01_Y2021_Jan_Q09_M10_03_Circles.png","finalAnswer":"$(a)(i)\\ (k,2k).\\quad (a)(ii)\\ \\sqrt{k+7}.\\quad (b)(ii)\\ k=3\\text{ or }\\dfrac25.\\quad (c)\\ \\dfrac{147}{16}$.","steps":[{"title":"Read the centre and radius","body":"From $(x-k)^2+(y-2k)^2=k+7$, the centre is $(k,2k)$ and the radius is $\\sqrt{k+7}$."},{"title":"Substitute point P","body":"Since $P(2,3)$ lies on the circle, $(2-k)^2+(3-2k)^2=k+7$."},{"title":"Show the quadratic","body":"Expanding gives $k^2-4k+4+4k^2-12k+9=k+7$, hence $5k^2-17k+6=0$."},{"title":"Solve for k","body":"$5k^2-17k+6=(5k-2)(k-3)$, so $k=\\dfrac25$ or $k=3$."},{"title":"Use the condition k less than two","body":"For the tangent calculation, $k<2$, so the centre is $\\left(\\dfrac25,\\dfrac45\\right)$."},{"title":"Find the tangent gradient","body":"The radius from the centre to $P$ has gradient $\\dfrac{3-4/5}{2-2/5}=\\dfrac{11}{8}$, so the tangent gradient is $-\\dfrac8{11}$."},{"title":"Find the x intercept","body":"The tangent is $y-3=-\\dfrac8{11}(x-2)$. Setting $y=0$ gives $x=\\dfrac{49}{8}$, so $T=\\left(\\dfrac{49}{8},0\\right)$."},{"title":"Calculate the area","body":"Triangle $OPT$ has base $\\dfrac{49}{8}$ on the $x$-axis and height $3$, so its area is $\\dfrac12\\cdot\\dfrac{49}{8}\\cdot3=\\dfrac{147}{16}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q06","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":6,"marks":7,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["12_Integration","11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Integration","Applications of Differentiation"],"topics":["03_Circles","12_Integration","11_ApplicationsOfDifferentiation"],"topicNames":["Circles","Integration","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q06_M07_03_Circles.png","downloadName":"WMA12-01_Y2021_MayJune_Q06_M07_03_Circles.png","finalAnswer":"$(a)\\ k=9.\\quad (b)\\ 3\\sqrt7$.","steps":[{"title":"Complete the square","body":"$x^2-6x=(x-3)^2-9$ and $y^2+8y=(y+4)^2-16$."},{"title":"Write centre-radius form","body":"The circle becomes $(x-3)^2+(y+4)^2=25-k$."},{"title":"Use the tangent condition","body":"The centre is $(3,-4)$. Since the $x$-axis is tangent, the radius is the distance from the centre to the $x$-axis, which is $4$."},{"title":"Find k","body":"Thus $25-k=4^2=16$, so $k=9$."},{"title":"Find the intercepts","body":"With $k=9$, the circle is $(x-3)^2+(y+4)^2=16$. On the $x$-axis, $y=0$, giving $x=3$."},{"title":"Find the y-axis points","body":"On the $y$-axis, $x=0$, so $9+(y+4)^2=16$. Hence $y=-4\\pm\\sqrt7$."},{"title":"Calculate the triangle area","body":"The vertical base on the $y$-axis has length $2\\sqrt7$, and its perpendicular distance to $(3,0)$ is $3$. The area is $\\dfrac12(2\\sqrt7)(3)=3\\sqrt7$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q06","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":6,"marks":8,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_Circles"],"topicNames":["Circles"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q06_M08_03_Circles.png","downloadName":"WMA12-01_Y2021_Oct_Q06_M08_03_Circles.png","finalAnswer":"$(i)(a)\\ (-5,6).\\quad (i)(b)\\ k>-61.\\quad (ii)\\ p=3+\\sqrt{165}$.","steps":[{"title":"Complete the square","body":"$x^2+10x=(x+5)^2-25$ and $y^2-12y=(y-6)^2-36$."},{"title":"Write centre-radius form","body":"The circle becomes $(x+5)^2+(y-6)^2=k+61$."},{"title":"Read the centre","body":"The centre is $(-5,6)$."},{"title":"State the range for k","body":"For a circle with positive radius, $k+61>0$, so $k>-61$."},{"title":"Use the diameter property","body":"If $QR$ is a diameter and $P$ lies on the circle, then $\\angle QPR=90^\\circ$."},{"title":"Use perpendicular vectors","body":"So $(Q-P)\\cdot(R-P)=0$. With $P=(p,0)$, $Q=(-2,10)$, and $R=(8,-14)$, this gives $(-2-p,10)\\cdot(8-p,-14)=0$."},{"title":"Form the quadratic","body":"$(-2-p)(8-p)-140=0$, so $p^2-6p-156=0$."},{"title":"Choose the positive value","body":"$p=\\dfrac{6\\pm\\sqrt{660}}{2}=3\\pm\\sqrt{165}$. Since $p$ is positive, $p=3+\\sqrt{165}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q06","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":6,"marks":8,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["03_Circles","11_ApplicationsOfDifferentiation"],"topicNames":["Circles","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q06_M08_03_Circles.png","downloadName":"WMA12-01_Y2022_Jan_Q06_M08_03_Circles.png","finalAnswer":"$(a)$ Proven: $\\angle PQR=90^\\circ$. $\\quad (b)(i)\\ (8,-6).\\quad (b)(ii)\\ 25.\\quad (c)\\ 7x-24y+425=0$.","steps":[{"title":"Find the gradient QP","body":"The gradient of $QP$ is $\\dfrac{14-(-30)}{23-15}=\\dfrac{44}{8}=\\dfrac{11}{2}$."},{"title":"Find the gradient QR","body":"The gradient of $QR$ is $\\dfrac{-26-(-30)}{-7-15}=\\dfrac4{-22}=-\\dfrac2{11}$."},{"title":"Show the right angle","body":"The product of the two gradients is $-1$, so $QP$ is perpendicular to $QR$ and $\\angle PQR=90^\\circ$."},{"title":"Use the diameter","body":"Since the angle at $Q$ is a right angle, $PR$ is a diameter of the circle."},{"title":"Find the centre","body":"The centre is the midpoint of $P(23,14)$ and $R(-7,-26)$, so it is $(8,-6)$."},{"title":"Find the radius","body":"$PR=\\sqrt{30^2+40^2}=50$, so the radius is $25$."},{"title":"Find the farthest point from Q","body":"The greatest distance from $Q$ occurs at the point opposite $Q$ on the diameter through the centre. Thus $S=2(8,-6)-(15,-30)=(1,18)$."},{"title":"Find the tangent gradient","body":"The radius from the centre to $S$ has gradient $\\dfrac{18-(-6)}{1-8}=-\\dfrac{24}{7}$, so the tangent gradient is $\\dfrac7{24}$."},{"title":"Write the tangent equation","body":"$y-18=\\dfrac7{24}(x-1)$, which rearranges to $7x-24y+425=0$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q10","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":10,"marks":12,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["02_Polynomials"],"secondaryTopicNames":["Polynomials"],"topics":["03_Circles","02_Polynomials"],"topicNames":["Circles","Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q10_M12_03_Circles.png","downloadName":"WMA12-01_Y2022_MayJune_Q10_M12_03_Circles.png","finalAnswer":"$(a)$ Proven. $\\quad (b)\\ 5r^2=(k+1)^2$, so $p=1$. $\\quad (c)\\ k=\\dfrac{11}{4}$.","steps":[{"title":"Write the circle equation","body":"The circle has centre $(3,5)$ and radius $r$, so $(x-3)^2+(y-5)^2=r^2$."},{"title":"Substitute the line","body":"On the line, $y=2x+k$. Substitution gives $(x-3)^2+(2x+k-5)^2=r^2$."},{"title":"Expand","body":"$x^2-6x+9+4x^2+4kx-20x+k^2-10k+25-r^2=0$."},{"title":"Show the intersection equation","body":"Collecting terms gives $5x^2+(4k-26)x+k^2-10k+34-r^2=0$."},{"title":"Use tangency","body":"For a tangent, the quadratic has one repeated root, so its discriminant is zero."},{"title":"Set the discriminant to zero","body":"$(4k-26)^2-20(k^2-10k+34-r^2)=0$."},{"title":"Simplify","body":"This reduces to $20r^2-4k^2-8k-4=0$, hence $5r^2=(k+1)^2$. Therefore $p=1$."},{"title":"Find the tangent point x coordinate","body":"For the repeated root, $x_B=-\\dfrac{4k-26}{2\\cdot5}=\\dfrac{13-2k}{5}$."},{"title":"Use distance AB","body":"The point $A$ is $(0,k)$ and $B$ lies on a line of gradient $2$, so $AB=\\sqrt{x_B^2+(2x_B)^2}=\\sqrt5\\,x_B$."},{"title":"Use the radius relation","body":"From $5r^2=(k+1)^2$, $r=\\dfrac{k+1}{\\sqrt5}$ in the shown configuration."},{"title":"Apply AB equals two r","body":"$\\sqrt5\\left(\\dfrac{13-2k}{5}\\right)=2\\left(\\dfrac{k+1}{\\sqrt5}\\right)$."},{"title":"Solve for k","body":"Multiplying by $\\sqrt5$ gives $13-2k=2k+2$, so $k=\\dfrac{11}{4}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q09","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":9,"marks":12,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["11_ApplicationsOfDifferentiation","12_Integration"],"secondaryTopicNames":["Applications of Differentiation","Integration"],"topics":["03_Circles","11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Circles","Applications of Differentiation","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q09_M12_03_Circles.png","downloadName":"WMA12-01_Y2022_Oct_Q09_M12_03_Circles.png","finalAnswer":"$(a)$ $T=(3,5)$. $\\quad (b)$ $(x-3)^2+(y-5)^2=10$. $\\quad (c)$ $y=\\dfrac13x+\\dfrac{22}{3}$. $\\quad (d)$ $\\dfrac{28}{3}$.","steps":[{"title":"Differentiate the cubic","body":"For $y=x^3-5x^2+3x+14$, $\\dfrac{dy}{dx}=3x^2-10x+3$."},{"title":"Find stationary x values","body":"$3x^2-10x+3=0$ factors as $(3x-1)(x-3)=0$, so $x=\\dfrac13$ or $x=3$."},{"title":"Identify the minimum","body":"$\\dfrac{d^2y}{dx^2}=6x-10$. At $x=3$, this is positive, so the minimum turning point has $x=3$."},{"title":"Find T","body":"Substitute $x=3$: $y=27-45+9+14=5$. Hence $T=(3,5)$."},{"title":"Find A","body":"At $x=2$ on $C_1$, $y=8-20+6+14=8$, so $A=(2,8)$."},{"title":"Find the circle radius","body":"The centre of $C_2$ is $T=(3,5)$ and it passes through $A=(2,8)$. Thus $r^2=(2-3)^2+(8-5)^2=10$."},{"title":"Write the circle equation","body":"Therefore $C_2$ has equation $(x-3)^2+(y-5)^2=10$."},{"title":"Find the tangent gradient","body":"The radius $TA$ has gradient $\\dfrac{8-5}{2-3}=-3$, so the tangent at $A$ has gradient $\\dfrac13$."},{"title":"Write the tangent equation","body":"Using $A=(2,8)$, $y-8=\\dfrac13(x-2)$, so $y=\\dfrac13x+\\dfrac{22}{3}$."},{"title":"Set up the area","body":"From $x=0$ to $x=2$, the cubic is above the line. The required area is $\\displaystyle \\int_0^2 \\left[x^3-5x^2+3x+14-\\left(\\dfrac13x+\\dfrac{22}{3}\\right)\\right]dx$."},{"title":"Simplify the integrand","body":"The integrand is $x^3-5x^2+\\dfrac83x+\\dfrac{20}{3}$."},{"title":"Integrate","body":"$\\displaystyle \\left[\\dfrac{x^4}{4}-\\dfrac{5x^3}{3}+\\dfrac{4x^2}{3}+\\dfrac{20x}{3}\\right]_0^2=4-\\dfrac{40}{3}+\\dfrac{16}{3}+\\dfrac{40}{3}=\\dfrac{28}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q06","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":6,"marks":10,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["03_Circles","11_ApplicationsOfDifferentiation"],"topicNames":["Circles","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q06_M10_03_Circles.png","downloadName":"WMA12-01_Y2023_Jan_Q06_M10_03_Circles.png","finalAnswer":"$(a)(i)$ $(-4,2)$. $\\quad (a)(ii)$ $2\\sqrt5$. $\\quad (b)$ $P=(-6,-2)$. $\\quad (c)$ $y=2x+10$.","steps":[{"title":"Complete the square","body":"$x^2+y^2+8x-4y=0$ becomes $(x+4)^2-16+(y-2)^2-4=0$."},{"title":"Write the circle form","body":"So $(x+4)^2+(y-2)^2=20$."},{"title":"Read the centre and radius","body":"The centre is $(-4,2)$ and the radius is $\\sqrt{20}=2\\sqrt5$."},{"title":"Use the tangent gradient","body":"The tangent $x+2y+10=0$ has gradient $-\\dfrac12$."},{"title":"Find the radius gradient","body":"The radius to the point of contact is perpendicular to the tangent, so its gradient is $2$."},{"title":"Write the normal through the centre","body":"The radius line through the centre $(-4,2)$ is $y-2=2(x+4)$, so $y=2x+10$."},{"title":"Intersect with the tangent","body":"Substitute $y=2x+10$ into $x+2y+10=0$: $x+2(2x+10)+10=0$."},{"title":"Find P","body":"$5x+30=0$, so $x=-6$. Then $y=2(-6)+10=-2$, hence $P=(-6,-2)$."},{"title":"State the normal","body":"The normal at $P$ is the radius line already found, so its equation is $y=2x+10$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q03","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":3,"marks":7,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["03_Circles","11_ApplicationsOfDifferentiation"],"topicNames":["Circles","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q03_M07_03_Circles.png","downloadName":"WMA12-01_Y2023_MayJune_Q03_M07_03_Circles.png","finalAnswer":"$(a)(i)$ $10$. $\\quad (a)(ii)$ $(x-2)^2+(y-5)^2=100$. $\\quad (b)$ $3x-4y-36=0$.","steps":[{"title":"Use the distance formula","body":"The centre is $(2,5)$ and $P=(8,-3)$. The radius is $\\sqrt{(8-2)^2+(-3-5)^2}$."},{"title":"Find the radius","body":"$r=\\sqrt{6^2+(-8)^2}=\\sqrt{100}=10$."},{"title":"Write the circle equation","body":"With centre $(2,5)$ and radius $10$, the circle is $(x-2)^2+(y-5)^2=100$."},{"title":"Find the radius gradient","body":"The gradient of the radius from the centre to $P$ is $\\dfrac{-3-5}{8-2}=\\dfrac{-8}{6}=-\\dfrac43$."},{"title":"Find the tangent gradient","body":"The tangent is perpendicular to the radius, so its gradient is $\\dfrac34$."},{"title":"Use point P","body":"The tangent through $(8,-3)$ is $y+3=\\dfrac34(x-8)$."},{"title":"Put into integer form","body":"Multiplying by $4$ gives $4y+12=3x-24$, hence $3x-4y-36=0$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q07","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":7,"marks":8,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["03_Circles","11_ApplicationsOfDifferentiation"],"topicNames":["Circles","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q07_M08_03_Circles.png","downloadName":"WMA12-01_Y2023_Oct_Q07_M08_03_Circles.png","finalAnswer":"$(a)$ Proven. $\\quad (b)(i)$ $N=(9,-5)$. $\\quad (b)(ii)$ $(x-4)^2+(y+3)^2=29$.","steps":[{"title":"Use perpendicular gradients","body":"The tangent $l$ has gradient $\\dfrac52$, so the radius $XN$ is perpendicular to it and has gradient $-\\dfrac25$."},{"title":"Use the centre","body":"The line through $X(4,-3)$ with gradient $-\\dfrac25$ is $y+3=-\\dfrac25(x-4)$."},{"title":"Show the required line","body":"Multiplying by $5$ gives $5y+15=-2x+8$, so $2x+5y+7=0$."},{"title":"Intersect the radius and tangent","body":"Use $y=\\dfrac52x-\\dfrac{55}{2}$ in $2x+5y+7=0$."},{"title":"Find x coordinate","body":"$2x+5\\left(\\dfrac52x-\\dfrac{55}{2}\\right)+7=0$. Multiplying by $2$ gives $4x+25x-275+14=0$, so $29x=261$ and $x=9$."},{"title":"Find y coordinate","body":"$y=\\dfrac52(9)-\\dfrac{55}{2}=\\dfrac{45-55}{2}=-5$, so $N=(9,-5)$."},{"title":"Find the radius squared","body":"$XN^2=(9-4)^2+(-5+3)^2=5^2+(-2)^2=29$."},{"title":"Write the circle equation","body":"With centre $(4,-3)$ and radius squared $29$, the circle is $(x-4)^2+(y+3)^2=29$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q03","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":3,"marks":6,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_Circles"],"topicNames":["Circles"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q03_M06_03_Circles.png","downloadName":"WMA12-01_Y2024_Jan_Q03_M06_03_Circles.png","finalAnswer":"$(a)$ $(x-3)^2+(y-5)^2=169$. $\\quad (b)$ $y=14$.","steps":[{"title":"Find the radius squared","body":"The centre is $A(3,5)$ and the circle passes through $B(8,-7)$, so $r^2=(8-3)^2+(-7-5)^2=25+144=169$."},{"title":"Write the circle equation","body":"Hence $C$ has equation $(x-3)^2+(y-5)^2=169$."},{"title":"Use the horizontal chord","body":"Since $MN$ is parallel to the $x$-axis, its equation has the form $y=c$."},{"title":"Use half the chord length","body":"The chord length is $4\\sqrt{22}$, so the half-length is $2\\sqrt{22}$."},{"title":"Relate chord length to the circle","body":"At height $y=c$, the horizontal half-length satisfies $169-(c-5)^2=(2\\sqrt{22})^2=88$."},{"title":"Solve for c","body":"$(c-5)^2=81$, so $c=14$ or $c=-4$."},{"title":"Use the position above the x-axis","body":"The chord lies above the $x$-axis, so $c=14$. Therefore the line through $M$ and $N$ is $y=14$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q07","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":7,"marks":6,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["01_Proof"],"secondaryTopicNames":["Proof"],"topics":["03_Circles","01_Proof"],"topicNames":["Circles","Proof"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q07_M06_03_Circles.png","downloadName":"WMA12-01_Y2024_MayJune_Q07_M06_03_Circles.png","finalAnswer":"$(a)(i)$ $(-4,5)$. $\\quad (a)(ii)$ $\\sqrt{70}$. $\\quad (b)$ The circles neither touch nor intersect.","steps":[{"title":"Complete the square","body":"$x^2+y^2+8x-10y=29$ becomes $(x+4)^2-16+(y-5)^2-25=29$."},{"title":"Write circle C1 in standard form","body":"$(x+4)^2+(y-5)^2=70$."},{"title":"Read centre and radius","body":"The centre of $C_1$ is $(-4,5)$ and its radius is $\\sqrt{70}$."},{"title":"Read C2","body":"$C_2$ has equation $(x-5)^2+(y+8)^2=52$, so its centre is $(5,-8)$ and its radius is $\\sqrt{52}=2\\sqrt{13}$."},{"title":"Find distance between centres","body":"The distance between $(-4,5)$ and $(5,-8)$ is $\\sqrt{9^2+(-13)^2}=\\sqrt{250}=5\\sqrt{10}$."},{"title":"Compare with radii","body":"$\\sqrt{70}+2\\sqrt{13}=15.58\\ldots$, while $5\\sqrt{10}=15.81\\ldots$."},{"title":"Conclude","body":"The distance between centres is greater than the sum of the radii, so the circles are separate. Therefore they neither touch nor intersect."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q03","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":3,"marks":5,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_Circles"],"topicNames":["Circles"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q03_M05_03_Circles.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q03_M05_03_Circles.png","finalAnswer":"$(a)(i)$ $(-4,7)$. $\\quad (a)(ii)$ $12$. $\\quad (b)$ $12-\\sqrt{65}$.","steps":[{"title":"Complete the square","body":"$x^2+y^2+8x-14y-79=0$ becomes $(x+4)^2-16+(y-7)^2-49-79=0$."},{"title":"Write standard form","body":"$(x+4)^2+(y-7)^2=144$."},{"title":"Read centre and radius","body":"The centre is $(-4,7)$ and the radius is $12$."},{"title":"Find distance from centre to origin","body":"The distance from $(-4,7)$ to $O(0,0)$ is $\\sqrt{(-4)^2+7^2}=\\sqrt{65}$."},{"title":"Use origin inside the circle","body":"Since $\\sqrt{65}<12$, the origin is inside the circle."},{"title":"Find nearest distance to the circle","body":"The nearest point on the circle lies along the line from the centre to the origin, so $OP=12-\\sqrt{65}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q10","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":10,"marks":10,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["03_Circles","11_ApplicationsOfDifferentiation"],"topicNames":["Circles","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q10_M10_03_Circles.png","downloadName":"WMA12-01_Y2024_Oct_Q10_M10_03_Circles.png","finalAnswer":"$(a)(i)$ $(-2,15)$. $\\quad (a)(ii)$ $2\\sqrt5$. $\\quad (b)$ Proven. $\\quad (c)$ $(-6,13)$ and $\\left(\\dfrac{12}{5},\\dfrac{71}{5}\\right)$.","steps":[{"title":"Complete the square","body":"$x^2+y^2+4x-30y+209=0$ becomes $(x+2)^2+(y-15)^2=20$."},{"title":"Read the centre and radius","body":"The centre is $(-2,15)$ and the radius is $\\sqrt{20}=2\\sqrt5$."},{"title":"Use the tangent distance","body":"The line $y=mx+1$ can be written as $mx-y+1=0$. Its distance from $(-2,15)$ must be $2\\sqrt5$."},{"title":"Set up the equation for m","body":"$\\dfrac{|m(-2)-15+1|}{\\sqrt{m^2+1}}=2\\sqrt5$, so $\\dfrac{|-2m-14|}{\\sqrt{m^2+1}}=2\\sqrt5$."},{"title":"Show the quadratic","body":"Squaring gives $4(m+7)^2=20(m^2+1)$. Hence $(m+7)^2=5(m^2+1)$, so $2m^2-7m-22=0$."},{"title":"Find the possible gradients","body":"$2m^2-7m-22=0$ gives $m=-2$ or $m=\\dfrac{11}{2}$."},{"title":"Use perpendicular radii","body":"A tangent is perpendicular to the radius at the point of contact."},{"title":"Find the first point","body":"For $m=-2$, the radius gradient is $\\dfrac12$. The radius through the centre is $y-15=\\dfrac12(x+2)$. Solving with $y=-2x+1$ gives $x=-6$ and $y=13$."},{"title":"Find the second point","body":"For $m=\\dfrac{11}{2}$, the radius gradient is $-\\dfrac2{11}$. The radius through the centre is $y-15=-\\dfrac2{11}(x+2)$. Solving with $y=\\dfrac{11}{2}x+1$ gives $x=\\dfrac{12}{5}$ and $y=\\dfrac{71}{5}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q06","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":6,"marks":8,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_Circles"],"topicNames":["Circles"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q06_M08_03_Circles.png","downloadName":"WMA12-01_Y2025_Jan_Q06_M08_03_Circles.png","finalAnswer":"$(a)$ $y=-3x+19$. $\\quad (b)$ $k=-2$. $\\quad (c)$ $(x-7)^2+(y+2)^2=80$.","steps":[{"title":"Find the midpoint","body":"For $A(-1,2)$ and $B(11,6)$, the midpoint is $M\\left(\\dfrac{-1+11}{2},\\dfrac{2+6}{2}\\right)=(5,4)$."},{"title":"Find the gradient of AB","body":"The gradient of $AB$ is $\\dfrac{6-2}{11-(-1)}=\\dfrac{4}{12}=\\dfrac13$."},{"title":"Use the perpendicular bisector","body":"The centre lies on the perpendicular bisector of the chord $AB$, so line $l$ has gradient $-3$ and passes through $M(5,4)$."},{"title":"Find line l","body":"$y-4=-3(x-5)$, so $y=-3x+19$."},{"title":"Use the centre coordinates","body":"Since $P=(7,k)$ lies on $l$, $k=-3(7)+19=-2$."},{"title":"Find the radius squared","body":"The centre is $(7,-2)$. Using point $A$, $r^2=(7-(-1))^2+(-2-2)^2=8^2+(-4)^2=80$."},{"title":"Write the circle equation","body":"Therefore the circle is $(x-7)^2+(y+2)^2=80$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q02","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":2,"marks":7,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_Circles"],"topicNames":["Circles"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q02_M07_03_Circles.png","downloadName":"WMA12-01_Y2025_MayJune_Q02_M07_03_Circles.png","finalAnswer":"$(a)$ $(x-1)^2+(y-10)^2=34$. $\\quad (b)$ $\\left(1,10-\\sqrt{34}\\right)$.","steps":[{"title":"Find the centre","body":"The centre is the midpoint of $(-2,5)$ and $(4,15)$, so it is $\\left(\\dfrac{-2+4}{2},\\dfrac{5+15}{2}\\right)=(1,10)$."},{"title":"Find the radius squared","body":"Using $(-2,5)$, $r^2=(-2-1)^2+(5-10)^2=9+25=34$."},{"title":"Write the circle equation","body":"Therefore $C$ has equation $(x-1)^2+(y-10)^2=34$."},{"title":"Find the nearest point to the x axis","body":"The nearest point to the $x$-axis is vertically below the centre by one radius."},{"title":"Write the coordinates","body":"The radius is $\\sqrt{34}$, so the point is $\\left(1,10-\\sqrt{34}\\right)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q06","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":6,"marks":9,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_Circles"],"topicNames":["Circles"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q06_M09_03_Circles.png","downloadName":"WMA12-01_Y2025_Oct_Q06_M09_03_Circles.png","finalAnswer":"$(a)$ $(x-6)^2+(y-12)^2=100$. $\\quad (b)$ $x^2+y^2=280-120\\sqrt5$ or $x^2+y^2=280+120\\sqrt5$.","steps":[{"title":"Find the centre of C one","body":"Since $AB$ is a diameter, the centre is the midpoint of $A(-2,18)$ and $B(14,6)$. This is $(6,12)$."},{"title":"Find the radius squared","body":"Using $A(-2,18)$, $r^2=(-2-6)^2+(18-12)^2=64+36=100$."},{"title":"Write C one","body":"Therefore $C_1$ has equation $(x-6)^2+(y-12)^2=100$."},{"title":"Find the centre distance","body":"The distance from the origin to $(6,12)$ is $\\sqrt{6^2+12^2}=6\\sqrt5$."},{"title":"Find possible radii for C two","body":"Since $C_1$ has radius $10$, a circle centred at the origin can touch it with radius $6\\sqrt5-10$ or $6\\sqrt5+10$."},{"title":"Write the equations","body":"Thus $C_2$ can be $x^2+y^2=(6\\sqrt5-10)^2=280-120\\sqrt5$ or $x^2+y^2=(6\\sqrt5+10)^2=280+120\\sqrt5$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q05","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":5,"marks":6,"topic":"03_Circles","topicName":"Circles","primaryTopic":"03_Circles","primaryTopicName":"Circles","secondaryTopics":[],"secondaryTopicNames":[],"topics":["03_Circles"],"topicNames":["Circles"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q05_M06_03_Circles.png","downloadName":"WMA12-01_Y2026_Jan_Q05_M06_03_Circles.png","finalAnswer":"$(a)(i)\\ (3,-\\dfrac52).\\quad (a)(ii)\\ \\dfrac{15}{2}.\\quad (b)\\ k=5\\sqrt6-3$.","steps":[{"title":"Complete the square","body":"$x^2-6x=(x-3)^2-9$ and $y^2+5y=\\left(y+\\dfrac52\\right)^2-\\dfrac{25}{4}$."},{"title":"Write the circle in centre-radius form","body":"The equation becomes $(x-3)^2+\\left(y+\\dfrac52\\right)^2=\\dfrac{225}{4}$."},{"title":"Read the centre and radius","body":"The centre is $\\left(3,-\\dfrac52\\right)$ and the radius is $\\sqrt{\\dfrac{225}{4}}=\\dfrac{15}{2}$."},{"title":"Use the touching condition","body":"The centre of $C_2$ is $(-k,0)$ and its radius is $5$. Since the circles touch externally, the distance between centres is $\\dfrac{15}{2}+5=\\dfrac{25}{2}$."},{"title":"Solve for k","body":"$(k+3)^2+\\left(\\dfrac52\\right)^2=\\left(\\dfrac{25}{2}\\right)^2$, so $(k+3)^2=150$. Since $k>0$, $k+3=5\\sqrt6$, hence $k=5\\sqrt6-3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q03","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":3,"marks":6,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q03_M06_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2019_Oct_Q03_M06_04_BinomialExpansion.png","finalAnswer":"$(a)\\ 1+3x+\\dfrac{33}{8}x^2+\\dfrac{55}{16}x^3.\\quad (b)\\ \\dfrac{77}{8}$.","steps":[{"title":"Write the binomial terms","body":"$(1+\\dfrac{x}{4})^{12}=1+\\binom{12}{1}\\dfrac{x}{4}+\\binom{12}{2}\\left(\\dfrac{x}{4}\\right)^2+\\binom{12}{3}\\left(\\dfrac{x}{4}\\right)^3+\\cdots$."},{"title":"Simplify the first four terms","body":"This gives $1+3x+\\dfrac{33}{8}x^2+\\dfrac{55}{16}x^3$."},{"title":"Rewrite the prefactor","body":"$\\dfrac{x^2+8}{x^5}=x^{-3}+8x^{-5}$."},{"title":"Find the constant contributions","body":"The $x^{-3}$ part needs the $x^3$ coefficient, which is $\\dfrac{55}{16}$. The $8x^{-5}$ part needs the $x^5$ coefficient, which is $8\\binom{12}{5}\\left(\\dfrac14\\right)^5=8\\cdot\\dfrac{99}{128}=\\dfrac{99}{16}$."},{"title":"Add the constant terms","body":"The term independent of $x$ is $\\dfrac{55}{16}+\\dfrac{99}{16}=\\dfrac{154}{16}=\\dfrac{77}{8}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q02","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":2,"marks":7,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q02_M07_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2020_Jan_Q02_M07_04_BinomialExpansion.png","finalAnswer":"$(a)\\ a=\\pm\\sqrt2.\\quad (b)\\ 17$.","steps":[{"title":"Identify the x to the fourth term","body":"In $(3+ax)^6$, the $x^4$ term is $\\binom64 3^2(ax)^4$."},{"title":"Form the equation for a","body":"$\\binom64 3^2a^4x^4=15\\cdot9a^4x^4=135a^4x^4$. Since this term is $540x^4$, $135a^4=540$."},{"title":"Solve for a","body":"$a^4=4$, so the real possible values are $a=\\sqrt2$ or $a=-\\sqrt2$."},{"title":"Find the constant contribution from 1 over 81","body":"The constant term from $\\dfrac1{81}(3+ax)^6$ is $\\dfrac1{81}\\cdot3^6=9$."},{"title":"Find the constant contribution from x to the minus six","body":"The $x^6$ term in $(3+ax)^6$ is $a^6x^6$. Since $a=\\pm\\sqrt2$, $a^6=8$, so $\\dfrac1{x^6}\\cdot a^6x^6$ contributes $8$."},{"title":"Add the constant terms","body":"The term independent of $x$ is $9+8=17$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q04","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":4,"marks":8,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q04_M08_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2021_Jan_Q04_M08_04_BinomialExpansion.png","finalAnswer":"$(a)\\ 64+192px+240p^2x^2.\\quad (b)\\ p=\\dfrac18\\text{ or }p=\\dfrac1{120}$.","steps":[{"title":"Write the first binomial terms","body":"$(2+px)^6=2^6+\\binom61 2^5(px)+\\binom62 2^4(px)^2+\\cdots$."},{"title":"Simplify the expansion","body":"The first three terms are $64+192px+240p^2x^2$."},{"title":"Find the coefficient of x squared","body":"In $(3-\\dfrac12x)(2+px)^6$, the $x^2$ coefficient is $3(240p^2)-\\dfrac12(192p)$."},{"title":"Form the equation","body":"So $720p^2-96p=-\\dfrac34$."},{"title":"Solve the quadratic","body":"Multiplying by $4$ gives $2880p^2-384p+3=0$, or $960p^2-128p+1=0$."},{"title":"State the values of p","body":"$p=\\dfrac{128\\pm112}{1920}$, so $p=\\dfrac18$ or $p=\\dfrac1{120}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q04","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":4,"marks":8,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q04_M08_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2021_MayJune_Q04_M08_04_BinomialExpansion.png","finalAnswer":"$(a)\\ 8192+6656x+2496x^2+572x^3.\\quad (b)\\ 8883.132.\\quad (c)$ Underestimate.","steps":[{"title":"Write the binomial terms","body":"$(2+\\dfrac{x}{8})^{13}=2^{13}+\\binom{13}{1}2^{12}\\dfrac{x}{8}+\\binom{13}{2}2^{11}\\left(\\dfrac{x}{8}\\right)^2+\\binom{13}{3}2^{10}\\left(\\dfrac{x}{8}\\right)^3+\\cdots$."},{"title":"Simplify the expansion","body":"This gives $8192+6656x+2496x^2+572x^3+\\cdots$."},{"title":"Match the value","body":"Since $2.0125=2+0.0125=2+\\dfrac{0.1}{8}$, use $x=0.1$ in the expansion."},{"title":"Calculate the approximation","body":"$8192+6656(0.1)+2496(0.1)^2+572(0.1)^3=8883.132$."},{"title":"Decide the direction","body":"The next terms in the expansion are positive because $x=0.1>0$, so stopping after the $x^3$ term gives an underestimate."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q01","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":1,"marks":6,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q01_M06_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2021_Oct_Q01_M06_04_BinomialExpansion.png","finalAnswer":"$(a)(i)\\ k=-\\dfrac14.\\quad (a)(ii)\\ p=\\dfrac{15}{2}.\\quad (b)\\ -125x^2$.","steps":[{"title":"Compare the linear term","body":"In $(1+kx)^{16}$, the coefficient of $x$ is $16k$."},{"title":"Find k","body":"Since the coefficient of $x$ is $-4$, $16k=-4$, so $k=-\\dfrac14$."},{"title":"Find p","body":"The coefficient of $x^2$ is $\\binom{16}{2}k^2=120\\left(\\dfrac1{16}\\right)=\\dfrac{15}{2}$."},{"title":"Find the needed binomial terms","body":"For $k=-\\dfrac14$, the $x^2$ coefficient in $(1+kx)^{16}$ is $\\dfrac{15}{2}$ and the $x^3$ coefficient is $\\binom{16}{3}\\left(-\\dfrac14\\right)^3=-\\dfrac{35}{4}$."},{"title":"Build the x squared term in g","body":"In $g(x)=\\left(2+\\dfrac{16}{x}\\right)(1+kx)^{16}$, the $x^2$ term comes from $2\\left(\\dfrac{15}{2}x^2\\right)$ and $\\dfrac{16}{x}\\left(-\\dfrac{35}{4}x^3\\right)$."},{"title":"Simplify","body":"The required term is $15x^2-140x^2=-125x^2$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q03","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":3,"marks":7,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q03_M07_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2022_Jan_Q03_M07_04_BinomialExpansion.png","finalAnswer":"$(a)\\ 256-256kx+112k^2x^2-28k^3x^3.\\quad (b)\\ k=-\\dfrac{14}{15}$.","steps":[{"title":"Write the first terms","body":"$(2-\\dfrac{kx}{4})^8=2^8+\\binom81 2^7\\left(-\\dfrac{kx}{4}\\right)+\\binom82 2^6\\left(-\\dfrac{kx}{4}\\right)^2+\\binom83 2^5\\left(-\\dfrac{kx}{4}\\right)^3+\\cdots$."},{"title":"Simplify the expansion","body":"The first four terms are $256-256kx+112k^2x^2-28k^3x^3$."},{"title":"Find the constant term in f","body":"For $f(x)=(5-3x)(2-\\dfrac{kx}{4})^8$, the constant term is $5(256)=1280$."},{"title":"Find the coefficient of x","body":"The coefficient of $x$ is $5(-256k)-3(256)=-1280k-768$."},{"title":"Use the condition","body":"The constant term is $3$ times the coefficient of $x$, so $1280=3(-1280k-768)$."},{"title":"Solve for k","body":"$1280=-3840k-2304$, hence $k=-\\dfrac{3584}{3840}=-\\dfrac{14}{15}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q01","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":1,"marks":4,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q01_M04_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2022_MayJune_Q01_M04_04_BinomialExpansion.png","finalAnswer":"$1024+1920x+1620x^2+810x^3$.","steps":[{"title":"Write the binomial terms","body":"$(2+\\dfrac38x)^{10}=2^{10}+\\binom{10}{1}2^9\\left(\\dfrac38x\\right)+\\binom{10}{2}2^8\\left(\\dfrac38x\\right)^2+\\binom{10}{3}2^7\\left(\\dfrac38x\\right)^3+\\cdots$."},{"title":"Simplify the constant and linear terms","body":"$2^{10}=1024$ and $\\binom{10}{1}2^9\\left(\\dfrac38\\right)x=1920x$."},{"title":"Simplify the quadratic term","body":"$\\binom{10}{2}2^8\\left(\\dfrac38\\right)^2x^2=1620x^2$."},{"title":"Simplify the cubic term","body":"$\\binom{10}{3}2^7\\left(\\dfrac38\\right)^3x^3=810x^3$."},{"title":"State the expansion","body":"The first four terms are $1024+1920x+1620x^2+810x^3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q02","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":2,"marks":7,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["04_BinomialExpansion","11_ApplicationsOfDifferentiation"],"topicNames":["Binomial Expansion","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q02_M07_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2022_Oct_Q02_M07_04_BinomialExpansion.png","finalAnswer":"$(a)$ $k=\\dfrac25$. $\\quad (b)\\ 32-32x+\\dfrac{64}{5}x^2$. $\\quad (c)\\ -32$.","steps":[{"title":"Use the remainder theorem","body":"Dividing by $4x-5$ means the remainder is $f\\left(\\dfrac54\\right)$."},{"title":"Substitute x equals five quarters","body":"$f\\left(\\dfrac54\\right)=\\left(2-\\dfrac{5k}{4}\\right)^5=\\dfrac{243}{32}$."},{"title":"Take the fifth root","body":"Since $\\dfrac{243}{32}=\\left(\\dfrac32\\right)^5$, we have $2-\\dfrac{5k}{4}=\\dfrac32$."},{"title":"Find k","body":"$\\dfrac{5k}{4}=\\dfrac12$, so $k=\\dfrac25$."},{"title":"Expand the binomial","body":"With $k=\\dfrac25$, $f(x)=\\left(2-\\dfrac25x\\right)^5$."},{"title":"Find the first three terms","body":"$2^5+5(2^4)\\left(-\\dfrac25x\\right)+10(2^3)\\left(-\\dfrac25x\\right)^2=32-32x+\\dfrac{64}{5}x^2$."},{"title":"Use the coefficient of x","body":"For a polynomial, the gradient at $x=0$ is the coefficient of $x$ in the expansion. Therefore $f'(0)=-32$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q03","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":3,"marks":7,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":["05_ArithmeticSequences"],"secondaryTopicNames":["Arithmetic Sequences"],"topics":["04_BinomialExpansion","05_ArithmeticSequences"],"topicNames":["Binomial Expansion","Arithmetic Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q03_M07_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2023_Jan_Q03_M07_04_BinomialExpansion.png","finalAnswer":"$(a)$ $128+56kx+\\dfrac{21}{2}k^2x^2+\\dfrac{35}{32}k^3x^3$. $\\quad (b)$ $k=\\dfrac{16}{5}$ or $k=16$.","steps":[{"title":"Start the binomial expansion","body":"$\\left(2+\\dfrac{kx}{8}\\right)^7$ begins with $2^7+7(2^6)\\left(\\dfrac{kx}{8}\\right)+\\binom72(2^5)\\left(\\dfrac{kx}{8}\\right)^2+\\binom73(2^4)\\left(\\dfrac{kx}{8}\\right)^3$."},{"title":"Simplify the terms","body":"This gives $128+56kx+\\dfrac{21}{2}k^2x^2+\\dfrac{35}{32}k^3x^3$."},{"title":"Use the arithmetic progression condition","body":"The coefficients of $x$, $x^2$ and $x^3$ are $56k$, $\\dfrac{21}{2}k^2$ and $\\dfrac{35}{32}k^3$."},{"title":"Set middle twice","body":"For three terms in an arithmetic progression, twice the middle term equals the sum of the outer terms: $21k^2=56k+\\dfrac{35}{32}k^3$."},{"title":"Use k non-zero","body":"Since $k\\ne0$, divide by $k$ and multiply by $32$: $672k=1792+35k^2$."},{"title":"Solve the quadratic","body":"So $35k^2-672k+1792=0$. The discriminant is $672^2-4(35)(1792)=200704=448^2$."},{"title":"Find the possible values","body":"$k=\\dfrac{672\\pm448}{70}$, giving $k=16$ or $k=\\dfrac{16}{5}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q04","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":4,"marks":7,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["04_BinomialExpansion","12_Integration"],"topicNames":["Binomial Expansion","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q04_M07_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2023_MayJune_Q04_M07_04_BinomialExpansion.png","finalAnswer":"$(a)$ $A=243$. $\\quad (b)(i)$ $p=-\\dfrac12$. $\\quad (b)(ii)$ $C=\\dfrac{135}{2}$.","steps":[{"title":"Find the constant term","body":"In $(3+px)^5$, the constant term is $3^5=243$, so $A=243$."},{"title":"Find B","body":"The coefficient of $x$ is $5(3^4)p=405p$, so $B=405p$."},{"title":"Find D","body":"The coefficient of $x^3$ is $\\binom53(3^2)p^3=10\\cdot9p^3=90p^3$, so $D=90p^3$."},{"title":"Use B equals 18D","body":"$405p=18(90p^3)=1620p^3$."},{"title":"Solve for p","body":"Since $p<0$, $p\\ne0$. Divide by $405p$ to get $1=4p^2$, so $p=\\pm\\dfrac12$. Therefore $p=-\\dfrac12$."},{"title":"Find C","body":"The coefficient of $x^2$ is $\\binom52(3^3)p^2=10\\cdot27\\cdot\\dfrac14=\\dfrac{135}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q10","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":10,"marks":12,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":["06_GeometricSequences","10_TrigonometricEquations"],"secondaryTopicNames":["Geometric Sequences","Trigonometric Equations"],"topics":["04_BinomialExpansion","06_GeometricSequences","10_TrigonometricEquations"],"topicNames":["Binomial Expansion","Geometric Sequences","Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q10_M12_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2023_Oct_Q10_M12_04_BinomialExpansion.png","finalAnswer":"$(i)(a)$ $2916x,\\ 4860x^2,\\ 2160x^4$. $\\quad (i)(b)$ $x=\\dfrac{15}{4}$. $\\quad (ii)(a)$ Proven. $\\quad (ii)(b)$ $\\dfrac{48}{125}$.","steps":[{"title":"Find the second term","body":"The 2nd term of $(3+2x)^6$ is $\\binom61 3^5(2x)=6\\cdot243\\cdot2x=2916x$."},{"title":"Find the third term","body":"The 3rd term is $\\binom62 3^4(2x)^2=15\\cdot81\\cdot4x^2=4860x^2$."},{"title":"Find the fifth term","body":"The 5th term is $\\binom64 3^2(2x)^4=15\\cdot9\\cdot16x^4=2160x^4$."},{"title":"Use the geometric condition","body":"For three consecutive terms in a geometric series, the middle term squared equals the product of the two outer terms."},{"title":"Set up the equation","body":"$(4860x^2)^2=(2916x)(2160x^4)$."},{"title":"Solve for x","body":"For the non-zero geometric case, divide by $x^4$: $4860^2=2916\\cdot2160\\,x$, so $x=\\dfrac{4860^2}{2916\\cdot2160}=\\dfrac{15}{4}$."},{"title":"Use the sum to infinity","body":"In the different geometric series, first term $=\\sin^2\\theta$, common ratio $=2\\cos\\theta$, and $S_\\infty=\\dfrac85$."},{"title":"Form the equation","body":"$\\dfrac{\\sin^2\\theta}{1-2\\cos\\theta}=\\dfrac85$."},{"title":"Use sine squared","body":"$5\\sin^2\\theta=8(1-2\\cos\\theta)$. With $\\sin^2\\theta=1-\\cos^2\\theta$, this becomes $5(1-\\cos^2\\theta)=8-16\\cos\\theta$."},{"title":"Show the required equation","body":"Rearranging gives $5\\cos^2\\theta-16\\cos\\theta+3=0$."},{"title":"Solve for cosine","body":"$5\\cos^2\\theta-16\\cos\\theta+3=0$ gives $\\cos\\theta=3$ or $\\cos\\theta=\\dfrac15$. The possible value is $\\cos\\theta=\\dfrac15$."},{"title":"Find the second term","body":"The 2nd term is first term times common ratio: $\\sin^2\\theta(2\\cos\\theta)=\\left(1-\\dfrac{1}{25}\\right)\\cdot\\dfrac25=\\dfrac{24}{25}\\cdot\\dfrac25=\\dfrac{48}{125}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q02","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":2,"marks":3,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q02_M03_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2024_Jan_Q02_M03_04_BinomialExpansion.png","finalAnswer":"$96228$.","steps":[{"title":"Choose the x power","body":"In $\\left(\\dfrac38+4x\\right)^{12}$, the term in $x^7$ comes from choosing $(4x)^7$ and $\\left(\\dfrac38\\right)^5$."},{"title":"Write the term","body":"The coefficient is $\\binom{12}{7}\\left(\\dfrac38\\right)^5 4^7$."},{"title":"Simplify the powers","body":"$4^7=2^{14}$ and $8^5=2^{15}$, so $\\left(\\dfrac38\\right)^5 4^7=\\dfrac{3^5}{2}$."},{"title":"Evaluate","body":"$\\binom{12}{7}=792$, so the coefficient is $792\\cdot\\dfrac{243}{2}=96228$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q01","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":1,"marks":5,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q01_M05_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2024_MayJune_Q01_M05_04_BinomialExpansion.png","finalAnswer":"$(a)$ $1-\\dfrac32x+x^2-\\dfrac{7}{18}x^3$. $\\quad (b)$ $\\dfrac{53}{6}$.","steps":[{"title":"Expand the first terms","body":"$\\left(1-\\dfrac16x\\right)^9=1+9\\left(-\\dfrac16x\\right)+\\binom92\\left(-\\dfrac16x\\right)^2+\\binom93\\left(-\\dfrac16x\\right)^3+\\cdots$."},{"title":"Simplify","body":"The first four terms are $1-\\dfrac32x+x^2-\\dfrac{7}{18}x^3$."},{"title":"Identify contributions to x cubed","body":"In $(10x+3)\\left(1-\\dfrac16x\\right)^9$, the $x^3$ coefficient comes from $3$ times the $x^3$ coefficient and $10x$ times the $x^2$ coefficient."},{"title":"Calculate the coefficient","body":"$3\\left(-\\dfrac{7}{18}\\right)+10(1)=-\\dfrac76+10=\\dfrac{53}{6}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q04","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":4,"marks":7,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q04_M07_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q04_M07_04_BinomialExpansion.png","finalAnswer":"$(a)$ $729+2916x+4860x^2+4320x^3$. $\\quad (b)$ $738$.","steps":[{"title":"Write the expansion terms","body":"$(3+2x)^6=3^6+\\binom61 3^5(2x)+\\binom62 3^4(2x)^2+\\binom63 3^3(2x)^3+\\cdots$."},{"title":"Simplify the first four terms","body":"This gives $729+2916x+4860x^2+4320x^3$."},{"title":"Identify x squared contributions","body":"In $\\left(2x^2-\\dfrac{1}{6x}\\right)(3+2x)^6$, the $x^2$ term comes from $2x^2$ times the constant term and $-\\dfrac{1}{6x}$ times the $x^3$ term."},{"title":"Calculate the coefficient","body":"The coefficient is $2(729)-\\dfrac16(4320)=1458-720=738$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q05","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":5,"marks":7,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q05_M07_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2024_Oct_Q05_M07_04_BinomialExpansion.png","finalAnswer":"$(a)$ $64+192ax+240a^2x^2$. $\\quad (b)$ $a=-\\dfrac{24}{5}$.","steps":[{"title":"Write the first three binomial terms","body":"$(2+ax)^6=2^6+6(2^5)(ax)+\\binom62(2^4)(ax)^2+\\cdots$."},{"title":"Simplify the terms","body":"The first three terms are $64+192ax+240a^2x^2$."},{"title":"Expand the other factor","body":"$\\left(3+\\dfrac1x\\right)^2=9+6x^{-1}+x^{-2}$."},{"title":"Collect constant contributions","body":"The constant term in $\\left(3+\\dfrac1x\\right)^2(2+ax)^6$ is $9(64)+6(192a)+240a^2$."},{"title":"Use the given constant term","body":"$576+1152a+240a^2=576$, so $240a^2+1152a=0$."},{"title":"Solve for a","body":"$48a(5a+24)=0$. Since $a\\ne0$, $5a+24=0$, so $a=-\\dfrac{24}{5}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q02","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":2,"marks":5,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q02_M05_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2025_Jan_Q02_M05_04_BinomialExpansion.png","finalAnswer":"$(a)$ $256-5120x+44800x^2-224000x^3$. $\\quad (b)$ $x=-0.01$.","steps":[{"title":"Write the first four terms","body":"$(2-5x)^8=2^8+8(2^7)(-5x)+\\binom82(2^6)(-5x)^2+\\binom83(2^5)(-5x)^3+\\cdots$."},{"title":"Simplify each term","body":"The first four terms are $256-5120x+44800x^2-224000x^3$."},{"title":"Connect the expansion to 2.05","body":"To use $(2-5x)^8$ for $2.05^8$, set $2-5x=2.05$."},{"title":"Find x","body":"$-5x=0.05$, so $x=-0.01$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q01","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":1,"marks":6,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["04_BinomialExpansion","07_SequencesSeries"],"topicNames":["Binomial Expansion","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q01_M06_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2025_MayJune_Q01_M06_04_BinomialExpansion.png","finalAnswer":"$(a)$ $1-28x+336x^2-2240x^3$. $\\quad (b)$ $k=13$.","steps":[{"title":"Write the binomial terms","body":"$(1-4x)^7=1+7(-4x)+\\binom72(-4x)^2+\\binom73(-4x)^3+\\cdots$."},{"title":"Simplify","body":"The first four terms are $1-28x+336x^2-2240x^3$."},{"title":"Find the x squared terms","body":"In $(5+kx)(1-4x)^7$, the $x^2$ coefficient comes from $5(336x^2)$ and $(kx)(-28x)$."},{"title":"Use the given coefficient","body":"$5(336)-28k=1316$, so $1680-28k=1316$."},{"title":"Find k","body":"$28k=364$, hence $k=13$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q02","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":2,"marks":6,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q02_M06_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2025_Oct_Q02_M06_04_BinomialExpansion.png","finalAnswer":"$p=\\dfrac32$, $q=\\dfrac{405}{4}$, $r=405$.","steps":[{"title":"Write the first four terms","body":"$(1+px)^{10}=1+10px+\\binom{10}{2}p^2x^2+\\binom{10}{3}p^3x^3+\\cdots$."},{"title":"Compare the x coefficient","body":"Since the coefficient of $x$ is $15$, $10p=15$, so $p=\\dfrac32$."},{"title":"Find q","body":"$q=\\binom{10}{2}p^2=45\\left(\\dfrac32\\right)^2=\\dfrac{405}{4}$."},{"title":"Find r","body":"$r=\\binom{10}{3}p^3=120\\left(\\dfrac32\\right)^3=405$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q01","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":1,"marks":6,"topic":"04_BinomialExpansion","topicName":"Binomial Expansion","primaryTopic":"04_BinomialExpansion","primaryTopicName":"Binomial Expansion","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_BinomialExpansion"],"topicNames":["Binomial Expansion"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q01_M06_04_BinomialExpansion.png","downloadName":"WMA12-01_Y2026_Jan_Q01_M06_04_BinomialExpansion.png","finalAnswer":"$(a)\\ 2187+5103kx+5103k^2x^2+2835k^3x^3.\\quad (b)\\ k=\\dfrac35$.","steps":[{"title":"Use the binomial expansion","body":"For $(3+kx)^7$, the first four terms are $3^7+\\binom71 3^6(kx)+\\binom72 3^5(kx)^2+\\binom73 3^4(kx)^3$."},{"title":"Simplify the coefficients","body":"This gives $2187+5103kx+5103k^2x^2+2835k^3x^3$."},{"title":"Compare the required coefficients","body":"The coefficient of $x^2$ is $5103k^2$ and the coefficient of $x^3$ is $2835k^3$."},{"title":"Solve for k","body":"Since $5103k^2=3(2835k^3)$ and $k\\ne0$, divide by $k^2$ to get $5103=8505k$, hence $k=\\dfrac{5103}{8505}=\\dfrac35$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q05","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":5,"marks":6,"topic":"05_ArithmeticSequences","topicName":"Arithmetic Sequences","primaryTopic":"05_ArithmeticSequences","primaryTopicName":"Arithmetic Sequences","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["05_ArithmeticSequences","08_ModellingSequencesSeries"],"topicNames":["Arithmetic Sequences","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q05_M06_05_ArithmeticSequences.png","downloadName":"WMA12-01_Y2021_Oct_Q05_M06_05_ArithmeticSequences.png","finalAnswer":"$(a)\\ 285$ tonnes. $\\quad (b)$ Proven: $N^2-65N+1036=0$. $\\quad (c)\\ N=28$.","steps":[{"title":"Identify the arithmetic sequence","body":"The first term is $480$ and the common difference is $465-480=-15$."},{"title":"Find year fourteen","body":"$u_{14}=480+13(-15)=285$, so $285$ tonnes were extracted in year $14$."},{"title":"Set up the total","body":"The total after $N$ years is $S_N=\\dfrac N2\\{2(480)+(N-1)(-15)\\}$."},{"title":"Use the total extraction","body":"$\\dfrac N2(975-15N)=7770$."},{"title":"Show the quadratic","body":"Multiplying by $2$ and rearranging gives $15N^2-975N+15540=0$, so $N^2-65N+1036=0$."},{"title":"Solve and choose N","body":"$N=28$ or $37$. Since extraction amounts would become negative before year $37$, the stopping year is $N=28$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q08","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":8,"marks":7,"topic":"05_ArithmeticSequences","topicName":"Arithmetic Sequences","primaryTopic":"05_ArithmeticSequences","primaryTopicName":"Arithmetic Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["05_ArithmeticSequences","07_SequencesSeries"],"topicNames":["Arithmetic Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q08_M07_05_ArithmeticSequences.png","downloadName":"WMA12-01_Y2023_Oct_Q08_M07_05_ArithmeticSequences.png","finalAnswer":"$(a)$ $a=18$. $\\quad (b)$ Proven. $\\quad (c)(i)$ $29$ rows. $\\quad (c)(ii)$ $130$ seats.","steps":[{"title":"Use the arithmetic sum formula","body":"The first term is $a$ and the common difference is $4$."},{"title":"Use the first 10 rows","body":"$S_{10}=\\dfrac{10}{2}\\left(2a+9\\cdot4\\right)=360$."},{"title":"Find a","body":"$5(2a+36)=360$, so $10a+180=360$ and $a=18$."},{"title":"Write S n","body":"$S_n=\\dfrac n2\\left(2(18)+(n-1)4\\right)=\\dfrac n2(4n+32)=2n^2+16n$."},{"title":"Use the total number of seats","body":"Since the total is $2146$, $2n^2+16n=2146$."},{"title":"Show the equation","body":"Dividing by $2$ and rearranging gives $n^2+8n-1073=0$."},{"title":"Solve for n","body":"$n=\\dfrac{-8\\pm\\sqrt{8^2+4(1073)}}{2}=\\dfrac{-8\\pm66}{2}$, so $n=29$ or $n=-37$."},{"title":"Choose the row count","body":"The number of rows must be positive, so there are $29$ rows."},{"title":"Find the maximum row size","body":"The largest row is the last row: $18+(29-1)4=18+112=130$ seats."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q02","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":2,"marks":7,"topic":"05_ArithmeticSequences","topicName":"Arithmetic Sequences","primaryTopic":"05_ArithmeticSequences","primaryTopicName":"Arithmetic Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["05_ArithmeticSequences","07_SequencesSeries"],"topicNames":["Arithmetic Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q02_M07_05_ArithmeticSequences.png","downloadName":"WMA12-01_Y2024_MayJune_Q02_M07_05_ArithmeticSequences.png","finalAnswer":"$(a)$ First term $=-98$, common difference $=20$. $\\quad (b)$ $n=35$.","steps":[{"title":"Use the sixth term","body":"For an arithmetic series, $u_6=a+5d=2$."},{"title":"Use the sum of ten terms","body":"$S_{10}=\\dfrac{10}{2}(2a+9d)=-80$, so $2a+9d=-16$."},{"title":"Solve simultaneously","body":"From $a+5d=2$, $a=2-5d$. Substitute into $2a+9d=-16$."},{"title":"Find a and d","body":"$2(2-5d)+9d=-16$, so $4-d=-16$ and $d=20$. Then $a=2-5(20)=-98$."},{"title":"Write S n","body":"$S_n=\\dfrac n2(2a+(n-1)d)=\\dfrac n2(-196+20n-20)=10n^2-108n$."},{"title":"Set up the inequality","body":"We need $10n^2-108n>8000$."},{"title":"Solve the boundary","body":"$10n^2-108n-8000=0$ gives $5n^2-54n-4000=0$."},{"title":"Find the positive threshold","body":"$n=\\dfrac{54+\\sqrt{82916}}{10}=34.195\\ldots$."},{"title":"Choose the smallest integer","body":"Therefore the smallest integer value with $S_n>8000$ is $n=35$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q08","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":8,"marks":13,"topic":"05_ArithmeticSequences","topicName":"Arithmetic Sequences","primaryTopic":"05_ArithmeticSequences","primaryTopicName":"Arithmetic Sequences","secondaryTopics":["06_GeometricSequences"],"secondaryTopicNames":["Geometric Sequences"],"topics":["05_ArithmeticSequences","06_GeometricSequences"],"topicNames":["Arithmetic Sequences","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q08_M13_05_ArithmeticSequences.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q08_M13_05_ArithmeticSequences.png","finalAnswer":"$(i)(a)$ Proven. $\\quad (i)(b)$ $35700$. $\\quad (ii)(a)$ Proven. $\\quad (ii)(b)$ $S_\\infty=24$.","steps":[{"title":"Write the first and last terms","body":"The first term is $a$ and the $n$th term is $a+(n-1)d$."},{"title":"Use the arithmetic sum formula","body":"$S_n=\\dfrac n2(\\text{first term}+\\text{last term})$."},{"title":"Show the formula","body":"Therefore $S_n=\\dfrac n2\\{a+[a+(n-1)d]\\}=\\dfrac n2\\{2a+(n-1)d\\}$."},{"title":"Identify the arithmetic series","body":"For $900+892+884+\\cdots+500$, the first term is $900$, the common difference is $-8$, and the last term is $500$."},{"title":"Find the number of terms","body":"$500=900+(n-1)(-8)$, so $n-1=50$ and $n=51$."},{"title":"Find the sum","body":"$S=\\dfrac{51}{2}(900+500)=35700$."},{"title":"Use the geometric condition","body":"For $k+4$, $k-2$, $11-k$ to be consecutive geometric terms, $(k-2)^2=(k+4)(11-k)$."},{"title":"Show the quadratic","body":"$k^2-4k+4=-k^2+7k+44$, so $2k^2-11k-40=0$."},{"title":"Solve for k","body":"$2k^2-11k-40=0$ gives $k=8$ or $k=-\\dfrac52$."},{"title":"Use convergence","body":"If $k=8$, the terms are $12,6,3$ and the common ratio is $\\dfrac12$, so the series is convergent. If $k=-\\dfrac52$, the common ratio is $-3$, so it is not convergent."},{"title":"Find S infinity","body":"Use $k=8$: $S_\\infty=\\dfrac{12}{1-1/2}=24$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q01","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":1,"marks":4,"topic":"05_ArithmeticSequences","topicName":"Arithmetic Sequences","primaryTopic":"05_ArithmeticSequences","primaryTopicName":"Arithmetic Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["05_ArithmeticSequences","07_SequencesSeries"],"topicNames":["Arithmetic Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q01_M04_05_ArithmeticSequences.png","downloadName":"WMA12-01_Y2025_Jan_Q01_M04_05_ArithmeticSequences.png","finalAnswer":"$(a)$ $85$. $\\quad (b)$ $10880$.","steps":[{"title":"Identify the arithmetic series","body":"The first term is $2$, the common difference is $3$, and the last term is $254$."},{"title":"Find the number of terms","body":"Use $254=2+(n-1)3$. Then $252=3(n-1)$, so $n-1=84$ and $n=85$."},{"title":"Use the sum formula","body":"$S_n=\\dfrac n2(a+l)$, where $a$ is the first term and $l$ is the last term."},{"title":"Find the sum","body":"$S=\\dfrac{85}{2}(2+254)=85\\times128=10880$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q01","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":1,"marks":4,"topic":"05_ArithmeticSequences","topicName":"Arithmetic Sequences","primaryTopic":"05_ArithmeticSequences","primaryTopicName":"Arithmetic Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["05_ArithmeticSequences","07_SequencesSeries"],"topicNames":["Arithmetic Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q01_M04_05_ArithmeticSequences.png","downloadName":"WMA12-01_Y2025_Oct_Q01_M04_05_ArithmeticSequences.png","finalAnswer":"$(a)$ $27$. $\\quad (b)$ $-7050$.","steps":[{"title":"Identify the sequence","body":"The first term is $78$ and the common difference is $75-78=-3$."},{"title":"Find the eighteenth term","body":"$u_{18}=78+17(-3)=27$."},{"title":"Use the sum formula","body":"$S_{100}=\\dfrac{100}{2}\\{2(78)+99(-3)\\}$."},{"title":"Evaluate the sum","body":"$S_{100}=50(156-297)=50(-141)=-7050$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q07","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":7,"marks":10,"topic":"06_GeometricSequences","topicName":"Geometric Sequences","primaryTopic":"06_GeometricSequences","primaryTopicName":"Geometric Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["06_GeometricSequences","07_SequencesSeries"],"topicNames":["Geometric Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q07_M10_06_GeometricSequences.png","downloadName":"WMA12-01_Y2021_Oct_Q07_M10_06_GeometricSequences.png","finalAnswer":"$(i)\\ n=129.\\quad (ii)(a)$ Proven. $\\quad (ii)(b)\\ r=\\dfrac65\\text{ or }-\\dfrac15.\\quad (ii)(c)\\ r=-\\dfrac15.\\quad (ii)(d)\\ \\dfrac{624}{25}$.","steps":[{"title":"Write the nth term","body":"The nth term of the first sequence is $4\\cdot6^{n-1}$."},{"title":"Use logarithms","body":"We need $4\\cdot6^{n-1}>10^{100}$, so $n-1>\\dfrac{100-\\log_{10}4}{\\log_{10}6}=127.736\\ldots$."},{"title":"Choose the smallest integer","body":"Thus $n$ must be greater than $128.736\\ldots$, so the minimum possible value is $129$."},{"title":"Use the second term","body":"For the second sequence, $ar=-6$, so $a=-\\dfrac6r$."},{"title":"Use the sum to infinity","body":"$\\dfrac{a}{1-r}=25$. Substituting $a=-\\dfrac6r$ gives $-6=25r(1-r)$."},{"title":"Show the quadratic","body":"Rearranging gives $25r^2-25r-6=0$."},{"title":"Solve for r","body":"$25r^2-25r-6=0$ gives $r=\\dfrac65$ or $r=-\\dfrac15$."},{"title":"Choose the valid ratio","body":"A sum to infinity exists only when $|r|<1$, so $r=-\\dfrac15$."},{"title":"Find the first term","body":"Since $ar=-6$, $a=30$."},{"title":"Sum four terms","body":"$S_4=30\\dfrac{1-(-1/5)^4}{1-(-1/5)}=\\dfrac{624}{25}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q06","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":6,"marks":8,"topic":"06_GeometricSequences","topicName":"Geometric Sequences","primaryTopic":"06_GeometricSequences","primaryTopicName":"Geometric Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["06_GeometricSequences","07_SequencesSeries"],"topicNames":["Geometric Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q06_M08_06_GeometricSequences.png","downloadName":"WMA12-01_Y2022_MayJune_Q06_M08_06_GeometricSequences.png","finalAnswer":"$(a)$ Proven: $3r^2-4r-4=0$. $\\quad (b)\\ u_1=-27.\\quad (c)\\ S_\\infty=-\\dfrac{81}{5}$.","steps":[{"title":"Write the terms","body":"$u_2=u_1r$, $u_3=u_1r^2$, and $u_4=u_1r^3$."},{"title":"Use u four","body":"Since $u_4=8$, $u_1r^3=8$, so $u_1r=\\dfrac{8}{r^2}$."},{"title":"Use u two plus u three","body":"$u_2+u_3=u_1r(1+r)=6$."},{"title":"Show the quadratic","body":"Substitute $u_1r=\\dfrac8{r^2}$ to get $\\dfrac8{r^2}(1+r)=6$. Hence $8+8r=6r^2$, so $3r^2-4r-4=0$."},{"title":"Solve for r","body":"$3r^2-4r-4=0$ gives $r=2$ or $r=-\\dfrac23$."},{"title":"Choose the sum-to-infinity ratio","body":"A sum to infinity requires $|r|<1$, so $r=-\\dfrac23$."},{"title":"Find u one","body":"$u_1r^3=8$, so $u_1\\left(-\\dfrac23\\right)^3=8$ and $u_1=-27$."},{"title":"Find the infinite sum","body":"$S_\\infty=\\dfrac{u_1}{1-r}=\\dfrac{-27}{1+2/3}=-\\dfrac{81}{5}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q08","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":8,"marks":7,"topic":"06_GeometricSequences","topicName":"Geometric Sequences","primaryTopic":"06_GeometricSequences","primaryTopicName":"Geometric Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["06_GeometricSequences","07_SequencesSeries"],"topicNames":["Geometric Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q08_M07_06_GeometricSequences.png","downloadName":"WMA12-01_Y2022_Oct_Q08_M07_06_GeometricSequences.png","finalAnswer":"$(a)$ $a=43.2$. $\\quad (b)$ $S_{10}=127.353\\ldots$, so $127$ to 3 s.f.","steps":[{"title":"Use the sum to infinity formula","body":"For a geometric sequence, $S_\\infty=\\dfrac{a}{1-r}$. The question gives $S_\\infty=3a$."},{"title":"Find the common ratio","body":"$\\dfrac{a}{1-r}=3a$. Since $u_2-u_4=16$, $a\\ne0$, so $\\dfrac{1}{1-r}=3$ and $r=\\dfrac23$."},{"title":"Use u2 minus u4","body":"$u_2-u_4=ar-ar^3=ar(1-r^2)=16$."},{"title":"Substitute r","body":"$a\\left(\\dfrac23\\right)\\left(1-\\dfrac49\\right)=16$."},{"title":"Solve for a","body":"$a\\cdot\\dfrac23\\cdot\\dfrac59=16$, so $\\dfrac{10a}{27}=16$ and $a=\\dfrac{216}{5}=43.2$."},{"title":"Find S10","body":"$S_{10}=\\dfrac{a(1-r^{10})}{1-r}=3a\\left(1-\\left(\\dfrac23\\right)^{10}\\right)$."},{"title":"Evaluate","body":"$S_{10}=3\\left(\\dfrac{216}{5}\\right)\\left(1-\\left(\\dfrac23\\right)^{10}\\right)=\\dfrac{92840}{729}=127.352\\ldots$, so $S_{10}=127$ to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q07","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":7,"marks":7,"topic":"06_GeometricSequences","topicName":"Geometric Sequences","primaryTopic":"06_GeometricSequences","primaryTopicName":"Geometric Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["06_GeometricSequences","07_SequencesSeries"],"topicNames":["Geometric Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q07_M07_06_GeometricSequences.png","downloadName":"WMA12-01_Y2023_Jan_Q07_M07_06_GeometricSequences.png","finalAnswer":"$(a)$ $r=0.8$. $\\quad (b)$ $a=31.25$. $\\quad (c)$ $n=29$.","steps":[{"title":"Write the given terms","body":"For a geometric sequence, the third term is $ar^2=20$ and the fifth term is $ar^4=12.8$."},{"title":"Divide the equations","body":"$\\dfrac{ar^4}{ar^2}=\\dfrac{12.8}{20}$, so $r^2=0.64$."},{"title":"Use r positive","body":"Since $r>0$, $r=0.8$."},{"title":"Find a","body":"Using $ar^2=20$, $a(0.8)^2=20$, so $a=\\dfrac{20}{0.64}=31.25$."},{"title":"Write the sum formula","body":"$S_n=\\dfrac{a(1-r^n)}{1-r}=\\dfrac{31.25(1-0.8^n)}{0.2}=156.25(1-0.8^n)$."},{"title":"Set up the inequality","body":"We need $156.25(1-0.8^n)>156$."},{"title":"Isolate the power","body":"$1-0.8^n>\\dfrac{156}{156.25}=\\dfrac{624}{625}$, so $0.8^n<\\dfrac{1}{625}$."},{"title":"Use logarithms","body":"$n\\log(0.8)<\\log\\left(\\dfrac{1}{625}\\right)$. Since $\\log(0.8)<0$, dividing reverses the inequality: $n>\\dfrac{\\log(1/625)}{\\log(0.8)}=28.85\\ldots$."},{"title":"Choose the smallest integer","body":"The smallest possible integer value is therefore $n=29$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q06","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":6,"marks":9,"topic":"06_GeometricSequences","topicName":"Geometric Sequences","primaryTopic":"06_GeometricSequences","primaryTopicName":"Geometric Sequences","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["06_GeometricSequences","08_ModellingSequencesSeries"],"topicNames":["Geometric Sequences","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q06_M09_06_GeometricSequences.png","downloadName":"WMA12-01_Y2023_MayJune_Q06_M09_06_GeometricSequences.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $\\dfrac{64}{3}$ thousand downloads, about $21300$ downloads. $\\quad (c)$ $N=17$.","steps":[{"title":"Use the geometric condition","body":"For three consecutive terms of a geometric sequence, the middle term squared equals the product of the outer terms."},{"title":"Set up the equation","body":"So $k^2=(2k-15)(k+4)$."},{"title":"Show the required quadratic","body":"Expanding gives $k^2=2k^2-7k-60$, hence $k^2-7k-60=0$."},{"title":"Find k","body":"$k^2-7k-60=(k-12)(k+5)=0$, so $k=12$ or $k=-5$. The download numbers must be positive, so $k=12$."},{"title":"Find the common ratio","body":"The first three monthly values are $9$, $12$ and $16$ thousand. The common ratio is $\\dfrac{12}{9}=\\dfrac43$."},{"title":"Predict month four","body":"The 4th month is $16\\cdot\\dfrac43=\\dfrac{64}{3}$ thousand downloads, which is about $21300$ downloads."},{"title":"Write the cumulative total","body":"In thousands, the total after $N$ months is $S_N=\\dfrac{9\\left(\\left(\\dfrac43\\right)^N-1\\right)}{\\dfrac43-1}=27\\left(\\left(\\dfrac43\\right)^N-1\\right)$."},{"title":"Compare with three million","body":"Three million downloads is $3000$ thousand, so we need $27\\left(\\left(\\dfrac43\\right)^N-1\\right)>3000$."},{"title":"Solve the inequality","body":"$\\left(\\dfrac43\\right)^N>\\dfrac{1009}{9}$. Taking logarithms gives $N>\\dfrac{\\log(1009/9)}{\\log(4/3)}=16.405\\ldots$."},{"title":"Choose the first month","body":"The first integer month for which the total exceeds $3$ million is $N=17$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q04","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":4,"marks":6,"topic":"06_GeometricSequences","topicName":"Geometric Sequences","primaryTopic":"06_GeometricSequences","primaryTopicName":"Geometric Sequences","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["06_GeometricSequences","07_SequencesSeries"],"topicNames":["Geometric Sequences","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q04_M06_06_GeometricSequences.png","downloadName":"WMA12-01_Y2025_Jan_Q04_M06_06_GeometricSequences.png","finalAnswer":"$(a)$ $r=0.4$. $\\quad (b)$ $45$.","steps":[{"title":"Write the two sums","body":"For first term $a$ and common ratio $r$, $S_\\infty=\\dfrac{a}{1-r}=75$ and $S_3=\\dfrac{a(1-r^3)}{1-r}=70.2$."},{"title":"Divide the equations","body":"$\\dfrac{S_3}{S_\\infty}=1-r^3$, so $\\dfrac{70.2}{75}=1-r^3$."},{"title":"Find the ratio","body":"$0.936=1-r^3$, so $r^3=0.064$ and $r=0.4$."},{"title":"Find the first term","body":"Use $\\dfrac{a}{1-0.4}=75$. Hence $a=75(0.6)=45$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q08","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":8,"marks":8,"topic":"06_GeometricSequences","topicName":"Geometric Sequences","primaryTopic":"06_GeometricSequences","primaryTopicName":"Geometric Sequences","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["06_GeometricSequences","08_ModellingSequencesSeries"],"topicNames":["Geometric Sequences","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q08_M08_06_GeometricSequences.png","downloadName":"WMA12-01_Y2025_Oct_Q08_M08_06_GeometricSequences.png","finalAnswer":"$(i)$ Proven. $\\quad (ii)(a)$ Approximately $91$ litres. $\\quad (ii)(b)$ $1664$ litres.","steps":[{"title":"Write S n","body":"$S_n=a+ar+ar^2+\\cdots+ar^{n-1}$."},{"title":"Multiply by r","body":"$rS_n=ar+ar^2+ar^3+\\cdots+ar^n$."},{"title":"Subtract","body":"$S_n-rS_n=a-ar^n=a(1-r^n)$."},{"title":"Rearrange","body":"$(1-r)S_n=a(1-r^n)$, so $S_n=\\dfrac{a(1-r^n)}{1-r}$."},{"title":"Use the yearly multiplier","body":"An $8\\%$ decrease each year means the multiplier is $0.92$."},{"title":"Show the amount after six years","body":"After $6$ years, the amount is $150(0.92)^6=90.953\\ldots$, which is approximately $91$ litres."},{"title":"Set up the forty barrel total","body":"At the end of $40$ years, the amounts are $150(0.92),150(0.92)^2,\\ldots,150(0.92)^{40}$."},{"title":"Sum the geometric sequence","body":"The total is $150(0.92)\\dfrac{1-0.92^{40}}{1-0.92}=1663.581\\ldots$."},{"title":"Round the total","body":"To the nearest litre, the total amount is $1664$ litres."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q08","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":8,"marks":7,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":["05_ArithmeticSequences"],"secondaryTopicNames":["Arithmetic Sequences"],"topics":["07_SequencesSeries","05_ArithmeticSequences"],"topicNames":["Sequences & Series","Arithmetic Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q08_M07_07_SequencesSeries.png","downloadName":"WMA12-01_Y2020_Jan_Q08_M07_07_SequencesSeries.png","finalAnswer":"$(i)$ Proven. $\\quad (ii)(a)\\ 22.\\quad (ii)(b)\\ 8847$.","steps":[{"title":"Write the series forwards","body":"$S_n=a+(a+d)+(a+2d)+\\cdots+(a+(n-1)d)$."},{"title":"Write the series backwards","body":"$S_n=(a+(n-1)d)+(a+(n-2)d)+\\cdots+a$."},{"title":"Add the two forms","body":"Each pair adds to $2a+(n-1)d$, and there are $n$ pairs. Hence $2S_n=n\\{2a+(n-1)d\\}$."},{"title":"Complete the proof","body":"Dividing by $2$ gives $S_n=\\dfrac n2\\{2a+(n-1)d\\}$."},{"title":"Find u5","body":"$u_5=5(5)+3(-1)^5=25-3=22$."},{"title":"Sum the sequence","body":"$\\sum_{n=1}^{59}u_n=5\\sum_{n=1}^{59}n+3\\sum_{n=1}^{59}(-1)^n$."},{"title":"Calculate the total","body":"$5\\sum_{n=1}^{59}n=5\\cdot\\dfrac{59\\cdot60}{2}=8850$, and $\\sum_{n=1}^{59}(-1)^n=-1$. Therefore the total is $8850-3=8847$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q08","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":8,"marks":7,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":[],"secondaryTopicNames":[],"topics":["07_SequencesSeries"],"topicNames":["Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q08_M07_07_SequencesSeries.png","downloadName":"WMA12-01_Y2021_Jan_Q08_M07_07_SequencesSeries.png","finalAnswer":"$(a)\\ a_2=2p^2-7.\\quad (b)\\ a_2=-7\\text{ or }\\dfrac12$.","steps":[{"title":"Find a two","body":"Since $a_1=p-3$, we have $a_1+3=p$. Therefore $a_2=2(a_1+3)^2-7=2p^2-7$."},{"title":"Find a three","body":"$a_2+3=2p^2-4$, so $a_3=2(2p^2-4)^2-7=8(p^2-2)^2-7$."},{"title":"Use the given sum","body":"$a_1+a_2+a_3=p+15$."},{"title":"Substitute the expressions","body":"$(p-3)+(2p^2-7)+8(p^2-2)^2-7=p+15$."},{"title":"Simplify","body":"Cancelling $p$ and expanding gives $8p^4-30p^2=0$, so $2p^2(4p^2-15)=0$."},{"title":"Find the possible a two values","body":"If $p=0$, then $a_2=-7$. If $p^2=\\dfrac{15}{4}$, then $a_2=2\\cdot\\dfrac{15}{4}-7=\\dfrac12$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q02","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":2,"marks":5,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":[],"secondaryTopicNames":[],"topics":["07_SequencesSeries"],"topicNames":["Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q02_M05_07_SequencesSeries.png","downloadName":"WMA12-01_Y2021_Oct_Q02_M05_07_SequencesSeries.png","finalAnswer":"$(a)\\ u_3=6k^2+3k+3.\\quad (b)\\ k=\\dfrac72$.","steps":[{"title":"Find u two","body":"$u_2=ku_1+3=6k+3$."},{"title":"Find u three","body":"$u_3=ku_2+3=k(6k+3)+3=6k^2+3k+3$."},{"title":"Use the given sum","body":"$u_1+u_2+u_3=117$, so $6+(6k+3)+(6k^2+3k+3)=117$."},{"title":"Simplify the equation","body":"$6k^2+9k+12=117$, hence $2k^2+3k-35=0$."},{"title":"Solve for k","body":"$(2k-7)(k+5)=0$. Since $k$ is positive, $k=\\dfrac72$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q03","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":3,"marks":7,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":["10_TrigonometricEquations"],"secondaryTopicNames":["Trigonometric Equations"],"topics":["07_SequencesSeries","10_TrigonometricEquations"],"topicNames":["Sequences & Series","Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q03_M07_07_SequencesSeries.png","downloadName":"WMA12-01_Y2022_Oct_Q03_M07_07_SequencesSeries.png","finalAnswer":"$(a)\\ a_1=\\dfrac14,\\ a_2=\\dfrac14,\\ a_3=1. $\\quad $(b)\\ \\dfrac{2599}{2}$.","steps":[{"title":"Find the first term","body":"$a_1=\\cos^2\\left(\\dfrac{\\pi}{3}\\right)=\\left(\\dfrac12\\right)^2=\\dfrac14$."},{"title":"Find the second term","body":"$a_2=\\cos^2\\left(\\dfrac{2\\pi}{3}\\right)=\\left(-\\dfrac12\\right)^2=\\dfrac14$."},{"title":"Find the third term","body":"$a_3=\\cos^2(\\pi)=(-1)^2=1$."},{"title":"Recognise the repeating pattern","body":"The values of $\\cos^2\\left(\\dfrac{n\\pi}{3}\\right)$ repeat every 3 terms as $\\dfrac14,\\dfrac14,1$."},{"title":"Sum the n part","body":"$\\sum_{n=1}^{50} n=\\dfrac{50\\cdot51}{2}=1275$."},{"title":"Sum the cosine part","body":"There are $16$ complete groups of 3 terms in the first $48$ terms, then the first 2 terms repeat. Hence the cosine-square sum is $16\\left(\\dfrac14+\\dfrac14+1\\right)+\\dfrac14+\\dfrac14=24+\\dfrac12=\\dfrac{49}{2}$."},{"title":"Add the two sums","body":"$\\sum_{n=1}^{50}\\left(n+\\cos^2\\left(\\dfrac{n\\pi}{3}\\right)\\right)=1275+\\dfrac{49}{2}=\\dfrac{2599}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q11","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":11,"marks":8,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":[],"secondaryTopicNames":[],"topics":["07_SequencesSeries"],"topicNames":["Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q11_M08_07_SequencesSeries.png","downloadName":"WMA12-01_Y2023_MayJune_Q11_M08_07_SequencesSeries.png","finalAnswer":"$(a)(i)$ $u_2=b-3a$. $\\quad (a)(ii)$ $u_3=b-ab+3a^2$. $\\quad (b)$ Proven. $\\quad (c)$ $21$.","steps":[{"title":"Find u2","body":"Using $u_{n+1}=b-au_n$ and $u_1=3$, we get $u_2=b-a(3)=b-3a$."},{"title":"Find u3","body":"$u_3=b-au_2=b-a(b-3a)=b-ab+3a^2$."},{"title":"Use the sum condition","body":"$u_1+u_2+u_3=153$, so $3+(b-3a)+(b-ab+3a^2)=153$."},{"title":"Substitute b equals a plus nine","body":"Using $b=a+9$, the left side becomes $3+(a+9)-3a+(a+9)-a(a+9)+3a^2$."},{"title":"Simplify","body":"This is $2a^2-10a+21$, so $2a^2-10a+21=153$."},{"title":"Show the required equation","body":"$2a^2-10a-132=0$. Dividing by $2$ gives $a^2-5a-66=0$."},{"title":"Solve for a","body":"$a^2-5a-66=(a-11)(a+6)=0$, so $a=11$ or $a=-6$."},{"title":"Find the corresponding u2 values","body":"If $a=11$, then $b=20$ and $u_2=20-3(11)=-13$. If $a=-6$, then $b=3$ and $u_2=3-3(-6)=21$."},{"title":"Choose the larger value","body":"The larger possible value of $u_2$ is $21$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q02","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":2,"marks":5,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":[],"secondaryTopicNames":[],"topics":["07_SequencesSeries"],"topicNames":["Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q02_M05_07_SequencesSeries.png","downloadName":"WMA12-01_Y2023_Oct_Q02_M05_07_SequencesSeries.png","finalAnswer":"$(a)$ $u_2=\\dfrac23,\\ u_3=-4,\\ u_4=3$. $\\quad (b)$ $-8$.","steps":[{"title":"Find u2","body":"$u_2=2-\\dfrac4{u_1}=2-\\dfrac43=\\dfrac23$."},{"title":"Find u3","body":"$u_3=2-\\dfrac4{u_2}=2-\\dfrac4{2/3}=2-6=-4$."},{"title":"Find u4","body":"$u_4=2-\\dfrac4{u_3}=2-\\dfrac4{-4}=3$."},{"title":"Notice the cycle","body":"The sequence starts $3,\\dfrac23,-4,3,\\dfrac23,-4,\\ldots$, so it repeats every 3 terms."},{"title":"Sum one cycle","body":"$3+\\dfrac23-4=-\\dfrac13$."},{"title":"Use 100 terms","body":"There are $33$ complete cycles in the first $99$ terms, then one extra term $u_{100}=3$."},{"title":"Find the sum","body":"$\\displaystyle \\sum_{r=1}^{100}u_r=33\\left(-\\dfrac13\\right)+3=-11+3=-8$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q05","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":5,"marks":8,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":["06_GeometricSequences"],"secondaryTopicNames":["Geometric Sequences"],"topics":["07_SequencesSeries","06_GeometricSequences"],"topicNames":["Sequences & Series","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q05_M08_07_SequencesSeries.png","downloadName":"WMA12-01_Y2024_Jan_Q05_M08_07_SequencesSeries.png","finalAnswer":"$(i)$ $2$. $\\quad (ii)(a)$ Periodic. $\\quad (ii)(b)$ Order $3$. $\\quad (ii)(c)$ $\\dfrac{213}{2}$.","steps":[{"title":"Identify the geometric series","body":"$\\displaystyle \\sum_{r=1}^{\\infty}6(0.25)^r$ has first term $6(0.25)=1.5$ and common ratio $0.25$."},{"title":"Sum to infinity","body":"$S_\\infty=\\dfrac{1.5}{1-0.25}=\\dfrac{1.5}{0.75}=2$."},{"title":"Find the first few terms","body":"$u_1=3$. Then $u_2=\\dfrac{3-3}{3-2}=0$."},{"title":"Continue the recurrence","body":"$u_3=\\dfrac{0-3}{0-2}=\\dfrac32$, and $u_4=\\dfrac{\\frac32-3}{\\frac32-2}=3$."},{"title":"Show periodicity","body":"Since $u_4=3=u_1$, the terms repeat as $3,0,\\dfrac32,3,0,\\dfrac32,\\ldots$."},{"title":"State the order","body":"The repeating cycle has length $3$, so the order is $3$."},{"title":"Sum one cycle","body":"One full cycle sums to $3+0+\\dfrac32=\\dfrac92$."},{"title":"Use 70 terms","body":"Since $70=23\\cdot3+1$, the first $70$ terms contain $23$ complete cycles and one extra term $u_1=3$."},{"title":"Find the required sum","body":"$\\displaystyle \\sum_{n=1}^{70}u_n=23\\left(\\dfrac92\\right)+3=\\dfrac{207}{2}+\\dfrac{6}{2}=\\dfrac{213}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q01","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":1,"marks":5,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":[],"secondaryTopicNames":[],"topics":["07_SequencesSeries"],"topicNames":["Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q01_M05_07_SequencesSeries.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q01_M05_07_SequencesSeries.png","finalAnswer":"$(a)$ $u_2=6$. $\\quad (b)$ $37$.","steps":[{"title":"Use the recurrence at n equals one","body":"$u_3=3u_2-2u_1$."},{"title":"Substitute given values","body":"$4=3u_2-2(7)$, so $4=3u_2-14$."},{"title":"Find u2","body":"$3u_2=18$, hence $u_2=6$."},{"title":"Find u4","body":"$u_4=3u_3-2u_2=3(4)-2(6)=0$."},{"title":"Evaluate the sum","body":"$\\displaystyle \\sum_{r=1}^{4}(u_r+2r)=(7+2)+(6+4)+(4+6)+(0+8)$."},{"title":"Add the terms","body":"The sum is $9+10+10+8=37$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q02","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":2,"marks":7,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":[],"secondaryTopicNames":[],"topics":["07_SequencesSeries"],"topicNames":["Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q02_M07_07_SequencesSeries.png","downloadName":"WMA12-01_Y2024_Oct_Q02_M07_07_SequencesSeries.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $k=15$. $\\quad (c)$ $1125$.","steps":[{"title":"Find the first few terms","body":"$u_1=7$, $u_2=(-1)^1u_1+k=k-7$, $u_3=(-1)^2u_2+k=2k-7$, and $u_4=(-1)^3u_3+k=7-k$."},{"title":"Show u five","body":"$u_5=(-1)^4u_4+k=(7-k)+k=7$."},{"title":"Use the given sum","body":"$\\displaystyle \\sum_{r=1}^{4}u_r=7+(k-7)+(2k-7)+(7-k)=2k$."},{"title":"Find k","body":"Since $\\displaystyle \\sum_{r=1}^{4}u_r=30$, we have $2k=30$, so $k=15$."},{"title":"Write one repeated block","body":"With $k=15$, the first four terms are $7,8,23,-8$, and their sum is $30$. Since $u_5=u_1$, the pattern repeats every four terms."},{"title":"Sum 150 terms","body":"There are $37$ complete blocks in the first $150$ terms, with the first two terms left over. Hence $\\displaystyle \\sum_{r=1}^{150}u_r=37(30)+7+8=1125$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q07","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":7,"marks":9,"topic":"07_SequencesSeries","topicName":"Sequences & Series","primaryTopic":"07_SequencesSeries","primaryTopicName":"Sequences & Series","secondaryTopics":["05_ArithmeticSequences","06_GeometricSequences"],"secondaryTopicNames":["Arithmetic Sequences","Geometric Sequences"],"topics":["07_SequencesSeries","05_ArithmeticSequences","06_GeometricSequences"],"topicNames":["Sequences & Series","Arithmetic Sequences","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q07_M09_07_SequencesSeries.png","downloadName":"WMA12-01_Y2025_MayJune_Q07_M09_07_SequencesSeries.png","finalAnswer":"$(i)(a)$ $50$. $\\quad (i)(b)$ $46$. $\\quad (ii)$ $52033$.","steps":[{"title":"Identify the geometric sequence","body":"The first term is $10$ and the common ratio is $\\dfrac{8}{10}=0.8$."},{"title":"Find the sum to infinity","body":"$S_\\infty=\\dfrac{10}{1-0.8}=50$."},{"title":"Write the kth term","body":"The $k$th term is $10(0.8)^{k-1}$."},{"title":"Use the inequality","body":"$10(0.8)^{k-1}<0.0005$, so $(0.8)^{k-1}<0.00005$."},{"title":"Solve with logarithms","body":"Taking logarithms gives $(k-1)\\log(0.8)<\\log(0.00005)$. Since $\\log(0.8)<0$, $k-1>\\dfrac{\\log(0.00005)}{\\log(0.8)}=44.381\\ldots$."},{"title":"Find the smallest integer","body":"Thus $k>45.381\\ldots$, so the smallest possible value is $k=46$."},{"title":"Write the arithmetic sum","body":"For $850+843+836+\\cdots$, the first term is $850$ and the common difference is $-7$."},{"title":"Form S n","body":"$S_n=\\dfrac n2\\{2(850)+(n-1)(-7)\\}=\\dfrac n2(1707-7n)$."},{"title":"Find the best integer n","body":"This quadratic has its maximum near $n=\\dfrac{1707}{14}=121.928\\ldots$, so check $n=122$."},{"title":"Find the greatest sum","body":"$S_{122}=\\dfrac{122}{2}(1707-854)=61(853)=52033$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q02","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":2,"marks":6,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["06_GeometricSequences"],"secondaryTopicNames":["Geometric Sequences"],"topics":["08_ModellingSequencesSeries","06_GeometricSequences"],"topicNames":["Modelling with Sequences & Series","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q02_M06_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2019_Oct_Q02_M06_08_ModellingSequencesSeries.png","finalAnswer":"$(a)$ 32341 adults, approximately. $\\quad (b)$ £1,997,000.","steps":[{"title":"Identify the common ratio","body":"An increase of $2\\%$ each year gives the geometric ratio $r=1.02$."},{"title":"Count the years to 2032","body":"From the start of 2019 to the start of 2032 there are $13$ yearly increases, so the population is $25000(1.02)^{13}$."},{"title":"Calculate the 2032 population","body":"$25000(1.02)^{13}\\approx32340.7$, so the model gives about $32341$ adults."},{"title":"Set up the total number of adult payments","body":"From 2019 to 2032 inclusive there are $14$ yearly populations, so the total number of adult payments is $25000\\dfrac{1.02^{14}-1}{1.02-1}$."},{"title":"Multiply by the charity amount","body":"The total money is $5\\times25000\\dfrac{1.02^{14}-1}{0.02}\\approx1\\,996\\,766$, so this is about £1,996,766."},{"title":"Round as requested","body":"To the nearest £1000, this is £1,997,000."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q05","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":5,"marks":8,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["06_GeometricSequences","09_LawsOfLogarithms"],"secondaryTopicNames":["Geometric Sequences","Laws of Logarithms"],"topics":["08_ModellingSequencesSeries","06_GeometricSequences","09_LawsOfLogarithms"],"topicNames":["Modelling with Sequences & Series","Geometric Sequences","Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q05_M08_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2020_Jan_Q05_M08_08_ModellingSequencesSeries.png","finalAnswer":"$(a)\\ p=4.26.\\quad (b)\\ N=22$.","steps":[{"title":"Set up the growth ratio","body":"Let the yearly ratio be $r$. After 3 years, $30000r^3=34000$."},{"title":"Find p","body":"$r^3=\\dfrac{17}{15}$, so $r=\\left(\\dfrac{17}{15}\\right)^{1/3}\\approx1.04257$. Therefore $p=(r-1)\\times100\\approx4.26$."},{"title":"Set up the inequality","body":"After $N$ years the model gives $30000r^N$. We need $30000r^N>75000$, so $r^N>2.5$."},{"title":"Take logarithms","body":"$N\\log r>\\log(2.5)$, so $N>\\dfrac{\\log(2.5)}{\\log r}$."},{"title":"Find the smallest integer","body":"Using $r\\approx1.04257$, $\\dfrac{\\log(2.5)}{\\log r}\\approx21.98$. Hence the smallest integer value is $N=22$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q10","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":10,"marks":11,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["05_ArithmeticSequences","06_GeometricSequences"],"secondaryTopicNames":["Arithmetic Sequences","Geometric Sequences"],"topics":["08_ModellingSequencesSeries","05_ArithmeticSequences","06_GeometricSequences"],"topicNames":["Modelling with Sequences & Series","Arithmetic Sequences","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q10_M11_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2021_Jan_Q10_M11_08_ModellingSequencesSeries.png","finalAnswer":"$(a)\\ 23\\text{ km}.\\quad (b)\\ 20.8\\text{ km}.\\quad (c)(i)\\ x=4.\\quad (c)(ii)\\ x=5$.","steps":[{"title":"Find the arithmetic difference","body":"Plan A has $12$ Sunday runs from $15$ km to $37$ km, so there are $11$ equal increases. The common difference is $\\dfrac{37-15}{11}=2$."},{"title":"Find week five for plan A","body":"Week $5$ is the fifth term, so the distance is $15+4(2)=23\\text{ km}$."},{"title":"Find the geometric ratio","body":"For plan B, $15r^{11}=37$, so $r=\\left(\\dfrac{37}{15}\\right)^{1/11}$."},{"title":"Find week five for plan B","body":"The fifth Sunday distance is $15r^4=15\\left(\\dfrac{37}{15}\\right)^{4/11}=20.829\\ldots$, so it is $20.8\\text{ km}$."},{"title":"Sum the Sunday runs for plan A","body":"The arithmetic total is $\\dfrac{12}{2}(15+37)=312$ km."},{"title":"Find the Wednesday limit for plan A","body":"The total distance condition gives $312+12x\\leq360$, so $x\\leq4$. The maximum integer is $4$."},{"title":"Sum the Sunday runs for plan B","body":"The geometric total is $15\\dfrac{r^{12}-1}{r-1}=294.185\\ldots$ km."},{"title":"Find the Wednesday limit for plan B","body":"Now $294.185\\ldots+12x\\leq360$, so $x\\leq5.484\\ldots$. The maximum integer is $5$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q01","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":1,"marks":7,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["05_ArithmeticSequences"],"secondaryTopicNames":["Arithmetic Sequences"],"topics":["08_ModellingSequencesSeries","05_ArithmeticSequences"],"topicNames":["Modelling with Sequences & Series","Arithmetic Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q01_M07_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2021_MayJune_Q01_M07_08_ModellingSequencesSeries.png","finalAnswer":"$(a)(i)$ Arithmetic series. $\\quad (a)(ii)\\ 5+0.25(n-1)$. $\\quad (b)\\ 37$ weeks.","steps":[{"title":"Choose the model","body":"The weekly amounts are $5$, $5.25$, $5.50$, and so on. The increase is a constant $0.25$, so an arithmetic series should be used."},{"title":"Write the nth amount","body":"The first amount is $5$ and the common difference is $0.25$, so the amount saved in week $n$ is $5+0.25(n-1)$."},{"title":"Set up the total","body":"After $n$ weeks, $S_n=\\dfrac n2\\{2(5)+(n-1)(0.25)\\}$."},{"title":"Form the inequality","body":"Adina needs $S_n\\geq350$, so $\\dfrac n2(9.75+0.25n)\\geq350$."},{"title":"Solve for n","body":"This is $n^2+39n-2800\\geq0$. The positive root is $36.89\\ldots$, so the first whole number that works is $n=37$."},{"title":"Check the week","body":"After $36$ weeks the total is below $350$, and after $37$ weeks it is $351.50$, so it takes $37$ weeks."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q08","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":8,"marks":9,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["05_ArithmeticSequences","06_GeometricSequences"],"secondaryTopicNames":["Arithmetic Sequences","Geometric Sequences"],"topics":["08_ModellingSequencesSeries","05_ArithmeticSequences","06_GeometricSequences"],"topicNames":["Modelling with Sequences & Series","Arithmetic Sequences","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q08_M09_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2022_Jan_Q08_M09_08_ModellingSequencesSeries.png","finalAnswer":"$(a)$ Proven: $62$ mm. $\\quad (b)\\ 1620$ mm. $\\quad (c)\\ r=0.984.\\quad (d)\\ N=48$.","steps":[{"title":"Use the arithmetic rule","body":"For the first $20$ hits, the additional distances form an arithmetic sequence with first term $100$ and common difference $-2$."},{"title":"Show the twentieth hit","body":"The twentieth additional distance is $100+19(-2)=62$ mm."},{"title":"Sum the first twenty hits","body":"$S_{20}=\\dfrac{20}{2}(100+62)=1620$ mm."},{"title":"Use the geometric information","body":"After the twentieth hit, the distances follow the same ratio, so the twenty second distance is $62r^2$."},{"title":"Find r","body":"$62r^2=60$, hence $r=\\sqrt{\\dfrac{30}{31}}=0.984$ to 3 decimal places."},{"title":"Set up the remaining distance","body":"More than $3$ m means more than $3000$ mm. After $20$ hits, the remaining amount to exceed is $3000-1620=1380$ mm."},{"title":"Sum the geometric tail","body":"If there are $m$ further hits, their total is $62r+62r^2+\\cdots+62r^m=62r\\dfrac{1-r^m}{1-r}$."},{"title":"Find the first m that works","body":"Using $r=\\sqrt{30/31}$, $62r\\dfrac{1-r^{27}}{1-r}$ is not enough, but $62r\\dfrac{1-r^{28}}{1-r}$ makes the total exceed $3000$ mm."},{"title":"State N","body":"Therefore $m=28$ further hits are needed after the first $20$, so $N=20+28=48$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q09","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":9,"marks":9,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["09_LawsOfLogarithms"],"secondaryTopicNames":["Laws of Logarithms"],"topics":["08_ModellingSequencesSeries","09_LawsOfLogarithms"],"topicNames":["Modelling with Sequences & Series","Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q09_M09_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2022_MayJune_Q09_M09_08_ModellingSequencesSeries.png","finalAnswer":"$(a)$ Decreasing exponential through $(0,1)$. $\\quad (b)\\ \\lambda=0.999878$. $\\quad (c)\\ 10.1\\text{ g}.\\quad (d)\\ 2700$ years.","steps":[{"title":"Sketch the model for k equals one","body":"For $k=1$, $N=\\lambda^t$ with $0<\\lambda<1$. The graph starts at $(0,1)$, decreases as $t$ increases, and tends towards $0$."},{"title":"Use the half-life information","body":"After $5700$ years, $N=\\dfrac{k}{2}$, so $k\\lambda^{5700}=\\dfrac{k}{2}$."},{"title":"Find lambda","body":"$\\lambda^{5700}=\\dfrac12$, hence $\\lambda=\\left(\\dfrac12\\right)^{1/5700}=0.999878\\ldots$, so $\\lambda=0.999878$ to 6 decimal places."},{"title":"Model item A","body":"For item A, $k=15$ and $t=3250$, so $N=15\\lambda^{3250}$."},{"title":"Calculate item A","body":"$N=15(0.9998784026\\ldots)^{3250}=10.103\\ldots$, so the current amount is $10.1$ g to 3 significant figures."},{"title":"Set up item B","body":"For item B, $18=25\\lambda^t$, so $\\lambda^t=\\dfrac{18}{25}$."},{"title":"Take logarithms","body":"$t\\log\\lambda=\\log\\left(\\dfrac{18}{25}\\right)$, so $t=\\dfrac{\\log(18/25)}{\\log\\lambda}$."},{"title":"Round the age","body":"Using $\\lambda=(1/2)^{1/5700}$ gives $t=2701\\ldots$, so the age is $2700$ years to the nearest $100$ years."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q07","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":7,"marks":9,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["05_ArithmeticSequences","06_GeometricSequences"],"secondaryTopicNames":["Arithmetic Sequences","Geometric Sequences"],"topics":["08_ModellingSequencesSeries","05_ArithmeticSequences","06_GeometricSequences"],"topicNames":["Modelling with Sequences & Series","Arithmetic Sequences","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q07_M09_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2024_Jan_Q07_M09_08_ModellingSequencesSeries.png","finalAnswer":"$(a)$ $1310$ tonnes. $\\quad (b)$ $380$ tonnes. $\\quad (c)$ $7860$ tonnes.","steps":[{"title":"Model A common difference","body":"Model A is arithmetic. From year 1 to year 12 there are $11$ equal increases, so $d=\\dfrac{4000-300}{11}=\\dfrac{3700}{11}$."},{"title":"Find year 4 in model A","body":"Year 4 is $300+3d=300+3\\left(\\dfrac{3700}{11}\\right)=1309.09\\ldots$, so the amount is $1310$ tonnes to the nearest $10$ tonnes."},{"title":"Model B common ratio","body":"Model B is geometric. If the ratio is $r$, then $300r^{11}=4000$."},{"title":"Find the ratio","body":"$r=\\left(\\dfrac{4000}{300}\\right)^{1/11}=1.2655\\ldots$."},{"title":"Find year 2 in model B","body":"Year 2 is $300r=379.65\\ldots$, so the amount is $380$ tonnes to the nearest $10$ tonnes."},{"title":"Total for model A","body":"$S_A=\\dfrac{12}{2}(300+4000)=25800$ tonnes."},{"title":"Total for model B","body":"$S_B=300\\dfrac{r^{12}-1}{r-1}=17935.20\\ldots$ tonnes."},{"title":"Find the difference","body":"The difference is $25800-17935.20\\ldots=7864.79\\ldots$, which is $7860$ tonnes to the nearest $10$ tonnes."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q10","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":10,"marks":8,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["06_GeometricSequences","09_LawsOfLogarithms"],"secondaryTopicNames":["Geometric Sequences","Laws of Logarithms"],"topics":["08_ModellingSequencesSeries","06_GeometricSequences","09_LawsOfLogarithms"],"topicNames":["Modelling with Sequences & Series","Geometric Sequences","Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q10_M08_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2024_MayJune_Q10_M08_08_ModellingSequencesSeries.png","finalAnswer":"$(a)$ $2390$ dormice. $\\quad (b)$ $N=4000(0.98)^t$ to 2 s.f. constants. $\\quad (c)$ $T=13.9$.","steps":[{"title":"Model the dormice","body":"The dormice model is $D=2000(1.03)^t$."},{"title":"Find the dormice after six years","body":"$D=2000(1.03)^6=2388.10\\ldots$, so there are $2390$ dormice to 3 significant figures."},{"title":"Set up the vole model","body":"Let the vole model be $N=ab^t$."},{"title":"Use the two data points","body":"At $t=4$, $ab^4=3690$. At $t=7$, $ab^7=3470$."},{"title":"Find b","body":"Dividing gives $b^3=\\dfrac{3470}{3690}$, so $b=0.9797\\ldots$, which is $0.98$ to 2 significant figures."},{"title":"Find a","body":"$a=\\dfrac{3690}{b^4}=4005.18\\ldots$, which is $4000$ to 2 significant figures."},{"title":"Write the vole model","body":"So the model is approximately $N=4000(0.98)^t$."},{"title":"Set the two models equal","body":"Use $2000(1.03)^T=a b^T$ with the unrounded constants from the vole model."},{"title":"Solve using logarithms","body":"$\\left(\\dfrac{1.03}{b}\\right)^T=\\dfrac{a}{2000}$, so $T=\\dfrac{\\log(a/2000)}{\\log(1.03/b)}$."},{"title":"Calculate T","body":"Substituting $a=4005.18\\ldots$ and $b=0.9797\\ldots$ gives $T=13.875\\ldots$, so $T=13.9$ to one decimal place."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q07","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":7,"marks":6,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["05_ArithmeticSequences","06_GeometricSequences"],"secondaryTopicNames":["Arithmetic Sequences","Geometric Sequences"],"topics":["08_ModellingSequencesSeries","05_ArithmeticSequences","06_GeometricSequences"],"topicNames":["Modelling with Sequences & Series","Arithmetic Sequences","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q07_M06_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2024_Oct_Q07_M06_08_ModellingSequencesSeries.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ £28,425. $\\quad (c)$ £1,060.","steps":[{"title":"Identify Jem's sequence","body":"Jem's payments are arithmetic with first term $20$ and common difference $0.50$."},{"title":"Show month 100","body":"The month $100$ payment is $20+99(0.50)=69.50$, so Jem pays £69.50."},{"title":"Sum Jem's payments","body":"$S_{300}=\\dfrac{300}{2}\\{2(20)+299(0.50)\\}=150(189.5)=28425$."},{"title":"Model Kim's payments","body":"Let the common ratio be $r$. Since the first payment is $20$ and the month $300$ payment is $250$, $20r^{299}=250$."},{"title":"Find the ratio","body":"Thus $r^{299}=12.5$ and $r=12.5^{1/299}$."},{"title":"Sum Kim's payments","body":"$S_B=20\\dfrac{r^{300}-1}{r-1}$ with $r=12.5^{1/299}$, giving $S_B\\approx27362.95$."},{"title":"Find the difference","body":"The difference is $28425-27362.95\\approx1062.05$, which is £1,060 to the nearest £10."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q09","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":9,"marks":10,"topic":"08_ModellingSequencesSeries","topicName":"Modelling with Sequences & Series","primaryTopic":"08_ModellingSequencesSeries","primaryTopicName":"Modelling with Sequences & Series","secondaryTopics":["05_ArithmeticSequences","06_GeometricSequences"],"secondaryTopicNames":["Arithmetic Sequences","Geometric Sequences"],"topics":["08_ModellingSequencesSeries","05_ArithmeticSequences","06_GeometricSequences"],"topicNames":["Modelling with Sequences & Series","Arithmetic Sequences","Geometric Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q09_M10_08_ModellingSequencesSeries.png","downloadName":"WMA12-01_Y2026_Jan_Q09_M10_08_ModellingSequencesSeries.png","finalAnswer":"$(a)\\ 11000$ tonnes. $\\quad (b)\\ 149250$ tonnes. $\\quad (c)\\ 8980$ tonnes. $\\quad (d)\\ 351500$ tonnes.","steps":[{"title":"Model A as an arithmetic sequence","body":"For Model A, let the common difference be $d$. Since year 15 is the 15th term, $7500=12400+14d$."},{"title":"Find year 5 for Model A","body":"$d=\\dfrac{7500-12400}{14}=-350$. Year 5 is $12400+4(-350)=11000$ tonnes."},{"title":"Find the total from year 1 to year 15","body":"$S_{15}=\\dfrac{15}{2}(12400+7500)=149250$ tonnes."},{"title":"Model B as a geometric sequence","body":"Let the common ratio be $r$. Then $7500=12400r^{14}$, so $r=\\left(\\dfrac{7500}{12400}\\right)^{1/14}\\approx0.964723$."},{"title":"Find year 10 for Model B","body":"Year 10 is $12400r^9\\approx8975.26$, which is $8980$ tonnes to the nearest 10 tonnes."},{"title":"Find the limiting total","body":"Since $0<r<1$, the sum to infinity is $S_\\infty=\\dfrac{12400}{1-r}\\approx351508.1$, so the limit is $351500$ tonnes to the nearest 100 tonnes."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q07","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":7,"marks":7,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["09_LawsOfLogarithms","07_SequencesSeries"],"topicNames":["Laws of Logarithms","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q07_M07_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2019_Oct_Q07_M07_09_LawsOfLogarithms.png","finalAnswer":"$(i)\\ \\dfrac12-k.\\quad (ii)\\ \\dfrac{k+2}{3k}.\\quad (iii)\\ 1325k$.","steps":[{"title":"Use the given logarithm","body":"Since $\\log_a b=k$, we can replace every $\\log_a b$ by $k$."},{"title":"Simplify part (i)","body":"$\\log_a\\left(\\dfrac{\\sqrt a}{b}\\right)=\\log_a(a^{1/2})-\\log_a b=\\dfrac12-k$."},{"title":"Simplify the numerator and denominator","body":"$\\log_a(a^2b)=\\log_a a^2+\\log_a b=2+k$, and $\\log_a(b^3)=3\\log_a b=3k$."},{"title":"Write part (ii)","body":"Therefore $\\dfrac{\\log_a(a^2b)}{\\log_a(b^3)}=\\dfrac{k+2}{3k}$."},{"title":"Simplify the summand","body":"$\\log_a(b^n)=n\\log_a b=nk$, so $k+\\log_a(b^n)=k+nk=(n+1)k$."},{"title":"Sum the series","body":"$\\sum_{n=1}^{50}(n+1)k=k\\left(\\sum_{n=1}^{50}n+50\\right)=k(1275+50)=1325k$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q09","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":9,"marks":7,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q09_M07_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2020_Jan_Q09_M07_09_LawsOfLogarithms.png","finalAnswer":"$(a)$ Increasing exponential curve through $(0,3)$, with no $x$-axis intersection. $\\quad (b)\\ x=\\dfrac{\\log_{10}2}{\\log_{10}24}$.","steps":[{"title":"Describe the sketch","body":"$y=3\\times4^x$ is an increasing exponential curve. At $x=0$, $y=3$, so the curve crosses the $y$-axis at $(0,3)$ and has no $x$-axis intersection."},{"title":"Equate the two curves","body":"At $P$, $6^{1-x}=3\\times4^x$."},{"title":"Take logarithms","body":"$(1-x)\\log_{10}6=\\log_{10}3+x\\log_{10}4$."},{"title":"Collect the x terms","body":"$\\log_{10}6-\\log_{10}3=x(\\log_{10}4+\\log_{10}6)$."},{"title":"Simplify the logarithms","body":"$\\log_{10}6-\\log_{10}3=\\log_{10}2$ and $\\log_{10}4+\\log_{10}6=\\log_{10}24$."},{"title":"State the x coordinate","body":"Therefore $x=\\dfrac{\\log_{10}2}{\\log_{10}24}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q03","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":3,"marks":8,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q03_M08_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2021_Jan_Q03_M08_09_LawsOfLogarithms.png","finalAnswer":"$(i)\\ x=\\log_7\\left(\\dfrac3{49}\\right).\\quad (ii)\\ y=\\dfrac12$.","steps":[{"title":"Rewrite the exponential equation","body":"From $7^{x+2}=3$, divide by $7^2$ to get $7^x=\\dfrac3{49}$."},{"title":"Write x as a logarithm","body":"Therefore $x=\\log_7\\left(\\dfrac3{49}\\right)$."},{"title":"Convert one to a logarithm","body":"Since $1=\\log_2 2$, the equation becomes $\\log_2 2+\\log_2 y+\\log_2(y+4)=\\log_2(5-y)$."},{"title":"Combine the logarithms","body":"$\\log_2\\{2y(y+4)\\}=\\log_2(5-y)$."},{"title":"Solve the quadratic","body":"Thus $2y(y+4)=5-y$, so $2y^2+9y-5=0=(2y-1)(y+5)$."},{"title":"Check the domain","body":"The original logarithms require $y>0$ and $y<5$, so $y=-5$ is invalid and $y=\\dfrac12$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q02","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":2,"marks":8,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q02_M08_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2021_MayJune_Q02_M08_09_LawsOfLogarithms.png","finalAnswer":"$(a)(i)$ Sketch $y=2^x$ through $(0,1)$ with no $x$-axis intercept. $(a)(ii)$ Sketch $y=4^x-6$ through $(0,-5)$ and $(\\log_4 6,0)$. $\\quad (b)\\ P=(\\log_2 3,3)$.","steps":[{"title":"Describe y equals two to the x","body":"$y=2^x$ is an increasing exponential curve. It crosses the $y$-axis at $(0,1)$ and has no $x$-axis intercept."},{"title":"Describe y equals four to the x minus six","body":"$y=4^x-6$ is the graph of $y=4^x$ translated $6$ units down. It crosses the $y$-axis at $(0,-5)$."},{"title":"Find the x-axis intercept","body":"For $y=4^x-6$, set $4^x-6=0$. Hence $4^x=6$ and $x=\\log_4 6$."},{"title":"Set up the intersection equation","body":"At $P$, $2^x=4^x-6$."},{"title":"Use a substitution","body":"Let $u=2^x$. Then $4^x=(2^x)^2=u^2$, so $u=u^2-6$."},{"title":"Solve for u","body":"$u^2-u-6=0$, so $(u-3)(u+2)=0$. Since $u=2^x>0$, $u=3$."},{"title":"State P","body":"$2^x=3$, so $x=\\log_2 3$, and $y=3$. Therefore $P=(\\log_2 3,3)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q07","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":7,"marks":10,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":["02_Polynomials"],"secondaryTopicNames":["Polynomials"],"topics":["09_LawsOfLogarithms","02_Polynomials"],"topicNames":["Laws of Logarithms","Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q07_M10_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2021_MayJune_Q07_M10_09_LawsOfLogarithms.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $-4$ is a root of the cubic. $\\quad (c)\\ x=2,\\ \\dfrac72$.","steps":[{"title":"Use the power law","body":"$3\\log_3(2x-1)=\\log_3(2x-1)^3$."},{"title":"Rewrite two as a logarithm","body":"Since $2=\\log_3 9$, the right side is $\\log_3 9+\\log_3(14x-25)=\\log_3\\{9(14x-25)\\}$."},{"title":"Equate the arguments","body":"So $(2x-1)^3=9(14x-25)$."},{"title":"Expand and simplify","body":"$8x^3-12x^2+6x-1=126x-225$, which simplifies to $2x^3-3x^2-30x+56=0$."},{"title":"Check the given root","body":"Substituting $x=-4$ gives $2(-64)-3(16)-30(-4)+56=0$, so $-4$ is a root."},{"title":"Factorise the cubic","body":"Dividing by $(x+4)$ gives $2x^2-11x+14=(2x-7)(x-2)$."},{"title":"Apply the logarithm domain","body":"The possible roots are $-4$, $2$, and $\\dfrac72$. The original logarithms require $2x-1>0$ and $14x-25>0$, so $x>\\dfrac{25}{14}$."},{"title":"State the valid solutions","body":"Therefore the solutions are $x=2$ and $x=\\dfrac72$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q04","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":4,"marks":5,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q04_M05_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2022_Jan_Q04_M05_09_LawsOfLogarithms.png","finalAnswer":"$x=-\\dfrac19$.","steps":[{"title":"Rewrite the right side","body":"$2\\log_3(1-x)=\\log_3(1-x)^2$ and $3=\\log_3 27$."},{"title":"Combine the logarithms","body":"The equation becomes $\\log_3(32-12x)=\\log_3\\{27(1-x)^2\\}$."},{"title":"Equate the arguments","body":"$32-12x=27(1-x)^2$."},{"title":"Form the quadratic","body":"$32-12x=27-54x+27x^2$, so $27x^2-42x-5=0$."},{"title":"Solve","body":"$x=\\dfrac{42\\pm48}{54}$, giving $x=\\dfrac53$ or $x=-\\dfrac19$."},{"title":"Check the domain","body":"The original logarithms require $1-x>0$, so $x<1$. Therefore $x=\\dfrac53$ is invalid and $x=-\\dfrac19$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q04","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":4,"marks":6,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q04_M06_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2022_MayJune_Q04_M06_09_LawsOfLogarithms.png","finalAnswer":"$a=4+4\\sqrt5,\\quad b=4\\sqrt5-4$.","steps":[{"title":"Combine the logarithms","body":"$\\log_4 a+\\log_4 b=\\log_4(ab)=3$."},{"title":"Find ab","body":"Therefore $ab=4^3=64$."},{"title":"Use a minus b","body":"From $a-b=8$, $b=a-8$."},{"title":"Form a quadratic","body":"$a(a-8)=64$, so $a^2-8a-64=0$."},{"title":"Solve for a","body":"$a=\\dfrac{8\\pm\\sqrt{64+256}}{2}=4\\pm4\\sqrt5$."},{"title":"Choose positive constants","body":"Since $b=a-8$ must also be positive, take $a=4+4\\sqrt5$."},{"title":"Find b","body":"$b=a-8=4\\sqrt5-4$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q04","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":4,"marks":8,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["09_LawsOfLogarithms","08_ModellingSequencesSeries"],"topicNames":["Laws of Logarithms","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q04_M08_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2022_Oct_Q04_M08_09_LawsOfLogarithms.png","finalAnswer":"$(a)$ $a=1.072$ to 3 d.p. $\\quad (b)\\ t=4(1.072)^w-5$. $\\quad (c)\\ t=6.35$ months to 3 s.f.","steps":[{"title":"Substitute the given information","body":"When $t=3$, $w=10$. So $10=\\log_a(3+5)-\\log_a4=\\log_a8-\\log_a4$."},{"title":"Combine the logarithms","body":"$\\log_a8-\\log_a4=\\log_a\\left(\\dfrac84\\right)=\\log_a2$, so $10=\\log_a2$."},{"title":"Find a","body":"$10=\\log_a2$ means $a^{10}=2$, hence $a=2^{1/10}=1.071773\\ldots=1.072$ to 3 decimal places."},{"title":"Start from the model","body":"Using $a=1.072$, $w=\\log_{1.072}(t+5)-\\log_{1.072}4$."},{"title":"Combine the logs again","body":"$w=\\log_{1.072}\\left(\\dfrac{t+5}{4}\\right)$."},{"title":"Make t the subject","body":"Changing from logarithmic form to exponential form gives $(1.072)^w=\\dfrac{t+5}{4}$, so $t=4(1.072)^w-5$."},{"title":"Substitute w equals fifteen","body":"When $w=15$, $t=4(1.072)^{15}-5=6.3496\\ldots$, so $t=6.35$ months to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q10","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":10,"marks":7,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q10_M07_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2022_Oct_Q10_M07_09_LawsOfLogarithms.png","finalAnswer":"$(i)(a)\\ 2a. $\\quad $(i)(b)\\ \\dfrac{a}{2}-4. $\\quad $(ii)\\ x=\\dfrac{a-3}{a+1}$.","steps":[{"title":"Use the power rule for log 2 of 9","body":"$\\log_2 9=\\log_2(3^2)=2\\log_2 3=2a$."},{"title":"Split the second logarithm","body":"$\\log_2\\left(\\dfrac{\\sqrt3}{16}\\right)=\\log_2(3^{1/2})-\\log_2(16)$."},{"title":"Simplify in terms of a","body":"$\\log_2(3^{1/2})=\\dfrac12\\log_2 3=\\dfrac a2$ and $\\log_2(16)=4$, so the expression is $\\dfrac a2-4$."},{"title":"Take log base 2 of both sides","body":"For $3^x\\times2^{x+4}=6$, take $\\log_2$ of both sides: $\\log_2(3^x)+\\log_2(2^{x+4})=\\log_2 6$."},{"title":"Rewrite each term","body":"$\\log_2(3^x)=xa$, $\\log_2(2^{x+4})=x+4$, and $\\log_2 6=\\log_2(2\\cdot3)=1+a$."},{"title":"Solve for x","body":"So $xa+x+4=a+1$. Hence $x(a+1)=a-3$, giving $x=\\dfrac{a-3}{a+1}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q04","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":4,"marks":6,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":["07_SequencesSeries"],"secondaryTopicNames":["Sequences & Series"],"topics":["09_LawsOfLogarithms","07_SequencesSeries"],"topicNames":["Laws of Logarithms","Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q04_M06_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2023_Jan_Q04_M06_09_LawsOfLogarithms.png","finalAnswer":"$(i)$ $x=\\dfrac{7}{31}$. $\\quad (ii)$ $y=a^2$.","steps":[{"title":"Rewrite the constant","body":"Since $2=\\log_3 9$, the equation becomes $\\log_3(4x)+\\log_3 9=\\log_3(5x+7)$."},{"title":"Combine the logarithms","body":"$\\log_3(4x)+\\log_3 9=\\log_3(36x)$."},{"title":"Solve for x","body":"Therefore $36x=5x+7$, so $31x=7$ and $x=\\dfrac{7}{31}$."},{"title":"Introduce L","body":"Let $L=\\log_a y$. Then $\\log_a(y^r)=r\\log_a y=rL$."},{"title":"Evaluate the left sum","body":"$\\displaystyle \\sum_{r=1}^{2}\\log_a(y^r)=L+2L=3L$."},{"title":"Evaluate the right sum","body":"$\\displaystyle \\sum_{r=1}^{2}(\\log_a y)^r=L+L^2$."},{"title":"Solve for L","body":"So $3L=L+L^2$, which gives $L^2-2L=0$ and $L(L-2)=0$."},{"title":"Use the restrictions","body":"Since $a>1$ and $y>1$, $\\log_a y>0$, so $L\\ne0$. Hence $L=2$ and $y=a^2$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q05","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":5,"marks":5,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q05_M05_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2023_MayJune_Q05_M05_09_LawsOfLogarithms.png","finalAnswer":"$x=\\dfrac32$.","steps":[{"title":"State the domain","body":"The logarithms require $16x>0$, $x+1>0$ and $x+6>0$, so $x>0$."},{"title":"Combine the left side","body":"$\\log_2(16x)+\\log_2(x+1)=\\log_2(16x(x+1))$."},{"title":"Rewrite the right side","body":"$3=\\log_2 8$, so $3+\\log_2(x+6)=\\log_2(8(x+6))$."},{"title":"Equate the arguments","body":"Therefore $16x(x+1)=8(x+6)$."},{"title":"Solve the quadratic","body":"$16x^2+16x=8x+48$, so $16x^2+8x-48=0$. Dividing by $8$ gives $2x^2+x-6=0$."},{"title":"Factor and use the domain","body":"$(2x-3)(x+2)=0$, so $x=\\dfrac32$ or $x=-2$. The domain $x>0$ rejects $-2$, leaving $x=\\dfrac32$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q05","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":5,"marks":6,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q05_M06_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2023_Oct_Q05_M06_09_LawsOfLogarithms.png","finalAnswer":"$(i)$ $a=3.867$. $\\quad (ii)$ $b=\\dfrac{\\sqrt5}{9}$.","steps":[{"title":"Solve the exponential equation","body":"$3^a=70$ gives $a=\\log_3 70=\\dfrac{\\log 70}{\\log 3}$."},{"title":"Round a","body":"$a=3.867147\\ldots$, so $a=3.867$ to 3 decimal places."},{"title":"Rewrite four as a logarithm","body":"$4=\\log_3(3^4)=\\log_3 81$."},{"title":"Combine the left side","body":"$4+3\\log_3 b=\\log_3 81+\\log_3(b^3)=\\log_3(81b^3)$."},{"title":"Equate arguments","body":"The equation becomes $\\log_3(81b^3)=\\log_3(5b)$, so $81b^3=5b$."},{"title":"Use the log domain","body":"Since $\\log_3 b$ is defined, $b>0$. Divide by $b$ to get $81b^2=5$."},{"title":"Find b","body":"$b^2=\\dfrac{5}{81}$, and $b>0$, so $b=\\dfrac{\\sqrt5}{9}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q06","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":6,"marks":8,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":["02_Polynomials"],"secondaryTopicNames":["Polynomials"],"topics":["09_LawsOfLogarithms","02_Polynomials"],"topicNames":["Laws of Logarithms","Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q06_M08_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2024_Jan_Q06_M08_09_LawsOfLogarithms.png","finalAnswer":"$(a)$ Proven. $\\quad (b)(i)$ $x=\\dfrac{-5+\\sqrt{41}}{2}$ and $x=\\dfrac{-5-\\sqrt{41}}{2}$. $\\quad (b)(ii)$ $x=\\dfrac{-5+\\sqrt{41}}{2}$.","steps":[{"title":"Combine the logarithms","body":"$2\\log_4(x+3)=\\log_4((x+3)^2)$, so the left side is $\\log_4(x(x+3)^2)$."},{"title":"Rewrite one half","body":"$\\dfrac12=\\log_4 2$, so the right side is $\\log_4(4x+2)+\\log_4 2=\\log_4(8x+4)$."},{"title":"Equate arguments","body":"Therefore $x(x+3)^2=8x+4$."},{"title":"Expand","body":"$x(x^2+6x+9)=8x+4$, so $x^3+6x^2+9x=8x+4$."},{"title":"Show the cubic","body":"Rearranging gives $x^3+6x^2+x-4=0$."},{"title":"Use the given root","body":"Since $-1$ is a root, $(x+1)$ is a factor of $x^3+6x^2+x-4$."},{"title":"Factor the cubic","body":"$x^3+6x^2+x-4=(x+1)(x^2+5x-4)$."},{"title":"Solve the quadratic","body":"$x^2+5x-4=0$ gives $x=\\dfrac{-5\\pm\\sqrt{25+16}}{2}=\\dfrac{-5\\pm\\sqrt{41}}{2}$."},{"title":"Apply the logarithm domain","body":"The original log equation requires $x>0$. The only positive root is $x=\\dfrac{-5+\\sqrt{41}}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q03","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":3,"marks":6,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q03_M06_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2024_MayJune_Q03_M06_09_LawsOfLogarithms.png","finalAnswer":"$(i)$ $x=-6$. $\\quad (ii)$ $12$.","steps":[{"title":"State the domain","body":"The logarithms require $2-x>0$ and $x+10>0$, so $-10<x<2$."},{"title":"Combine powers","body":"$2\\log_2(2-x)=\\log_2((2-x)^2)$."},{"title":"Rewrite four","body":"$4=\\log_2 16$, so $4+\\log_2(x+10)=\\log_2(16(x+10))$."},{"title":"Equate arguments","body":"$(2-x)^2=16(x+10)$."},{"title":"Solve the quadratic","body":"$x^2-4x+4=16x+160$, so $x^2-20x-156=0$."},{"title":"Use the domain","body":"$x=26$ or $x=-6$. The value $26$ is outside the domain, so $x=-6$."},{"title":"Evaluate the logarithm","body":"$\\log_{\\sqrt a}(a^6)=\\log_{a^{1/2}}(a^6)=\\dfrac{6}{1/2}=12$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q09","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":9,"marks":9,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":["02_Polynomials"],"secondaryTopicNames":["Polynomials"],"topics":["09_LawsOfLogarithms","02_Polynomials"],"topicNames":["Laws of Logarithms","Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q09_M09_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q09_M09_09_LawsOfLogarithms.png","finalAnswer":"$(a)$ Verified. $\\quad (b)$ Proven. $\\quad (c)$ $t=4$ or $t=56+12\\sqrt{21}$.","steps":[{"title":"Verify t equals four","body":"Substitute $t=4$: $3\\log_2(8)-2\\log_2(2)=3(3)-2(1)=7$."},{"title":"Combine the logarithms","body":"$3\\log_2(t+4)-2\\log_2(t-2)=\\log_2\\left(\\dfrac{(t+4)^3}{(t-2)^2}\\right)$."},{"title":"Use seven as a logarithm","body":"$7=\\log_2(128)$, so $\\dfrac{(t+4)^3}{(t-2)^2}=128$."},{"title":"Clear the denominator","body":"$(t+4)^3=128(t-2)^2$."},{"title":"Expand","body":"$t^3+12t^2+48t+64=128t^2-512t+512$."},{"title":"Show the cubic","body":"Rearranging gives $t^3-116t^2+560t-448=0$."},{"title":"Use the known root","body":"Since $t=4$ is a root, $(t-4)$ is a factor."},{"title":"Factor the cubic","body":"$t^3-116t^2+560t-448=(t-4)(t^2-112t+112)$."},{"title":"Solve the quadratic","body":"$t^2-112t+112=0$ gives $t=\\dfrac{112\\pm\\sqrt{112^2-4(112)}}{2}=56\\pm12\\sqrt{21}$."},{"title":"Use the log domain","body":"The original equation requires $t>2$. The value $56-12\\sqrt{21}$ is less than $2$, so it is rejected. Hence $t=4$ or $t=56+12\\sqrt{21}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q06","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":6,"marks":5,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q06_M05_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2024_Oct_Q06_M05_09_LawsOfLogarithms.png","finalAnswer":"$x=-\\dfrac18$.","steps":[{"title":"State the domain","body":"The logarithms require $12-2x>0$ and $x+1>0$, so $-1<x<6$."},{"title":"Combine the right hand side","body":"$2=\\log_4(16)$, so $2+2\\log_4(x+1)=\\log_4\\left(16(x+1)^2\\right)$."},{"title":"Equate the arguments","body":"$\\log_4(12-2x)=\\log_4\\left(16(x+1)^2\\right)$ gives $12-2x=16(x+1)^2$."},{"title":"Form the quadratic","body":"$12-2x=16x^2+32x+16$, so $8x^2+17x+2=0$."},{"title":"Factor and solve","body":"$8x^2+17x+2=(8x+1)(x+2)=0$, so $x=-\\dfrac18$ or $x=-2$."},{"title":"Check the domain","body":"The value $x=-2$ is outside $-1<x<6$, so the solution is $x=-\\dfrac18$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q07","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":7,"marks":8,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["09_LawsOfLogarithms","12_Integration"],"topicNames":["Laws of Logarithms","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q07_M08_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2025_Jan_Q07_M08_09_LawsOfLogarithms.png","finalAnswer":"$(i)$ $k=10080$. $\\quad (ii)$ $a=-5$.","steps":[{"title":"Use the trapezium rule","body":"The width is $1$, so $\\displaystyle\\int_{-1}^{4}\\log_{10}(x+5)\\,dx\\approx\\dfrac12\\{\\log_{10}4+\\log_{10}9+2(\\log_{10}5+\\log_{10}6+\\log_{10}7+\\log_{10}8)\\}$."},{"title":"Combine the logarithms","body":"This is $\\log_{10}\\left(\\sqrt{4\\times9}\\times5\\times6\\times7\\times8\\right)$."},{"title":"Find k","body":"$\\sqrt{4\\times9}\\times5\\times6\\times7\\times8=6\\times1680=10080$, so $k=10080$."},{"title":"State the domain","body":"The logarithms require $5-a>0$ and $a+25>0$, so $-25<a<5$."},{"title":"Combine the logarithms","body":"$2\\log_5(5-a)-\\log_5(a+25)=\\log_5\\left(\\dfrac{(5-a)^2}{a+25}\\right)$."},{"title":"Use one as a logarithm","body":"$1=\\log_5 5$, so $\\dfrac{(5-a)^2}{a+25}=5$."},{"title":"Form the quadratic","body":"$(5-a)^2=5(a+25)$, so $a^2-10a+25=5a+125$. Hence $a^2-15a-100=0$."},{"title":"Solve and check","body":"$(a-20)(a+5)=0$, so $a=20$ or $a=-5$. Only $a=-5$ is in the domain, so $a=-5$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q06","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":6,"marks":10,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q06_M10_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2025_MayJune_Q06_M10_09_LawsOfLogarithms.png","finalAnswer":"$(i)$ $x=-2$. $\\quad (ii)$ $P=(\\log_3 2,12)$.","steps":[{"title":"State the domain","body":"The logarithms require $4-x>0$ and $\\dfrac{x+11}{2}>0$, so $-11<x<4$."},{"title":"Use log laws","body":"$2\\log_2(4-x)=\\log_2((4-x)^2)$ and $3+\\log_2\\left(\\dfrac{x+11}{2}\\right)=\\log_2\\left(8\\cdot\\dfrac{x+11}{2}\\right)$."},{"title":"Equate the arguments","body":"Thus $(4-x)^2=4(x+11)$."},{"title":"Solve the quadratic","body":"$x^2-8x+16=4x+44$, so $x^2-12x-28=0$. Hence $(x-14)(x+2)=0$."},{"title":"Check the domain","body":"The root $14$ is outside the domain, so $x=-2$."},{"title":"Equate the curves","body":"At $P$, $3^{2x+1}=6\\times3^x$."},{"title":"Let u equal 3 to the x","body":"Let $u=3^x$. Then $3^{2x+1}=3u^2$, so $3u^2=6u$."},{"title":"Find u","body":"Since $u>0$, divide by $3u$ to get $u=2$. Hence $3^x=2$ and $x=\\log_3 2$."},{"title":"Find y","body":"$y=6\\times3^x=6\\times2=12$, so $P=(\\log_3 2,12)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q09","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":9,"marks":10,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":["01_Proof"],"secondaryTopicNames":["Proof"],"topics":["09_LawsOfLogarithms","01_Proof"],"topicNames":["Laws of Logarithms","Proof"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q09_M10_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2025_Oct_Q09_M10_09_LawsOfLogarithms.png","finalAnswer":"$(i)$ $x=\\dfrac1{16}$. $\\quad (ii)(a)$ Proven. $\\quad (ii)(b)$ $b>1$.","steps":[{"title":"State the domain","body":"The logarithms require $4x+5>0$ and $x+3>0$, so $x>-\\dfrac54$."},{"title":"Combine the logarithms","body":"$2\\log_3(4x+5)-\\log_3(x+3)=\\log_3\\left(\\dfrac{(4x+5)^2}{x+3}\\right)$."},{"title":"Use two as a logarithm","body":"$2=\\log_3 9$, so $\\dfrac{(4x+5)^2}{x+3}=9$."},{"title":"Form the quadratic","body":"$(4x+5)^2=9(x+3)$, so $16x^2+40x+25=9x+27$. Hence $16x^2+31x-2=0$."},{"title":"Solve the quadratic","body":"$16x^2+31x-2=(16x-1)(x+2)=0$, so $x=\\dfrac1{16}$ or $x=-2$."},{"title":"Check the domain","body":"$x=-2$ is outside the domain, so $x=\\dfrac1{16}$."},{"title":"Use the logarithm equation","body":"$\\log_{10}a+\\log_{10}b=\\log_{10}(a+b)$ gives $\\log_{10}(ab)=\\log_{10}(a+b)$."},{"title":"Equate the arguments","body":"Since the logarithm function is one-to-one, $ab=a+b$."},{"title":"Rearrange for a","body":"$ab-a=b$, so $a(b-1)=b$ and therefore $a=\\dfrac{b}{b-1}$."},{"title":"Restrict b","body":"Given $a>0$ and $b>0$, the fraction $\\dfrac{b}{b-1}$ must be positive. Since the numerator is positive, the denominator must also be positive, so $b>1$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q07","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":7,"marks":9,"topic":"09_LawsOfLogarithms","topicName":"Laws of Logarithms","primaryTopic":"09_LawsOfLogarithms","primaryTopicName":"Laws of Logarithms","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_LawsOfLogarithms"],"topicNames":["Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q07_M09_09_LawsOfLogarithms.png","downloadName":"WMA12-01_Y2026_Jan_Q07_M09_09_LawsOfLogarithms.png","finalAnswer":"$(i)\\ x=\\dfrac{17}{6}+\\dfrac16\\log_2 5.\\quad (ii)\\ y=-5$.","steps":[{"title":"Take logarithms base 2","body":"From $8^{2x-5}=20$, take $\\log_2$ of both sides to get $(2x-5)\\log_2 8=\\log_2 20$."},{"title":"Simplify the logarithms","body":"Since $\\log_2 8=3$ and $\\log_2 20=\\log_2(4\\cdot5)=2+\\log_2 5$, we get $3(2x-5)=2+\\log_2 5$."},{"title":"Solve for x","body":"$6x-15=2+\\log_2 5$, so $6x=17+\\log_2 5$ and $x=\\dfrac{17}{6}+\\dfrac16\\log_2 5$."},{"title":"Use log laws","body":"$3=\\log_3 27$ and $2\\log_3(4-y)=\\log_3(4-y)^2$."},{"title":"Remove the logarithms","body":"$\\log_3(13+2y)+\\log_3 27=\\log_3(4-y)^2$, so $27(13+2y)=(4-y)^2$."},{"title":"Solve the quadratic","body":"$351+54y=y^2-8y+16$, hence $y^2-62y-335=0=(y-67)(y+5)$."},{"title":"Check the logarithm domains","body":"We need $13+2y>0$ and $4-y>0$. Therefore $y=67$ is not valid, and the solution is $y=-5$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q09","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":9,"marks":12,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":["05_ArithmeticSequences"],"secondaryTopicNames":["Arithmetic Sequences"],"topics":["10_TrigonometricEquations","05_ArithmeticSequences"],"topicNames":["Trigonometric Equations","Arithmetic Sequences"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q09_M12_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2019_Oct_Q09_M12_10_TrigonometricEquations.png","finalAnswer":"$(i)\\ \\theta=14.7^\\circ,\\ 85.3^\\circ.\\quad (ii)(a)$ Proven. $\\quad (ii)(b)\\ \\alpha=5.517$ radians.","steps":[{"title":"Solve the sine equation","body":"Let $u=2\\theta-10^\\circ$. Then $\\sin u=\\dfrac13$."},{"title":"Find the valid angle values","body":"Since $0\\leq\\theta<180^\\circ$, $-10^\\circ\\leq u<350^\\circ$. In this interval, $u=19.471\\ldots^\\circ$ or $u=160.529\\ldots^\\circ$."},{"title":"Return to theta","body":"$\\theta=\\dfrac{u+10^\\circ}{2}$, giving $\\theta=14.7^\\circ$ and $85.3^\\circ$ to one decimal place."},{"title":"Use the arithmetic sequence condition","body":"For three consecutive terms of an arithmetic sequence, second minus first equals third minus second. Hence $\\dfrac1{\\tan\\alpha}-\\sin\\alpha=2\\sin\\alpha-\\dfrac1{\\tan\\alpha}$."},{"title":"Prove the required identity","body":"This gives $\\dfrac2{\\tan\\alpha}=3\\sin\\alpha$. Since $\\dfrac1{\\tan\\alpha}=\\dfrac{\\cos\\alpha}{\\sin\\alpha}$, we get $\\dfrac{2\\cos\\alpha}{\\sin\\alpha}=3\\sin\\alpha$, so $2\\cos\\alpha=3\\sin^2\\alpha$."},{"title":"Form a quadratic in cos alpha","body":"Using $\\sin^2\\alpha=1-\\cos^2\\alpha$, $2\\cos\\alpha=3(1-\\cos^2\\alpha)$, so $3\\cos^2\\alpha+2\\cos\\alpha-3=0$."},{"title":"Solve in the given interval","body":"$\\cos\\alpha=\\dfrac{-1+\\sqrt{10}}{3}$; the other root is less than $-1$. Since $\\pi<\\alpha<2\\pi$ and cosine is positive, $\\alpha$ is in the fourth quadrant."},{"title":"State alpha","body":"$\\alpha=2\\pi-\\cos^{-1}\\left(\\dfrac{-1+\\sqrt{10}}{3}\\right)=5.517$ radians to 3 decimal places."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q07","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":7,"marks":7,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q07_M07_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2020_Jan_Q07_M07_10_TrigonometricEquations.png","finalAnswer":"$(a)$ Proven. $\\quad (b)\\ x=9.74^\\circ,\\ 80.26^\\circ$.","steps":[{"title":"Rewrite tan theta","body":"$8\\tan\\theta=3\\cos\\theta$ becomes $8\\dfrac{\\sin\\theta}{\\cos\\theta}=3\\cos\\theta$."},{"title":"Clear the denominator","body":"Multiplying by $\\cos\\theta$ gives $8\\sin\\theta=3\\cos^2\\theta$."},{"title":"Use the identity","body":"Since $\\cos^2\\theta=1-\\sin^2\\theta$, $8\\sin\\theta=3(1-\\sin^2\\theta)$, so $3\\sin^2\\theta+8\\sin\\theta-3=0$."},{"title":"Apply the result to 2x","body":"For $8\\tan2x=3\\cos2x$, we get $3\\sin^2(2x)+8\\sin(2x)-3=0$."},{"title":"Solve for sin 2x","body":"$(3\\sin2x-1)(\\sin2x+3)=0$. Since $\\sin2x$ cannot be $-3$, $\\sin2x=\\dfrac13$."},{"title":"Find x","body":"For $0\\leq x\\leq90^\\circ$, $0\\leq2x\\leq180^\\circ$. Thus $2x=19.471\\ldots^\\circ$ or $160.529\\ldots^\\circ$, so $x=9.74^\\circ$ or $80.26^\\circ$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q06","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":6,"marks":8,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q06_M08_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2021_Jan_Q06_M08_10_TrigonometricEquations.png","finalAnswer":"$(a)$ Proven. $\\quad (b)\\ x=0,\\ 0.365$.","steps":[{"title":"Clear the fraction","body":"Starting with $\\dfrac{3\\sin\\theta\\cos\\theta}{2\\sin\\theta-1}=5\\tan\\theta$, multiply by $(2\\sin\\theta-1)\\cos\\theta$."},{"title":"Use tan theta","body":"This gives $3\\sin\\theta\\cos^2\\theta=5\\sin\\theta(2\\sin\\theta-1)$."},{"title":"Use cos squared","body":"Substitute $\\cos^2\\theta=1-\\sin^2\\theta$: $3\\sin\\theta(1-\\sin^2\\theta)=10\\sin^2\\theta-5\\sin\\theta$."},{"title":"Collect terms","body":"Rearranging gives $3\\sin^3\\theta+10\\sin^2\\theta-8\\sin\\theta=0$."},{"title":"Factor the sine equation","body":"$3s^3+10s^2-8s=0$ gives $s(3s-2)(s+4)=0$, where $s=\\sin2x$."},{"title":"Use the valid sine values","body":"Since $-\\dfrac\\pi2<2x<\\dfrac\\pi2$, the valid values are $\\sin2x=0$ and $\\sin2x=\\dfrac23$."},{"title":"Find x","body":"$2x=0$ gives $x=0$. Also $2x=\\sin^{-1}\\left(\\dfrac23\\right)$, so $x=0.364863\\ldots=0.365$ to 3 decimal places."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q08","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":8,"marks":10,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q08_M10_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2021_MayJune_Q08_M10_10_TrigonometricEquations.png","finalAnswer":"$(i)\\ \\theta=36.8^\\circ,\\ 216.8^\\circ.\\quad (ii)(a)\\ a=3,\\ b=-7,\\ c=2.\\quad (ii)(b)\\ x=-\\cos^{-1}\\left(\\dfrac13\\right),\\ 0,\\ \\cos^{-1}\\left(\\dfrac13\\right)$.","steps":[{"title":"Solve for theta plus thirty","body":"Let $u=\\theta+30^\\circ$. Then $3\\sin u=7\\cos u$, so $\\tan u=\\dfrac73$."},{"title":"Find u in the interval","body":"Since $0<\\theta<360^\\circ$, $30^\\circ<u<390^\\circ$. Thus $u=66.801\\ldots^\\circ$ or $246.801\\ldots^\\circ$."},{"title":"Return to theta","body":"$\\theta=u-30^\\circ$, giving $\\theta=36.8^\\circ$ and $216.8^\\circ$ to one decimal place."},{"title":"Rearrange the second equation","body":"$3\\sin^3x=5\\sin x-7\\sin x\\cos x$ gives $3\\sin^3x-5\\sin x+7\\sin x\\cos x=0$."},{"title":"Factor out sine","body":"$\\sin x(3\\sin^2x-5+7\\cos x)=0$."},{"title":"Use sin squared","body":"Since $\\sin^2x=1-\\cos^2x$, this becomes $\\sin x(-3\\cos^2x+7\\cos x-2)=0$, or $\\sin x(3\\cos^2x-7\\cos x+2)=0$."},{"title":"Solve in the interval","body":"For $-\\dfrac\\pi2\\leq x\\leq\\dfrac\\pi2$, $\\sin x=0$ gives $x=0$. Also $3\\cos^2x-7\\cos x+2=0$ gives $(3\\cos x-1)(\\cos x-2)=0$."},{"title":"State the solutions","body":"$\\cos x=2$ is impossible, so $\\cos x=\\dfrac13$. The solutions are $x=-\\cos^{-1}\\left(\\dfrac13\\right)$, $0$, and $\\cos^{-1}\\left(\\dfrac13\\right)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q10","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":10,"marks":10,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q10_M10_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2021_Oct_Q10_M10_10_TrigonometricEquations.png","finalAnswer":"$(i)\\ x=-\\dfrac{11\\pi}{24},\\ -\\dfrac{7\\pi}{24},\\ \\dfrac{\\pi}{24},\\ \\dfrac{5\\pi}{24}.\\quad (ii)\\ \\theta=53.1^\\circ,\\ 180^\\circ,\\ 233.1^\\circ$.","steps":[{"title":"Take the square root","body":"Let $u=2x+\\dfrac\\pi4$. From $\\tan^2u=3$, $\\tan u=\\pm\\sqrt3$."},{"title":"Write the angle families","body":"Thus $u=\\dfrac\\pi3+n\\pi$ or $u=-\\dfrac\\pi3+n\\pi$, where $n$ is an integer."},{"title":"Return to x","body":"So $x=\\dfrac\\pi{24}+\\dfrac{n\\pi}{2}$ or $x=-\\dfrac{7\\pi}{24}+\\dfrac{n\\pi}{2}$."},{"title":"Use the interval","body":"For $-\\dfrac\\pi2<x<\\dfrac\\pi2$, the solutions are $x=-\\dfrac{11\\pi}{24},-\\dfrac{7\\pi}{24},\\dfrac\\pi{24},\\dfrac{5\\pi}{24}$."},{"title":"Expand the squared equation","body":"$(2\\sin\\theta-\\cos\\theta)^2=1$ gives $4\\sin^2\\theta-4\\sin\\theta\\cos\\theta+\\cos^2\\theta=1$."},{"title":"Use the identity","body":"Since $1=\\sin^2\\theta+\\cos^2\\theta$, this simplifies to $3\\sin^2\\theta-4\\sin\\theta\\cos\\theta=0$."},{"title":"Factor","body":"$\\sin\\theta(3\\sin\\theta-4\\cos\\theta)=0$."},{"title":"Solve the two cases","body":"$\\sin\\theta=0$ gives $\\theta=180^\\circ$ in the interval. Also $3\\sin\\theta=4\\cos\\theta$ gives $\\tan\\theta=\\dfrac43$."},{"title":"State theta","body":"For $0<\\theta<360^\\circ$, $\\tan\\theta=\\dfrac43$ gives $\\theta=53.1^\\circ$ and $233.1^\\circ$. Therefore $\\theta=53.1^\\circ,180^\\circ,233.1^\\circ$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q07","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":7,"marks":8,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q07_M08_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2022_Jan_Q07_M08_10_TrigonometricEquations.png","finalAnswer":"$(i)\\ x=-73.3^\\circ,\\ 16.7^\\circ.\\quad (ii)\\ \\theta=1.69,\\ 4.59$.","steps":[{"title":"Solve the first tangent equation","body":"Let $u=2x-15^\\circ$. Then $3\\sin u=\\cos u$, so $\\tan u=\\dfrac13$."},{"title":"Use the interval for u","body":"Since $-90^\\circ<x<90^\\circ$, $-195^\\circ<u<165^\\circ$."},{"title":"Find x","body":"$u=18.434\\ldots^\\circ$ or $u=-161.565\\ldots^\\circ$, so $x=16.7^\\circ$ or $x=-73.3^\\circ$."},{"title":"Rewrite the second equation","body":"$4\\sin^2\\theta+8\\cos\\theta=3$."},{"title":"Use sin squared","body":"Substitute $\\sin^2\\theta=1-\\cos^2\\theta$ to get $4(1-\\cos^2\\theta)+8\\cos\\theta=3$."},{"title":"Solve for cos theta","body":"This gives $4\\cos^2\\theta-8\\cos\\theta-1=0$, so $\\cos\\theta=1\\pm\\dfrac{\\sqrt5}{2}$."},{"title":"Choose the valid cosine","body":"Only $\\cos\\theta=1-\\dfrac{\\sqrt5}{2}$ lies between $-1$ and $1$."},{"title":"State theta","body":"For $0<\\theta<2\\pi$, $\\theta=1.69$ or $4.59$ to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q05","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":5,"marks":6,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q05_M06_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2022_MayJune_Q05_M06_10_TrigonometricEquations.png","finalAnswer":"$\\theta=-13^\\circ,\\ 107^\\circ$.","steps":[{"title":"Substitute u","body":"Let $u=\\theta+43^\\circ$. The equation becomes $3\\tan u=2\\cos u$."},{"title":"Clear the cosine denominator","body":"$3\\dfrac{\\sin u}{\\cos u}=2\\cos u$, so $3\\sin u=2\\cos^2u$."},{"title":"Use cos squared","body":"$3\\sin u=2(1-\\sin^2u)$, so $2\\sin^2u+3\\sin u-2=0$."},{"title":"Factor the quadratic","body":"$(2\\sin u-1)(\\sin u+2)=0$."},{"title":"Use the valid sine value","body":"$\\sin u=-2$ is impossible, so $\\sin u=\\dfrac12$."},{"title":"Find u in the interval","body":"Since $-180^\\circ<\\theta\\leq180^\\circ$, $-137^\\circ<u\\leq223^\\circ$. Thus $u=30^\\circ$ or $150^\\circ$."},{"title":"Return to theta","body":"$\\theta=u-43^\\circ$, so $\\theta=-13^\\circ$ or $107^\\circ$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q05","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":5,"marks":8,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q05_M08_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2022_Oct_Q05_M08_10_TrigonometricEquations.png","finalAnswer":"$(a)$ Proven. $\\quad (b)\\ x=-1.13,\\ -0.438,\\ 0.225,\\ 1.35$ radians.","steps":[{"title":"Rewrite the left side","body":"$(3\\cos\\theta-\\tan\\theta)\\cos\\theta=3\\cos^2\\theta-\\sin\\theta$ because $\\tan\\theta\\cos\\theta=\\sin\\theta$."},{"title":"Move everything to one side","body":"The equation becomes $3\\cos^2\\theta-\\sin\\theta=2$."},{"title":"Use cos squared","body":"Since $\\cos^2\\theta=1-\\sin^2\\theta$, $3(1-\\sin^2\\theta)-\\sin\\theta=2$."},{"title":"Show the required form","body":"Expanding and rearranging gives $3\\sin^2\\theta+\\sin\\theta-1=0$."},{"title":"Apply the result to 2x","body":"For $(3\\cos2x-\\tan2x)\\cos2x=2$, take $\\theta=2x$. Then $3\\sin^2(2x)+\\sin(2x)-1=0$."},{"title":"Solve the quadratic","body":"Let $u=\\sin(2x)$. Then $3u^2+u-1=0$, so $u=\\dfrac{-1\\pm\\sqrt{13}}{6}$."},{"title":"Use the interval","body":"Since $-\\dfrac{\\pi}{2}\\le x\\le\\dfrac{\\pi}{2}$, we have $-\\pi\\le2x\\le\\pi$. Solving $\\sin(2x)=\\dfrac{-1+\\sqrt{13}}{6}$ and $\\sin(2x)=\\dfrac{-1-\\sqrt{13}}{6}$ in this interval gives $2x=-2.2665\\ldots,-0.8751\\ldots,0.4492\\ldots,2.6924\\ldots$."},{"title":"Divide by two","body":"Therefore $x=-1.133\\ldots,-0.4375\\ldots,0.2246\\ldots,1.346\\ldots$, giving $x=-1.13,-0.438,0.225,1.35$ radians."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q08","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":8,"marks":9,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q08_M09_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2023_Jan_Q08_M09_10_TrigonometricEquations.png","finalAnswer":"$(i)$ $x=-0.94,-0.17,1.15,1.92$. $\\quad (ii)$ $\\theta=70.5^\\circ,289.5^\\circ$.","steps":[{"title":"Isolate the sine term","body":"$5\\sin(3x+0.1)+2=0$ gives $\\sin(3x+0.1)=-0.4$."},{"title":"Find the angle interval","body":"Since $-\\dfrac{\\pi}{2}<x<\\pi$, multiplying by 3 and adding $0.1$ gives $-\\dfrac{3\\pi}{2}+0.1<3x+0.1<3\\pi+0.1$."},{"title":"Solve for the inner angle","body":"In this interval, $3x+0.1=-2.7301\\ldots,-0.4115\\ldots,3.5531\\ldots,5.8717\\ldots$."},{"title":"Find x values","body":"Subtract $0.1$ and divide by $3$: $x=-0.9433\\ldots,-0.1705\\ldots,1.1510\\ldots,1.9239\\ldots$."},{"title":"Round the radian answers","body":"To 2 decimal places, $x=-0.94,-0.17,1.15,1.92$."},{"title":"Rewrite the second equation","body":"$2\\tan\\theta\\sin\\theta=5+\\cos\\theta$. Using $\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}$ gives $\\dfrac{2\\sin^2\\theta}{\\cos\\theta}=5+\\cos\\theta$."},{"title":"Use sine squared","body":"Multiplying by $\\cos\\theta$ gives $2\\sin^2\\theta=5\\cos\\theta+\\cos^2\\theta$. Substitute $\\sin^2\\theta=1-\\cos^2\\theta$."},{"title":"Solve for cos theta","body":"$2(1-\\cos^2\\theta)=5\\cos\\theta+\\cos^2\\theta$, so $3\\cos^2\\theta+5\\cos\\theta-2=0$."},{"title":"Factor and reject impossible value","body":"$(3\\cos\\theta-1)(\\cos\\theta+2)=0$. Since $\\cos\\theta=-2$ is impossible, $\\cos\\theta=\\dfrac13$."},{"title":"Find theta","body":"For $0<\\theta<360^\\circ$, $\\cos\\theta=\\dfrac13$ gives $\\theta=70.5^\\circ$ or $289.5^\\circ$ to one decimal place."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q09","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":9,"marks":7,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q09_M07_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2023_MayJune_Q09_M07_10_TrigonometricEquations.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $x=24.1^\\circ,155.9^\\circ,204.1^\\circ,335.9^\\circ$.","steps":[{"title":"Rewrite tan theta sin theta","body":"$\\tan\\theta\\sin\\theta=\\dfrac{\\sin^2\\theta}{\\cos\\theta}$."},{"title":"Simplify the left side","body":"$3\\cos\\theta\\left(\\tan\\theta\\sin\\theta+3\\right)=3\\sin^2\\theta+9\\cos\\theta$."},{"title":"Use sine squared","body":"The equation becomes $3(1-\\cos^2\\theta)+9\\cos\\theta=11-5\\cos\\theta$."},{"title":"Rearrange","body":"$3-3\\cos^2\\theta+9\\cos\\theta=11-5\\cos\\theta$, so $3\\cos^2\\theta-14\\cos\\theta+8=0$."},{"title":"Apply the result to 2x","body":"For the equation in part (b), take $\\theta=2x$. Then $3\\cos^2(2x)-14\\cos(2x)+8=0$."},{"title":"Solve the quadratic","body":"Let $u=\\cos(2x)$. Then $3u^2-14u+8=0$, so $(3u-2)(u-4)=0$."},{"title":"Reject the impossible value","body":"$u=4$ is impossible for cosine, so $\\cos(2x)=\\dfrac23$."},{"title":"Use the interval","body":"Since $0<x<360^\\circ$, we have $0<2x<720^\\circ$."},{"title":"Find x","body":"In this interval, $2x=48.189\\ldots^\\circ,311.810\\ldots^\\circ,408.189\\ldots^\\circ,671.810\\ldots^\\circ$. Dividing by $2$ gives $x=24.1^\\circ,155.9^\\circ,204.1^\\circ,335.9^\\circ$ to one decimal place."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q03","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":3,"marks":7,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q03_M07_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2023_Oct_Q03_M07_10_TrigonometricEquations.png","finalAnswer":"$(a)$ $\\theta=131.8^\\circ,180^\\circ,228.2^\\circ,360^\\circ$. $\\quad (b)$ $x=45.9^\\circ$.","steps":[{"title":"Factor the equation","body":"$2\\tan\\theta+3\\sin\\theta=0$ becomes $\\dfrac{2\\sin\\theta}{\\cos\\theta}+3\\sin\\theta=0$."},{"title":"Multiply by cos theta","body":"Since $\\tan\\theta$ is defined, $\\cos\\theta\\ne0$. Multiplying by $\\cos\\theta$ gives $2\\sin\\theta+3\\sin\\theta\\cos\\theta=0$."},{"title":"Factor","body":"$\\sin\\theta(2+3\\cos\\theta)=0$."},{"title":"Solve the sine case","body":"For $0<\\theta\\le360^\\circ$, $\\sin\\theta=0$ gives $\\theta=180^\\circ$ or $360^\\circ$."},{"title":"Solve the cosine case","body":"$2+3\\cos\\theta=0$ gives $\\cos\\theta=-\\dfrac23$, so $\\theta=131.8^\\circ$ or $228.2^\\circ$ to one decimal place."},{"title":"Apply to the new angle","body":"For $2\\tan(2x+40^\\circ)+3\\sin(2x+40^\\circ)=0$, the angle $2x+40^\\circ$ must be one of the solution angles, modulo $360^\\circ$."},{"title":"Find the smallest positive x","body":"The smallest positive value comes from $2x+40^\\circ=131.8\\ldots^\\circ$, so $x=\\dfrac{131.8\\ldots-40}{2}=45.9^\\circ$ to one decimal place."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q09","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":9,"marks":14,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q09_M14_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2024_Jan_Q09_M14_10_TrigonometricEquations.png","finalAnswer":"$(i)$ $x=78.9^\\circ,281.1^\\circ$. $\\quad (ii)(a)$ $A=5$. $\\quad (ii)(b)$ $Q=\\left(\\dfrac{15\\pi}{16},-3\\right)$. $\\quad (ii)(c)$ $\\theta=5.51$.","steps":[{"title":"Rewrite the equation","body":"$\\sin x\\tan x=5$ becomes $\\dfrac{\\sin^2x}{\\cos x}=5$."},{"title":"Use sine squared","body":"Multiplying by $\\cos x$ gives $\\sin^2x=5\\cos x$. Since $\\sin^2x=1-\\cos^2x$, $1-\\cos^2x=5\\cos x$."},{"title":"Solve for cos x","body":"$\\cos^2x+5\\cos x-1=0$, so $\\cos x=\\dfrac{-5\\pm\\sqrt{29}}{2}$."},{"title":"Choose the possible cosine value","body":"$\\dfrac{-5-\\sqrt{29}}{2}<-1$, so the valid value is $\\cos x=\\dfrac{-5+\\sqrt{29}}{2}$."},{"title":"Find x","body":"For $0\\le x<360^\\circ$, this gives $x=78.9^\\circ$ or $281.1^\\circ$ to one decimal place."},{"title":"Find A from P","body":"The point $P$ is a maximum point on the sine curve. Its $y$ coordinate is $7$, so $A+2=7$ and $A=5$."},{"title":"Locate Q","body":"Point $Q$ is the next minimum after $P$, so $\\sin\\left(2\\theta-\\dfrac{3\\pi}{8}\\right)=-1$."},{"title":"Find theta at Q","body":"For this minimum, $2\\theta-\\dfrac{3\\pi}{8}=\\dfrac{3\\pi}{2}$, so $2\\theta=\\dfrac{15\\pi}{8}$ and $\\theta=\\dfrac{15\\pi}{16}$."},{"title":"Find y at Q","body":"At the minimum, $y=2-5=-3$, so $Q=\\left(\\dfrac{15\\pi}{16},-3\\right)$."},{"title":"Set up R","body":"At $R$, $y=0$, so $5\\sin\\left(2\\theta-\\dfrac{3\\pi}{8}\\right)+2=0$."},{"title":"Choose the shown crossing","body":"Thus $\\sin\\left(2\\theta-\\dfrac{3\\pi}{8}\\right)=-\\dfrac25$. The crossing $R$ shown after the second maximum has $2\\theta-\\dfrac{3\\pi}{8}=3\\pi+\\sin^{-1}\\left(\\dfrac25\\right)$."},{"title":"Find theta at R","body":"$\\theta=\\dfrac12\\left(3\\pi+\\sin^{-1}\\left(\\dfrac25\\right)+\\dfrac{3\\pi}{8}\\right)=5.507\\ldots$, so $\\theta=5.51$ to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q08","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":8,"marks":12,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["10_TrigonometricEquations","08_ModellingSequencesSeries"],"topicNames":["Trigonometric Equations","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q08_M12_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2024_MayJune_Q08_M12_10_TrigonometricEquations.png","finalAnswer":"$(i)$ $x=1.91$ radians. $\\quad (ii)(a)$ $k=6.41$ or $17.59$. $\\quad (ii)(b)$ $22^\\circ\\text{C}$. $\\quad (ii)(c)$ $11{:}14$ am.","steps":[{"title":"Rewrite the trig equation","body":"$5\\sin x\\tan x+13=\\cos x$ becomes $\\dfrac{5\\sin^2x}{\\cos x}+13=\\cos x$."},{"title":"Multiply by cos x","body":"$5\\sin^2x+13\\cos x=\\cos^2x$."},{"title":"Use sine squared","body":"$5(1-\\cos^2x)+13\\cos x=\\cos^2x$, so $6\\cos^2x-13\\cos x-5=0$."},{"title":"Solve for cos x","body":"$(2\\cos x-5)(3\\cos x+1)=0$, so $\\cos x=\\dfrac52$ or $\\cos x=-\\dfrac13$."},{"title":"Choose the valid root","body":"$\\cos x=\\dfrac52$ is impossible, so $\\cos x=-\\dfrac13$. For $0<x\\le\\pi$, $x=1.9106\\ldots$, so $x=1.91$ radians to 3 significant figures."},{"title":"Use the temperature at 6 am","body":"At $t=6$, $20=10+12\\sin(6k+18)^\\circ$, so $\\sin(6k+18)^\\circ=\\dfrac56$."},{"title":"Solve for k","body":"$\\sin^{-1}\\left(\\dfrac56\\right)=56.442\\ldots^\\circ$. Since $0<k<20$, $18<6k+18<138$, so $6k+18=56.442\\ldots$ or $123.557\\ldots$."},{"title":"Find possible k values","body":"This gives $k=6.407\\ldots$ or $k=17.592\\ldots$, so $k=6.41$ or $17.59$ to 2 decimal places."},{"title":"Use the tighter condition","body":"Given further that $0<k<10$, use $k=6.407\\ldots$."},{"title":"Find the maximum temperature","body":"The maximum value of $\\sin$ is $1$, so the maximum temperature is $10+12=22^\\circ\\text{C}$."},{"title":"Find the time of maximum","body":"The maximum occurs when $kt+18=90$, so $t=\\dfrac{72}{6.407\\ldots}=11.2375\\ldots$ hours after midnight."},{"title":"Convert to time of day","body":"$0.2375\\ldots$ hours is $14.25\\ldots$ minutes, so the maximum occurs at about $11{:}14$ am."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q05","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":5,"marks":6,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["10_TrigonometricEquations","08_ModellingSequencesSeries"],"topicNames":["Trigonometric Equations","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q05_M06_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q05_M06_10_TrigonometricEquations.png","finalAnswer":"$(a)$ $D(2)=4.06\\ldots$ m, just over $4$ m. $\\quad (b)$ $13{:}03$, or $1{:}03$ pm.","steps":[{"title":"Substitute t equals two","body":"$D=8+5\\sin\\left(\\dfrac{\\pi(2)}{6}+3\\right)=8+5\\sin\\left(\\dfrac{\\pi}{3}+3\\right)$."},{"title":"Evaluate","body":"$D=4.064\\ldots$, so the depth at 2 am is just over $4$ metres."},{"title":"Set depth equal to six","body":"$6=8+5\\sin\\left(\\dfrac{\\pi t}{6}+3\\right)$, so $\\sin\\left(\\dfrac{\\pi t}{6}+3\\right)=-\\dfrac25$."},{"title":"Use the time interval","body":"After midday means $t>12$. Then $\\dfrac{\\pi t}{6}+3$ is greater than $2\\pi+3$."},{"title":"Choose the first suitable angle","body":"The first angle after $2\\pi+3$ with sine $-\\dfrac25$ is $3\\pi+\\sin^{-1}\\left(\\dfrac25\\right)$."},{"title":"Solve for t","body":"$\\dfrac{\\pi t}{6}+3=3\\pi+\\sin^{-1}\\left(\\dfrac25\\right)$, so $t=13.056\\ldots$ hours after midnight."},{"title":"Convert to clock time","body":"$0.056\\ldots$ hours is about $3.38$ minutes, so the time to the nearest minute is $13{:}03$, or $1{:}03$ pm."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q07","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":7,"marks":7,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q07_M07_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q07_M07_10_TrigonometricEquations.png","finalAnswer":"$(i)$ $x=1.318,\\ 4.965$. $\\quad (ii)$ $2\\sqrt2$.","steps":[{"title":"Rewrite tan x","body":"$3\\sin x\\tan x=11+\\cos x$ becomes $\\dfrac{3\\sin^2x}{\\cos x}=11+\\cos x$."},{"title":"Multiply by cos x","body":"$3\\sin^2x=11\\cos x+\\cos^2x$."},{"title":"Use sine squared","body":"$3(1-\\cos^2x)=11\\cos x+\\cos^2x$, so $4\\cos^2x+11\\cos x-3=0$."},{"title":"Solve for cosine","body":"$(4\\cos x-1)(\\cos x+3)=0$, so $\\cos x=\\dfrac14$ or $\\cos x=-3$."},{"title":"Reject impossible value","body":"$\\cos x=-3$ is impossible, so $\\cos x=\\dfrac14$."},{"title":"Find x values","body":"For $0\\le x<2\\pi$, this gives $x=1.318\\ldots$ or $x=4.965\\ldots$, so $x=1.318,4.965$ radians."},{"title":"Use the right triangle identity","body":"Given $0<\\theta<90^\\circ$ and $\\cos\\theta=\\dfrac13$, $\\sin\\theta=\\sqrt{1-\\dfrac19}=\\dfrac{2\\sqrt2}{3}$."},{"title":"Find tan theta","body":"$\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}=\\dfrac{2\\sqrt2/3}{1/3}=2\\sqrt2$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q09","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":9,"marks":7,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q09_M07_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2024_Oct_Q09_M07_10_TrigonometricEquations.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $x=-2.50$, $-0.121$, $0.645$, $3.02$.","steps":[{"title":"Write tan in terms of sin and cos","body":"$2\\tan\\theta=3\\cos\\theta$ gives $2\\dfrac{\\sin\\theta}{\\cos\\theta}=3\\cos\\theta$."},{"title":"Multiply by cos theta","body":"Since $\\tan\\theta$ is defined, $\\cos\\theta\\ne0$. Hence $2\\sin\\theta=3\\cos^2\\theta$."},{"title":"Use the identity","body":"$2\\sin\\theta=3(1-\\sin^2\\theta)$, so $3\\sin^2\\theta+2\\sin\\theta-3=0$."},{"title":"Substitute the new angle","body":"Let $\\theta=2x+\\dfrac\\pi3$. Then $3\\sin^2\\theta+2\\sin\\theta-3=0$."},{"title":"Solve for sin theta","body":"$\\sin\\theta=\\dfrac{-2\\pm\\sqrt{40}}{6}=\\dfrac{-1\\pm\\sqrt{10}}{3}$. The root $\\dfrac{-1-\\sqrt{10}}{3}$ is less than $-1$, so reject it."},{"title":"Find the angle range","body":"Since $-\\pi<x<\\pi$, $-\\dfrac{5\\pi}{3}<\\theta<\\dfrac{7\\pi}{3}$."},{"title":"Find the theta values","body":"For $\\sin\\theta=\\dfrac{-1+\\sqrt{10}}{3}$ in this range, $\\theta\\approx-3.94649$, $0.804897$, $2.33670$, and $7.08808$."},{"title":"Convert back to x","body":"Using $x=\\dfrac{\\theta-\\pi/3}{2}$ gives $x\\approx-2.49684$, $-0.121150$, $0.644749$, and $3.02044$."},{"title":"Round the answers","body":"To $3$ significant figures, $x=-2.50$, $-0.121$, $0.645$, and $3.02$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q10","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":10,"marks":8,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q10_M08_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2025_Jan_Q10_M08_10_TrigonometricEquations.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $x=3.48$, $5.94$.","steps":[{"title":"Expand the left side","body":"$\\cos\\theta\\left(3\\tan\\theta+\\dfrac2{\\tan\\theta}\\right)=3\\sin\\theta+\\dfrac{2\\cos\\theta}{\\tan\\theta}$."},{"title":"Rewrite the second term","body":"Since $\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}$, $\\dfrac{2\\cos\\theta}{\\tan\\theta}=\\dfrac{2\\cos^2\\theta}{\\sin\\theta}$."},{"title":"Use the identity","body":"$3\\sin\\theta+\\dfrac{2\\cos^2\\theta}{\\sin\\theta}=3\\sin\\theta+\\dfrac{2(1-\\sin^2\\theta)}{\\sin\\theta}$."},{"title":"Simplify","body":"$3\\sin\\theta+\\dfrac2{\\sin\\theta}-2\\sin\\theta=\\sin\\theta+\\dfrac2{\\sin\\theta}$, as required."},{"title":"Use part a","body":"The equation becomes $\\sin x+\\dfrac2{\\sin x}=4\\sin x-5$."},{"title":"Form a quadratic in sin x","body":"Multiplying by $\\sin x$ gives $\\sin^2x+2=4\\sin^2x-5\\sin x$, so $3\\sin^2x-5\\sin x-2=0$."},{"title":"Solve for sin x","body":"$(3\\sin x+1)(\\sin x-2)=0$. Since $\\sin x=2$ is impossible, $\\sin x=-\\dfrac13$."},{"title":"Find x in the interval","body":"For $0<x<2\\pi$, $\\sin x=-\\dfrac13$ gives $x=\\pi+\\sin^{-1}\\left(\\dfrac13\\right)$ or $x=2\\pi-\\sin^{-1}\\left(\\dfrac13\\right)$."},{"title":"Round the answers","body":"Thus $x=3.481\\ldots$ or $x=5.943\\ldots$, so to $3$ significant figures $x=3.48$ or $x=5.94$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q08","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":8,"marks":8,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q08_M08_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2025_MayJune_Q08_M08_10_TrigonometricEquations.png","finalAnswer":"$(i)$ $x=\\dfrac{29\\pi}{60}$, $\\dfrac{59\\pi}{60}$. $\\quad (ii)$ $\\theta=50.3^\\circ$, $309.7^\\circ$.","steps":[{"title":"Solve the tangent equation","body":"$3\\tan\\left(2x+\\dfrac\\pi5\\right)=\\sqrt3$ gives $\\tan\\left(2x+\\dfrac\\pi5\\right)=\\dfrac1{\\sqrt3}$."},{"title":"Write the general angle","body":"Therefore $2x+\\dfrac\\pi5=\\dfrac\\pi6+n\\pi$."},{"title":"Find x","body":"$2x=-\\dfrac\\pi{30}+n\\pi$, so $x=-\\dfrac\\pi{60}+\\dfrac{n\\pi}{2}$."},{"title":"Use the interval","body":"For $0\\le x<\\pi$, the possible values are $x=\\dfrac{29\\pi}{60}$ and $x=\\dfrac{59\\pi}{60}$."},{"title":"Rewrite the second equation","body":"Using $\\tan\\theta=\\dfrac{\\sin\\theta}{\\cos\\theta}$, $5\\sin\\theta\\tan\\theta=\\cos\\theta+4$ becomes $\\dfrac{5\\sin^2\\theta}{\\cos\\theta}=\\cos\\theta+4$."},{"title":"Form an equation in cos theta","body":"Multiplying by $\\cos\\theta$ gives $5\\sin^2\\theta=\\cos^2\\theta+4\\cos\\theta$. Using $\\sin^2\\theta=1-\\cos^2\\theta$ gives $6\\cos^2\\theta+4\\cos\\theta-5=0$."},{"title":"Solve for cos theta","body":"$\\cos\\theta=\\dfrac{-2\\pm\\sqrt{34}}{6}$. The negative option is less than $-1$, so reject it."},{"title":"Find theta","body":"$\\cos\\theta=\\dfrac{-2+\\sqrt{34}}{6}$ gives $\\theta=50.320\\ldots^\\circ$ or $309.679\\ldots^\\circ$."},{"title":"Round the answers","body":"To one decimal place, $\\theta=50.3^\\circ$ or $309.7^\\circ$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q05","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":5,"marks":9,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q05_M09_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2025_Oct_Q05_M09_10_TrigonometricEquations.png","finalAnswer":"$(i)$ $\\theta=143.1^\\circ$, $180^\\circ$, $216.9^\\circ$, $360^\\circ$. $\\quad (ii)$ $x=0.201$, $2.94$.","steps":[{"title":"Rewrite the first equation","body":"$4\\tan\\theta+5\\sin\\theta=0$ gives $4\\dfrac{\\sin\\theta}{\\cos\\theta}+5\\sin\\theta=0$."},{"title":"Factor sin theta","body":"$\\sin\\theta\\left(\\dfrac4{\\cos\\theta}+5\\right)=0$."},{"title":"Use sin theta equals zero","body":"In $0<\\theta\\le360^\\circ$, $\\sin\\theta=0$ gives $\\theta=180^\\circ$ or $360^\\circ$."},{"title":"Use the other factor","body":"$\\dfrac4{\\cos\\theta}+5=0$ gives $\\cos\\theta=-\\dfrac45$."},{"title":"Find the remaining angles","body":"For $0<\\theta\\le360^\\circ$, $\\cos\\theta=-\\dfrac45$ gives $\\theta=143.130\\ldots^\\circ$ or $216.869\\ldots^\\circ$."},{"title":"Round part i","body":"The non-exact angles are $143.1^\\circ$ and $216.9^\\circ$ to one decimal place."},{"title":"Clear the fractions in part ii","body":"$\\dfrac{\\sin x}{\\cos x}+\\dfrac{\\cos x}{\\sin x}=\\dfrac5{\\cos x}$. Multiplying by $\\sin x\\cos x$ gives $\\sin^2x+\\cos^2x=5\\sin x$."},{"title":"Use the identity","body":"$\\sin^2x+\\cos^2x=1$, so $1=5\\sin x$ and $\\sin x=\\dfrac15$."},{"title":"Solve in the interval","body":"For $0<x<\\pi$, $x=\\sin^{-1}\\left(\\dfrac15\\right)$ or $x=\\pi-\\sin^{-1}\\left(\\dfrac15\\right)$."},{"title":"Round part ii","body":"Thus $x=0.201357\\ldots$ or $2.94023\\ldots$, so $x=0.201$ or $2.94$ to $3$ significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q08","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":8,"marks":10,"topic":"10_TrigonometricEquations","topicName":"Trigonometric Equations","primaryTopic":"10_TrigonometricEquations","primaryTopicName":"Trigonometric Equations","secondaryTopics":[],"secondaryTopicNames":[],"topics":["10_TrigonometricEquations"],"topicNames":["Trigonometric Equations"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q08_M10_10_TrigonometricEquations.png","downloadName":"WMA12-01_Y2026_Jan_Q08_M10_10_TrigonometricEquations.png","finalAnswer":"$(i)\\ \\theta=51.9^\\circ,\\ 68.1^\\circ,\\ 141.9^\\circ,\\ 158.1^\\circ.\\quad (ii)\\ x=\\dfrac{2\\pi}{3},\\ \\dfrac{4\\pi}{3}$.","steps":[{"title":"Make the tangent expression the subject","body":"$4\\tan^2(2\\theta-30^\\circ)+1=49$ gives $\\tan^2(2\\theta-30^\\circ)=12$."},{"title":"Find the possible angle values","body":"Let $\\alpha=2\\theta-30^\\circ$. Since $0\\leq\\theta<180^\\circ$, $-30^\\circ\\leq\\alpha<330^\\circ$. The solutions of $\\tan\\alpha=\\pm\\sqrt{12}$ in this range are approximately $73.9^\\circ,106.1^\\circ,253.9^\\circ,286.1^\\circ$."},{"title":"Return to theta","body":"$\\theta=\\dfrac{\\alpha+30^\\circ}{2}$, giving $\\theta=51.9^\\circ,68.1^\\circ,141.9^\\circ,158.1^\\circ$ to one decimal place."},{"title":"Rewrite tan x","body":"$2\\tan x\\sin x+3=0$ becomes $2\\left(\\dfrac{\\sin x}{\\cos x}\\right)\\sin x+3=0$."},{"title":"Form a quadratic in cos x","body":"Multiplying by $\\cos x$ gives $2\\sin^2 x+3\\cos x=0$. Using $\\sin^2x=1-\\cos^2x$, $2(1-\\cos^2x)+3\\cos x=0$, so $2\\cos^2x-3\\cos x-2=0$."},{"title":"Solve for x","body":"$(2\\cos x+1)(\\cos x-2)=0$. Since $\\cos x=2$ is impossible, $\\cos x=-\\dfrac12$. In $0\\leq x<2\\pi$, $x=\\dfrac{2\\pi}{3}$ or $x=\\dfrac{4\\pi}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q01","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":1,"marks":6,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q01_M06_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2019_Oct_Q01_M06_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)\\ x=0,\\ \\dfrac{10}{3}.\\quad (b)\\ x<0\\text{ or }x>\\dfrac{10}{3}$.","steps":[{"title":"Expand the curve","body":"$y=2x^2(x-5)=2x^3-10x^2$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=6x^2-20x=2x(3x-10)$."},{"title":"Find the stationary values of x","body":"At a stationary point, $\\dfrac{dy}{dx}=0$. Hence $2x(3x-10)=0$, so $x=0$ or $x=\\dfrac{10}{3}$."},{"title":"Use the sign of the derivative","body":"Since $2x(3x-10)$ is positive outside its two roots and negative between them, $y$ is increasing for $x<0$ and for $x>\\dfrac{10}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q10","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":10,"marks":7,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q10_M07_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2019_Oct_Q10_M07_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)\\ a=\\dfrac43,\\ b=\\dfrac13.\\quad (b)$ Proven: $C$ has no turning points.","steps":[{"title":"Use the point on the curve","body":"Substitute $(2,5)$ into $y=ax^3-3x^2+3x+b$: $5=8a-12+6+b$, so $8a+b=11$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=3ax^2-6x+3$."},{"title":"Use the given gradient","body":"At $x=2$, the gradient is $7$, so $12a-12+3=7$. Hence $12a=16$ and $a=\\dfrac43$."},{"title":"Find b","body":"Using $8a+b=11$, $b=11-8\\left(\\dfrac43\\right)=\\dfrac13$."},{"title":"Check for turning points","body":"With $a=\\dfrac43$, $\\dfrac{dy}{dx}=4x^2-6x+3$."},{"title":"Use the discriminant","body":"For $4x^2-6x+3=0$, the discriminant is $(-6)^2-4(4)(3)=36-48=-12<0$."},{"title":"Conclude","body":"The derivative is never zero, so the curve has no turning points."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q10","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":10,"marks":10,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q10_M10_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2020_Jan_Q10_M10_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)\\ k=-\\dfrac32.\\quad (b)$ local maximum. $\\quad (c)\\ x=\\dfrac1{\\sqrt2}$.","steps":[{"title":"Differentiate the curve","body":"Write $y=4x^3-9x+kx^{-1}$. Then $\\dfrac{dy}{dx}=12x^2-9-kx^{-2}$."},{"title":"Use the stationary point","body":"At $x=\\dfrac12$, $\\dfrac{dy}{dx}=0$, so $0=12\\left(\\dfrac12\\right)^2-9-k\\left(\\dfrac12\\right)^{-2}=3-9-4k$."},{"title":"Find k","body":"$-6-4k=0$, hence $k=-\\dfrac32$."},{"title":"Use the second derivative","body":"With $k=-\\dfrac32$, $\\dfrac{dy}{dx}=12x^2-9+\\dfrac{3}{2x^2}$ and $\\dfrac{d^2y}{dx^2}=24x-3x^{-3}$."},{"title":"Determine the nature of P","body":"At $x=\\dfrac12$, $\\dfrac{d^2y}{dx^2}=12-24=-12<0$, so $P$ is a local maximum."},{"title":"Find the other stationary point","body":"Set $12x^2-9+\\dfrac{3}{2x^2}=0$. Multiplying by $2x^2$ gives $24x^4-18x^2+3=0$, or $8x^4-6x^2+1=0$."},{"title":"Solve the quadratic in x squared","body":"$(4x^2-1)(2x^2-1)=0$. The given point has $x=\\dfrac12$, so the second stationary point has $x^2=\\dfrac12$."},{"title":"State the positive x coordinate","body":"Since $x>0$, the second stationary point has $x=\\dfrac1{\\sqrt2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q02","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":2,"marks":7,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q02_M07_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2021_Jan_Q02_M07_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)\\ x=-2,\\ \\dfrac83.\\quad (b)$ local maximum at $x=-2$ and local minimum at $x=\\dfrac83$.","steps":[{"title":"Differentiate the curve","body":"For $y=x^3-x^2-16x+2$, $\\dfrac{dy}{dx}=3x^2-2x-16$."},{"title":"Set the gradient to zero","body":"Stationary points occur when $3x^2-2x-16=0$."},{"title":"Factorise","body":"$3x^2-2x-16=(3x-8)(x+2)$, so $x=\\dfrac83$ or $x=-2$."},{"title":"Differentiate again","body":"$\\dfrac{d^2y}{dx^2}=6x-2$."},{"title":"Classify x equals negative two","body":"At $x=-2$, $6x-2=-14<0$, so the stationary point is a local maximum."},{"title":"Classify x equals eight over three","body":"At $x=\\dfrac83$, $6x-2=14>0$, so the stationary point is a local minimum."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q09","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":9,"marks":10,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Applications of Differentiation","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q09_M10_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2021_MayJune_Q09_M10_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ Proven: $S=\\dfrac{250000}{h}+2000\\sqrt h$. $\\quad (b)\\ h=250^{2/3}$, so $k=\\dfrac23$. $\\quad (c)$ Minimum.","steps":[{"title":"Use the volume","body":"The volume is $l^2h=250000$, so $l^2=\\dfrac{250000}{h}$."},{"title":"Write the surface area","body":"The open box has one square base and four side faces, so $S=l^2+4lh$."},{"title":"Substitute l","body":"Since $l=\\sqrt{\\dfrac{250000}{h}}=\\dfrac{500}{\\sqrt h}$, $4lh=4\\cdot\\dfrac{500}{\\sqrt h}\\cdot h=2000\\sqrt h$."},{"title":"Show S","body":"Therefore $S=\\dfrac{250000}{h}+2000\\sqrt h$."},{"title":"Differentiate S","body":"$S=250000h^{-1}+2000h^{1/2}$, so $\\dfrac{dS}{dh}=-250000h^{-2}+1000h^{-1/2}$."},{"title":"Set the derivative to zero","body":"$-250000h^{-2}+1000h^{-1/2}=0$, so $1000h^{-1/2}=250000h^{-2}$."},{"title":"Solve for h","body":"Multiplying by $h^2$ gives $1000h^{3/2}=250000$, so $h^{3/2}=250$ and $h=250^{2/3}$."},{"title":"Find k","body":"Since $h=250^k$, we have $k=\\dfrac23$."},{"title":"Use the second derivative","body":"$\\dfrac{d^2S}{dh^2}=500000h^{-3}-500h^{-3/2}$."},{"title":"Check the sign","body":"At $h=250^{2/3}$, $h^{3/2}=250$, so the second derivative is $\\dfrac{500000}{250^2}-\\dfrac{500}{250}=8-2=6>0$."},{"title":"Conclude","body":"The stationary point is therefore a minimum."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q08","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":8,"marks":10,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Applications of Differentiation","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q08_M10_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2021_Oct_Q08_M10_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ Proven: $k=28$. $\\quad (b)\\ x<2\\text{ or }x>\\dfrac72.\\quad (c)\\ \\dfrac{40}{3}$.","steps":[{"title":"Differentiate the curve","body":"For $y=\\dfrac43x^3-11x^2+kx$, $\\dfrac{dy}{dx}=4x^2-22x+k$."},{"title":"Use the turning point","body":"At the turning point $M$, $x=2$ and $\\dfrac{dy}{dx}=0$."},{"title":"Show k","body":"$4(2)^2-22(2)+k=0$, so $16-44+k=0$ and $k=28$."},{"title":"Factor the derivative","body":"With $k=28$, $\\dfrac{dy}{dx}=4x^2-22x+28=2(2x-7)(x-2)$."},{"title":"Find where y is increasing","body":"The derivative is positive outside its roots, so $y$ is increasing for $x<2$ or $x>\\dfrac72$."},{"title":"Find the height of the line","body":"At $x=2$, $y=\\dfrac43(8)-11(4)+28(2)=\\dfrac{68}{3}$. Hence line $l$ has equation $y=\\dfrac{68}{3}$."},{"title":"Set up the shaded area","body":"The region is between the line and the curve from $x=0$ to $x=2$, so $A=\\int_0^2\\left(\\dfrac{68}{3}-\\left(\\dfrac43x^3-11x^2+28x\\right)\\right)dx$."},{"title":"Integrate","body":"$A=\\left[\\dfrac{68}{3}x-\\dfrac13x^4+\\dfrac{11}{3}x^3-14x^2\\right]_0^2$."},{"title":"Evaluate exactly","body":"Substituting $x=2$ gives $\\dfrac{136}{3}-\\dfrac{16}{3}+\\dfrac{88}{3}-56=\\dfrac{40}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q02","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":2,"marks":8,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q02_M08_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2022_Jan_Q02_M08_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=\\dfrac{27}{2}x^{-1/2}-\\dfrac32x^{1/2}.\\quad (b)\\ (9,34).\\quad (c)$ local maximum.","steps":[{"title":"Differentiate","body":"For $y=27x^{1/2}-x^{3/2}-20$, $\\dfrac{dy}{dx}=\\dfrac{27}{2}x^{-1/2}-\\dfrac32x^{1/2}$."},{"title":"Set the gradient to zero","body":"$\\dfrac{27}{2}x^{-1/2}-\\dfrac32x^{1/2}=0$."},{"title":"Clear the powers","body":"Multiplying by $2x^{1/2}$ gives $27-3x=0$, so $x=9$."},{"title":"Find y","body":"At $x=9$, $y=27\\sqrt9-9^{3/2}-20=81-27-20=34$."},{"title":"State the stationary point","body":"The stationary point is $(9,34)$."},{"title":"Differentiate again","body":"$\\dfrac{d^2y}{dx^2}=-\\dfrac{27}{4}x^{-3/2}-\\dfrac34x^{-1/2}$."},{"title":"Determine the nature","body":"At $x=9$, both terms in $\\dfrac{d^2y}{dx^2}$ are negative, so the stationary point is a local maximum."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q08","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":8,"marks":8,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q08_M08_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2022_MayJune_Q08_M08_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)\\ \\dfrac{dy}{dx}=1024x^3-304-\\dfrac{54}{x^3}.\\quad (b)\\ \\left(-\\dfrac12,241\\right),\\ \\left(\\dfrac34,-134\\right)$.","steps":[{"title":"Rewrite with powers","body":"$y=256x^4-304x-35+27x^{-2}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=1024x^3-304-54x^{-3}=1024x^3-304-\\dfrac{54}{x^3}$."},{"title":"Set the derivative to zero","body":"$1024x^3-304-\\dfrac{54}{x^3}=0$."},{"title":"Use a substitution","body":"Multiplying by $x^3$ gives $1024x^6-304x^3-54=0$. Let $u=x^3$."},{"title":"Solve for u","body":"$1024u^2-304u-54=0$, or $512u^2-152u-27=0=(8u+1)(64u-27)$."},{"title":"Find x","body":"Thus $x^3=-\\dfrac18$ or $x^3=\\dfrac{27}{64}$, giving $x=-\\dfrac12$ or $x=\\dfrac34$."},{"title":"Find the y values","body":"Substitution into $y=256x^4-304x-35+\\dfrac{27}{x^2}$ gives $y=241$ at $x=-\\dfrac12$ and $y=-134$ at $x=\\dfrac34$."},{"title":"State the stationary points","body":"The stationary points are $\\left(-\\dfrac12,241\\right)$ and $\\left(\\dfrac34,-134\\right)$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q07","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":7,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q07_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2022_Oct_Q07_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ $y=\\dfrac47x^{7/2}-4x^{5/2}+\\dfrac{26}{3}x^{3/2}-10x^{1/2}$. $\\quad (b)$ Proven. $\\quad (c)$ $x=2-\\dfrac{\\sqrt6}{2}$ and $x=2+\\dfrac{\\sqrt6}{2}$.","steps":[{"title":"Expand the numerator","body":"$12x^3(x-7)+14x(13x-15)=12x^4-84x^3+182x^2-210x$."},{"title":"Divide by 21 root x","body":"Since $\\sqrt{x}=x^{1/2}$, divide each term by $21x^{1/2}$."},{"title":"Write in the required form","body":"$y=\\dfrac{12}{21}x^{7/2}-\\dfrac{84}{21}x^{5/2}+\\dfrac{182}{21}x^{3/2}-\\dfrac{210}{21}x^{1/2}=\\dfrac47x^{7/2}-4x^{5/2}+\\dfrac{26}{3}x^{3/2}-10x^{1/2}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=2x^{5/2}-10x^{3/2}+13x^{1/2}-5x^{-1/2}$."},{"title":"Factor the derivative","body":"$\\dfrac{dy}{dx}=x^{-1/2}(2x^3-10x^2+13x-5)$."},{"title":"Use the turning point condition","body":"At a turning point, $\\dfrac{dy}{dx}=0$. Since $x>0$, $x^{-1/2}\\ne0$, so the $x$ coordinates satisfy $2x^3-10x^2+13x-5=0$."},{"title":"Use the known root","body":"One root is $x=1$, so divide $2x^3-10x^2+13x-5$ by $(x-1)$."},{"title":"Factor the cubic","body":"$2x^3-10x^2+13x-5=(x-1)(2x^2-8x+5)$."},{"title":"Solve the quadratic","body":"$2x^2-8x+5=0$ gives $x=\\dfrac{8\\pm\\sqrt{64-40}}{4}=\\dfrac{8\\pm2\\sqrt6}{4}=2\\pm\\dfrac{\\sqrt6}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q02","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":2,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q02_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2023_Jan_Q02_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ $S=6x^2+\\dfrac{2592}{x}$. $\\quad (b)\\ \\dfrac{dS}{dx}=12x-\\dfrac{2592}{x^2}$. $\\quad (c)\\ x=6$. $\\quad (d)$ Minimum shown. $\\quad (e)\\ 648\\text{ cm}^2$.","steps":[{"title":"Use the volume","body":"The cuboid has dimensions $x$, $3x$ and $h$, so its volume is $3x^2h=972$."},{"title":"Write h in terms of x","body":"Hence $h=\\dfrac{972}{3x^2}=\\dfrac{324}{x^2}$."},{"title":"Build the surface area","body":"The surface area is $S=2(3x^2+3xh+xh)=6x^2+8xh$."},{"title":"Substitute h","body":"$S=6x^2+8x\\left(\\dfrac{324}{x^2}\\right)=6x^2+\\dfrac{2592}{x}$."},{"title":"Differentiate","body":"$S=6x^2+2592x^{-1}$, so $\\dfrac{dS}{dx}=12x-2592x^{-2}=12x-\\dfrac{2592}{x^2}$."},{"title":"Set the derivative to zero","body":"For a stationary value, $12x-\\dfrac{2592}{x^2}=0$."},{"title":"Solve for x","body":"Multiplying by $x^2$ gives $12x^3=2592$, so $x^3=216$ and $x=6$."},{"title":"Use the second derivative","body":"$\\dfrac{d^2S}{dx^2}=12+\\dfrac{5184}{x^3}$."},{"title":"Show it is a minimum","body":"At $x=6$, $\\dfrac{d^2S}{dx^2}=12+\\dfrac{5184}{216}=36>0$, so the stationary value is a minimum."},{"title":"Find the minimum surface area","body":"$S=6(6)^2+\\dfrac{2592}{6}=216+432=648$, so the minimum surface area is $648\\text{ cm}^2$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q07","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":7,"marks":8,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["01_Proof"],"secondaryTopicNames":["Proof"],"topics":["11_ApplicationsOfDifferentiation","01_Proof"],"topicNames":["Applications of Differentiation","Proof"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q07_M08_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2023_MayJune_Q07_M08_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $\\alpha=4.491$. $\\quad (c)$ $H$ is a maximum at this value.","steps":[{"title":"Rewrite H with powers","body":"$H=\\dfrac{1}{20}t^{1/2}(20+6t-t^2)+17$."},{"title":"Expand before differentiating","body":"$H=\\dfrac{1}{20}(20t^{1/2}+6t^{3/2}-t^{5/2})+17$."},{"title":"Differentiate","body":"$\\dfrac{dH}{dt}=\\dfrac{1}{20}\\left(10t^{-1/2}+9t^{1/2}-\\dfrac52t^{3/2}\\right)$."},{"title":"Put over a common factor","body":"$\\dfrac{dH}{dt}=\\dfrac{-5t^2+18t+20}{40\\sqrt{t}}$."},{"title":"Use the stationary condition","body":"At $t=\\alpha$, $\\dfrac{dH}{dt}=0$. Since $\\alpha>0$, the denominator is not zero, so $-5\\alpha^2+18\\alpha+20=0$."},{"title":"Show the required equation","body":"Multiplying by $-1$ gives $5\\alpha^2-18\\alpha-20=0$."},{"title":"Find alpha","body":"$\\alpha=\\dfrac{18\\pm\\sqrt{18^2+4(5)(20)}}{10}=\\dfrac{9\\pm\\sqrt{181}}{5}$."},{"title":"Use the time interval","body":"Only the positive value lies in $0\\le t\\le7$, so $\\alpha=\\dfrac{9+\\sqrt{181}}{5}=4.491$ to 3 decimal places."},{"title":"Differentiate again","body":"$\\dfrac{d^2H}{dt^2}=\\dfrac{-15t^2+18t-20}{80t^{3/2}}$."},{"title":"Use the stationary equation","body":"At $t=\\alpha$, $5\\alpha^2=18\\alpha+20$. Therefore the numerator of $\\dfrac{d^2H}{dt^2}$ is $-15\\alpha^2+18\\alpha-20=-3(18\\alpha+20)+18\\alpha-20=-36\\alpha-80$."},{"title":"Show it is negative","body":"Since $\\alpha>0$, $-36\\alpha-80<0$, and the denominator $80\\alpha^{3/2}$ is positive. Thus $\\dfrac{d^2H}{dt^2}<0$, so $H$ is a maximum."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q09","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":9,"marks":12,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Applications of Differentiation","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q09_M12_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2023_Oct_Q09_M12_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ $y$ is increasing for $x>\\dfrac94$. $\\quad (b)$ Area $=\\dfrac{857}{21}$.","steps":[{"title":"Differentiate","body":"For $y=\\dfrac23x^2-9\\sqrt{x}+13$, $\\dfrac{dy}{dx}=\\dfrac43x-\\dfrac{9}{2\\sqrt{x}}$."},{"title":"Set up increasing condition","body":"$y$ is increasing when $\\dfrac{dy}{dx}>0$."},{"title":"Multiply by a positive quantity","body":"For $x>0$, multiply by $6\\sqrt{x}$: $8x\\sqrt{x}-27>0$."},{"title":"Solve the inequality","body":"$x^{3/2}>\\dfrac{27}{8}=\\left(\\dfrac32\\right)^3$, so $\\sqrt{x}>\\dfrac32$ and $x>\\dfrac94$."},{"title":"Find the tangent gradient","body":"At $P(9,40)$, $\\dfrac{dy}{dx}=\\dfrac43(9)-\\dfrac{9}{2\\cdot3}=12-\\dfrac32=\\dfrac{21}{2}$."},{"title":"Write the tangent line","body":"$y-40=\\dfrac{21}{2}(x-9)$, so $y=\\dfrac{21}{2}x-\\dfrac{109}{2}$."},{"title":"Find where the tangent meets the x-axis","body":"Set $y=0$: $\\dfrac{21}{2}x-\\dfrac{109}{2}=0$, so $x=\\dfrac{109}{21}$."},{"title":"Split the area","body":"From $x=0$ to $x=\\dfrac{109}{21}$, the lower boundary is the $x$-axis. From $x=\\dfrac{109}{21}$ to $x=9$, the lower boundary is the tangent."},{"title":"Set up the integral","body":"$\\displaystyle R=\\int_0^{109/21}\\left(\\dfrac23x^2-9\\sqrt{x}+13\\right)dx+\\int_{109/21}^{9}\\left(\\dfrac23x^2-9\\sqrt{x}+13-\\left(\\dfrac{21}{2}x-\\dfrac{109}{2}\\right)\\right)dx$."},{"title":"Use antiderivatives","body":"$\\displaystyle \\int\\left(\\dfrac23x^2-9\\sqrt{x}+13\\right)dx=\\dfrac{2}{9}x^3-6x^{3/2}+13x$, and $\\displaystyle \\int\\left(\\dfrac{21}{2}x-\\dfrac{109}{2}\\right)dx=\\dfrac{21}{4}x^2-\\dfrac{109}{2}x$."},{"title":"Evaluate","body":"Substituting the limits and simplifying gives $R=\\dfrac{857}{21}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q10","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":10,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Applications of Differentiation","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q10_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2024_Jan_Q10_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ Proven. $\\quad (b)$ $\\dfrac{373}{3}$.","steps":[{"title":"Rewrite the curve","body":"$y=\\dfrac12x^2+1458x^{-3/2}-74$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=x+1458\\left(-\\dfrac32\\right)x^{-5/2}=x-2187x^{-5/2}$."},{"title":"Use the stationary condition","body":"At a stationary point, $x-2187x^{-5/2}=0$."},{"title":"Solve for x","body":"$x=2187x^{-5/2}$, so $x^{7/2}=2187=3^7$."},{"title":"Show x coordinate","body":"Raising both sides to the power $\\dfrac27$ gives $x=3^2=9$. Since $x>0$, this is the only stationary point."},{"title":"Find the horizontal line","body":"At $x=9$, $y=\\dfrac12(9)^2+\\dfrac{1458}{\\sqrt{9^3}}-74=\\dfrac{81}{2}+54-74=\\dfrac{41}{2}$."},{"title":"Set up the area","body":"The region lies from $x=4$ to $x=9$ between the curve and the horizontal line $y=\\dfrac{41}{2}$."},{"title":"Integrate the difference","body":"$\\displaystyle R=\\int_4^9\\left(\\dfrac12x^2+1458x^{-3/2}-74-\\dfrac{41}{2}\\right)dx$."},{"title":"Find an antiderivative","body":"$\\displaystyle \\int\\left(\\dfrac12x^2+1458x^{-3/2}-\\dfrac{189}{2}\\right)dx=\\dfrac{x^3}{6}-2916x^{-1/2}-\\dfrac{189}{2}x$."},{"title":"Evaluate exactly","body":"$\\displaystyle R=\\left[\\dfrac{x^3}{6}-2916x^{-1/2}-\\dfrac{189}{2}x\\right]_4^9=\\dfrac{373}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q09","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":9,"marks":8,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Applications of Differentiation","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q09_M08_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2024_MayJune_Q09_M08_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ $x=\\dfrac{12}{5}$. $\\quad (b)$ $k=\\dfrac{28}{5}$.","steps":[{"title":"Rewrite the curve","body":"$y=2x^{3/2}(4-x)=8x^{3/2}-2x^{5/2}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=12x^{1/2}-5x^{3/2}=\\sqrt{x}(12-5x)$."},{"title":"Find the stationary point","body":"For the interior stationary point $P$, $12-5x=0$, so $x=\\dfrac{12}{5}$."},{"title":"Set up the area condition","body":"$R_1$ is the area from $x=0$ to $x=4$ above the $x$-axis. $R_2$ is the area from $x=4$ to $x=k$ below the $x$-axis."},{"title":"Use equal areas","body":"Equal areas mean $\\displaystyle \\int_0^4 y\\,dx=-\\int_4^k y\\,dx$, so $\\displaystyle \\int_0^k y\\,dx=0$."},{"title":"Integrate y","body":"$\\displaystyle \\int 2x^{3/2}(4-x)dx=\\int(8x^{3/2}-2x^{5/2})dx=\\dfrac{16}{5}x^{5/2}-\\dfrac47x^{7/2}$."},{"title":"Solve for k","body":"$\\dfrac{16}{5}k^{5/2}-\\dfrac47k^{7/2}=0$."},{"title":"Factor","body":"$4k^{5/2}\\left(\\dfrac45-\\dfrac{k}{7}\\right)=0$."},{"title":"Choose the value beyond four","body":"Since $k>4$, $\\dfrac45-\\dfrac{k}{7}=0$, so $k=\\dfrac{28}{5}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q06","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":6,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["02_Polynomials"],"secondaryTopicNames":["Polynomials"],"topics":["11_ApplicationsOfDifferentiation","02_Polynomials"],"topicNames":["Applications of Differentiation","Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q06_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q06_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)(i)$ $p=10$. $\\quad (a)(ii)$ $q=3$. $\\quad (b)$ $-1<x<-\\dfrac23$.","steps":[{"title":"Use the factor theorem","body":"Since $(2x+3)$ is a factor, $x=-\\dfrac32$ is a root."},{"title":"Substitute x equals negative three halves","body":"$4\\left(-\\dfrac32\\right)^3+p\\left(-\\dfrac32\\right)^2+8\\left(-\\dfrac32\\right)+q=0$."},{"title":"Simplify the first condition","body":"$-\\dfrac{27}{2}+\\dfrac94p-12+q=0$, so $\\dfrac94p+q=\\dfrac{51}{2}$."},{"title":"Use the remainder theorem","body":"The remainder on division by $(x+2)$ is $f(-2)$."},{"title":"Substitute x equals negative two","body":"$f(-2)=4(-8)+4p-16+q=4p+q-48$."},{"title":"Use the given remainder","body":"$4p+q-48=-5$, so $4p+q=43$."},{"title":"Solve for p and q","body":"Subtract $\\dfrac94p+q=\\dfrac{51}{2}$ from $4p+q=43$: $\\dfrac74p=\\dfrac{35}{2}$, so $p=10$. Then $4(10)+q=43$, so $q=3$."},{"title":"Differentiate","body":"With $p=10$, $f(x)=4x^3+10x^2+8x+3$, so $f'(x)=12x^2+20x+8$."},{"title":"Factor the derivative","body":"$f'(x)=4(3x+2)(x+1)$."},{"title":"Find where decreasing","body":"The quadratic derivative is negative between its roots, so $f(x)$ is decreasing for $-1<x<-\\dfrac23$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q10","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":10,"marks":9,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Applications of Differentiation","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q10_M09_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q10_M09_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ $x=3$. $\\quad (b)$ $\\dfrac{148}{5}$.","steps":[{"title":"Rewrite the curve","body":"$y=\\dfrac{9x-x^2}{2\\sqrt{x}}=\\dfrac12(9x^{1/2}-x^{3/2})$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=\\dfrac12\\left(\\dfrac92x^{-1/2}-\\dfrac32x^{1/2}\\right)=\\dfrac{3(3-x)}{4\\sqrt{x}}$."},{"title":"Use the stationary condition","body":"For $x>0$, the denominator is not zero. So $\\dfrac{dy}{dx}=0$ when $3-x=0$."},{"title":"Find P","body":"Therefore the $x$ coordinate of $P$ is $3$."},{"title":"Find where the curve meets the x-axis","body":"$y=0$ when $9x-x^2=0$, so $x=9$ for the positive intercept."},{"title":"Set up the area","body":"The region is under the curve from $x=1$ to $x=9$, so $R=\\displaystyle \\int_1^9 \\dfrac{9x-x^2}{2\\sqrt{x}}dx$."},{"title":"Integrate","body":"$R=\\displaystyle \\int_1^9 \\dfrac12(9x^{1/2}-x^{3/2})dx=\\left[3x^{3/2}-\\dfrac15x^{5/2}\\right]_1^9$."},{"title":"Evaluate","body":"$R=\\left(3(27)-\\dfrac15(243)\\right)-\\left(3-\\dfrac15\\right)=\\dfrac{148}{5}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q04","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":4,"marks":7,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":[],"secondaryTopicNames":[],"topics":["11_ApplicationsOfDifferentiation"],"topicNames":["Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q04_M07_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2024_Oct_Q04_M07_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ $\\dfrac{2}{\\sqrt{x}}-\\dfrac{9}{2x^{3/2}}$. $\\quad (b)$ $x=\\dfrac94$. $\\quad (c)(i)$ $-\\dfrac1{x^{3/2}}+\\dfrac{27}{4x^{5/2}}$. $\\quad (c)(ii)$ Minimum. $\\quad (d)$ $0<x<\\dfrac94$.","steps":[{"title":"Rewrite using powers","body":"$y=4x^{1/2}+9x^{-1/2}+3$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=2x^{-1/2}-\\dfrac92x^{-3/2}=\\dfrac{2}{\\sqrt{x}}-\\dfrac{9}{2x^{3/2}}$."},{"title":"Set the derivative to zero","body":"$\\dfrac{dy}{dx}=\\dfrac{4x-9}{2x^{3/2}}$. Since $x>0$, the stationary point occurs when $4x-9=0$."},{"title":"Find the x coordinate","body":"Therefore $x=\\dfrac94$."},{"title":"Differentiate again","body":"$\\dfrac{d^2y}{dx^2}=-x^{-3/2}+\\dfrac{27}{4}x^{-5/2}=-\\dfrac1{x^{3/2}}+\\dfrac{27}{4x^{5/2}}$."},{"title":"Test the stationary point","body":"$\\dfrac{d^2y}{dx^2}=\\dfrac{27-4x}{4x^{5/2}}$. At $x=\\dfrac94$, the numerator is $27-9=18>0$, so the stationary point is a minimum."},{"title":"Find where y is decreasing","body":"For $x>0$, $2x^{3/2}>0$, so $\\dfrac{dy}{dx}<0$ when $4x-9<0$. Hence $y$ is decreasing for $0<x<\\dfrac94$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q03","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":3,"marks":10,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["11_ApplicationsOfDifferentiation","08_ModellingSequencesSeries"],"topicNames":["Applications of Differentiation","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q03_M10_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2025_Jan_Q03_M10_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ $A=3x^2+\\dfrac{320}{x}$, so $P=3$ and $Q=320$. $\\quad (b)$ $x=3.76$. $\\quad (c)$ $\\dfrac{d^2A}{dx^2}=6+\\dfrac{640}{x^3}$, minimum.","steps":[{"title":"Use the volume","body":"The volume is $(3x)(x)(y)=3x^2y$. Since the capacity is $120$, $3x^2y=120$, so $y=\\dfrac{40}{x^2}$."},{"title":"Write the metal area","body":"The open top means the metal area is the base plus four sides: $A=3x^2+2(3xy)+2(xy)$."},{"title":"Substitute for y","body":"$A=3x^2+8xy=3x^2+8x\\left(\\dfrac{40}{x^2}\\right)=3x^2+\\dfrac{320}{x}$. Hence $P=3$ and $Q=320$."},{"title":"Differentiate","body":"$\\dfrac{dA}{dx}=6x-320x^{-2}=6x-\\dfrac{320}{x^2}$."},{"title":"Use the stationary condition","body":"Set $\\dfrac{dA}{dx}=0$: $6x=\\dfrac{320}{x^2}$, so $6x^3=320$."},{"title":"Find x","body":"$x^3=\\dfrac{160}{3}$, so $x=\\sqrt[3]{\\dfrac{160}{3}}=3.764\\ldots$. To $3$ significant figures, $x=3.76$."},{"title":"Differentiate again","body":"$\\dfrac{d^2A}{dx^2}=6+640x^{-3}=6+\\dfrac{640}{x^3}$."},{"title":"Show the minimum","body":"For $x>0$, $6+\\dfrac{640}{x^3}>0$, so the stationary value found in part (b) is a minimum."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q09","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":9,"marks":11,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["11_ApplicationsOfDifferentiation","08_ModellingSequencesSeries"],"topicNames":["Applications of Differentiation","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q09_M11_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2025_MayJune_Q09_M11_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)$ $S=6x^2+\\dfrac{20}{x}$, so $P=6$ and $Q=20$. $\\quad (b)$ $25.3$. $\\quad (c)$ Minimum justified.","steps":[{"title":"Find the triangular end area","body":"Each end is a right-angled triangle with perpendicular sides $3x$ and $2x$, so its area is $\\dfrac12(3x)(2x)=3x^2$."},{"title":"Use the capacity","body":"The volume is cross-section area times length, so $3x^2L=12$ and $L=\\dfrac4{x^2}$."},{"title":"Write the metal area","body":"There are two triangular ends with total area $6x^2$, and two rectangular sides with total area $3xL+2xL=5xL$."},{"title":"Substitute for L","body":"$S=6x^2+5x\\left(\\dfrac4{x^2}\\right)=6x^2+\\dfrac{20}{x}$. Hence $P=6$ and $Q=20$."},{"title":"Differentiate","body":"$\\dfrac{dS}{dx}=12x-20x^{-2}=12x-\\dfrac{20}{x^2}$."},{"title":"Find the stationary value of x","body":"Set $\\dfrac{dS}{dx}=0$: $12x=\\dfrac{20}{x^2}$, so $x^3=\\dfrac53$."},{"title":"Evaluate S","body":"At $x=\\sqrt[3]{\\dfrac53}$, $S=6x^2+\\dfrac{20}{x}=25.3029\\ldots$, so the minimum value is $25.3$ to one decimal place."},{"title":"Differentiate again","body":"$\\dfrac{d^2S}{dx^2}=12+40x^{-3}=12+\\dfrac{40}{x^3}$."},{"title":"Justify the minimum","body":"Since $x>0$, $12+\\dfrac{40}{x^3}>0$, so the stationary value found is a minimum."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q10","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":10,"marks":8,"topic":"11_ApplicationsOfDifferentiation","topicName":"Applications of Differentiation","primaryTopic":"11_ApplicationsOfDifferentiation","primaryTopicName":"Applications of Differentiation","secondaryTopics":["12_Integration"],"secondaryTopicNames":["Integration"],"topics":["11_ApplicationsOfDifferentiation","12_Integration"],"topicNames":["Applications of Differentiation","Integration"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q10_M08_11_ApplicationsOfDifferentiation.png","downloadName":"WMA12-01_Y2026_Jan_Q10_M08_11_ApplicationsOfDifferentiation.png","finalAnswer":"$(a)\\ x=2\\sqrt5.\\quad (b)\\ k=\\dfrac{10\\sqrt{21}}{3}$.","steps":[{"title":"Rewrite the curve","body":"$y=\\dfrac{\\sqrt{x}(100-x^2)}{40}=\\dfrac52x^{1/2}-\\dfrac1{40}x^{5/2}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=\\dfrac54x^{-1/2}-\\dfrac1{16}x^{3/2}$."},{"title":"Use the stationary point","body":"At $P$, $\\dfrac{dy}{dx}=0$. Thus $\\dfrac54x^{-1/2}=\\dfrac1{16}x^{3/2}$. Multiplying by $16x^{1/2}$ gives $20=x^2$."},{"title":"Find the x-coordinate","body":"Since $x\\geq0$, $x=\\sqrt{20}=2\\sqrt5$."},{"title":"Integrate the curve","body":"$\\int y\\,dx=\\int\\left(\\dfrac52x^{1/2}-\\dfrac1{40}x^{5/2}\\right)dx=\\dfrac53x^{3/2}-\\dfrac1{140}x^{7/2}$."},{"title":"Use equal areas","body":"The signed area from $0$ to $k$ is zero because the positive area $R_1$ equals the negative area $R_2$ in magnitude."},{"title":"Solve for k","body":"$\\dfrac53k^{3/2}-\\dfrac1{140}k^{7/2}=0$. Since $k>0$, divide by $k^{3/2}$ to get $\\dfrac53-\\dfrac{k^2}{140}=0$, so $k^2=\\dfrac{700}{3}$."},{"title":"Write the exact value","body":"$k=\\sqrt{\\dfrac{700}{3}}=\\dfrac{10\\sqrt{21}}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q05","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":5,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q05_M07_12_Integration.png","downloadName":"WMA12-01_Y2019_Oct_Q05_M07_12_Integration.png","finalAnswer":"$(a)$ A decreasing exponential curve crossing the $y$-axis at $(0,1)$. $\\quad (b)\\ 19.0.\\quad (c)\\ 1.0$.","steps":[{"title":"Describe the sketch","body":"For $0<a<1$, $y=a^x$ is a decreasing exponential curve. At $x=0$, $y=a^0=1$, so it crosses the $y$-axis at $(0,1)$."},{"title":"Find the strip width","body":"The $x$ values increase by $0.5$, so $h=0.5$."},{"title":"Apply the trapezium rule","body":"$A\\approx\\dfrac{0.5}{2}\\{4.25+16.06+2(6.427+9.125+12.34)\\}$."},{"title":"Calculate the estimate","body":"$A\\approx0.25(76.094)=19.0235$, so the estimate is $19.0$ to 3 significant figures."},{"title":"Relate the two integrands","body":"$x(x-3)+\\left(\\dfrac12\\right)^x=x^2+\\left(\\dfrac12\\right)^x-3x$."},{"title":"Subtract the exact integral of 3x","body":"$\\int_2^4 3x\\,dx=\\left[\\dfrac32x^2\\right]_2^4=24-6=18$."},{"title":"Estimate the new integral","body":"Using the estimate from part (b), the required value is $19.0235-18=1.0235$, so the estimate is $1.0$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2019_Oct_Q08","year":2019,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2019","qNo":8,"marks":9,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2019_Oct_Q08_M09_12_Integration.png","downloadName":"WMA12-01_Y2019_Oct_Q08_M09_12_Integration.png","finalAnswer":"$(i)\\ 4\\sqrt2-\\dfrac{37}{8}.\\quad (ii)\\ k=\\dfrac{29}{18}$.","steps":[{"title":"Rewrite the curve","body":"$y=\\dfrac{8\\sqrt{x}-5}{2x^2}=4x^{-3/2}-\\dfrac52x^{-2}$."},{"title":"Integrate the curve","body":"$\\int\\left(4x^{-3/2}-\\dfrac52x^{-2}\\right)dx=-8x^{-1/2}+\\dfrac{5}{2x}$."},{"title":"Apply the limits for the area","body":"$\\left[-8x^{-1/2}+\\dfrac{5}{2x}\\right]_2^4=\\left(-4+\\dfrac58\\right)-\\left(-4\\sqrt2+\\dfrac54\\right)$."},{"title":"Simplify the exact area","body":"This gives $4\\sqrt2-\\dfrac{37}{8}$."},{"title":"Integrate the second expression","body":"$\\int\\left(\\dfrac12x^2+k\\right)dx=\\dfrac{x^3}{6}+kx$."},{"title":"Use the limits","body":"$\\left[\\dfrac{x^3}{6}+kx\\right]_{-3}^{6}=\\left(36+6k\\right)-\\left(-\\dfrac92-3k\\right)=\\dfrac{81}{2}+9k$."},{"title":"Solve for k","body":"$\\dfrac{81}{2}+9k=55$, so $9k=\\dfrac{29}{2}$ and $k=\\dfrac{29}{18}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q01","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":1,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["09_LawsOfLogarithms"],"secondaryTopicNames":["Laws of Logarithms"],"topics":["12_Integration","09_LawsOfLogarithms"],"topicNames":["Integration","Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q01_M07_12_Integration.png","downloadName":"WMA12-01_Y2020_Jan_Q01_M07_12_Integration.png","finalAnswer":"$(a)\\ 45.6.\\quad (b)(i)\\ 18.2.\\quad (b)(ii)\\ -21.6$.","steps":[{"title":"Use the trapezium rule","body":"The strip width is $h=3$. Therefore $\\int_2^{14}\\log_2(2x)\\,dx\\approx\\dfrac32\\{2+4.81+2(3.32+4+4.46)\\}$."},{"title":"Calculate part (a)","body":"The estimate is $\\dfrac32(30.37)=45.555$, so to one decimal place the answer is $45.6$."},{"title":"Rewrite part (b)(i)","body":"$\\log_2(4x^2)=\\log_2\\{(2x)^2\\}=2\\log_2(2x)$, so $\\int_2^{14}\\dfrac{\\log_2(4x^2)}5\\,dx=\\dfrac25\\int_2^{14}\\log_2(2x)\\,dx$."},{"title":"Estimate part (b)(i)","body":"Using part (a), the estimate is $\\dfrac25(45.555)=18.222$, so $18.2$ to one decimal place."},{"title":"Rewrite part (b)(ii)","body":"$\\log_2\\left(\\dfrac2x\\right)=2-\\log_2(2x)$."},{"title":"Estimate part (b)(ii)","body":"$\\int_2^{14}\\log_2\\left(\\dfrac2x\\right)dx\\approx\\int_2^{14}2\\,dx-45.555=24-45.555=-21.555$, so $-21.6$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2020_Jan_Q04","year":2020,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2020","qNo":4,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2020_Jan_Q04_M06_12_Integration.png","downloadName":"WMA12-01_Y2020_Jan_Q04_M06_12_Integration.png","finalAnswer":"$\\dfrac{20\\sqrt5}{3}$.","steps":[{"title":"Find the intersection with y equals 17","body":"The curve is $y=2x^2+7$. Set $2x^2+7=17$ to get $x^2=5$, so the right-hand limit is $x=\\sqrt5$."},{"title":"Set up the area","body":"The shaded area is between $y=17$ and $y=2x^2+7$, from $x=0$ to $x=\\sqrt5$."},{"title":"Integrate","body":"$A=\\int_0^{\\sqrt5}\\{17-(2x^2+7)\\}\\,dx=\\int_0^{\\sqrt5}(10-2x^2)\\,dx$."},{"title":"Evaluate the exact area","body":"$A=\\left[10x-\\dfrac23x^3\\right]_0^{\\sqrt5}=10\\sqrt5-\\dfrac23(5\\sqrt5)=\\dfrac{20\\sqrt5}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Jan_Q07","year":2021,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2021","qNo":7,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["12_Integration","08_ModellingSequencesSeries"],"topicNames":["Integration","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2021_Jan_Q07_M06_12_Integration.png","downloadName":"WMA12-01_Y2021_Jan_Q07_M06_12_Integration.png","finalAnswer":"$(a)\\ P(10)=1.20,\\ P(11.5)=2.821.\\quad (b)\\ 4.61\\text{ kWh}$.","steps":[{"title":"Use the model at t equals ten","body":"$P(10)=0.95+2^{-2}+2^2-(10-12)^2=0.95+0.25+4-4=1.20$."},{"title":"Use the model at t equals eleven point five","body":"$P(11.5)=0.95+2^{-0.5}+2^{0.5}-(11.5-12)^2=2.821\\ldots$."},{"title":"Identify the trapezium width","body":"The time values increase by $0.5$, so $h=0.5$."},{"title":"Apply the trapezium rule","body":"The estimate is $\\dfrac{0.5}{2}\\{1.20+2.95+2(1.882+2.45+2.821\\ldots)\\}$."},{"title":"Calculate the energy","body":"This gives $4.614\\ldots$, so the estimated energy is $4.61\\text{ kWh}$ to 2 decimal places."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_MayJune_Q05","year":2021,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2021","qNo":5,"marks":10,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2021_MayJune_Q05_M10_12_Integration.png","downloadName":"WMA12-01_Y2021_MayJune_Q05_M10_12_Integration.png","finalAnswer":"$(a)\\ 12.33.\\quad (b)\\ \\dfrac25x^{5/2}-\\dfrac32x^2+9x+c.\\quad (c)\\ 4.6$.","steps":[{"title":"Identify the strip width","body":"The $x$ values increase by $0.25$, so $h=0.25$."},{"title":"Apply the trapezium rule","body":"The area under $C_1$ is approximately $\\dfrac{0.25}{2}\\{5.453+5+2(7.764+9.375+9.964+9.367+7.626)\\}$."},{"title":"Calculate the estimate","body":"This gives $12.330625$, so the estimate is $12.33$ to 2 decimal places."},{"title":"Integrate C two","body":"$\\int(x^{3/2}-3x+9)\\,dx=\\dfrac25x^{5/2}-\\dfrac32x^2+9x+c$."},{"title":"Find the area under C two","body":"Between $x=2.5$ and $x=4$, the exact integral of $C_2$ is $\\left[\\dfrac25x^{5/2}-\\dfrac32x^2+9x\\right]_{2.5}^{4}=7.722\\ldots$."},{"title":"Find the shaded area","body":"The shaded region is between $C_1$ and $C_2$, so its area is approximately $12.330625-7.722\\ldots=4.608\\ldots$."},{"title":"Round the result","body":"To one decimal place, the area of region $R$ is $4.6$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2021_Oct_Q03","year":2021,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2021","qNo":3,"marks":8,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["09_LawsOfLogarithms"],"secondaryTopicNames":["Laws of Logarithms"],"topics":["12_Integration","09_LawsOfLogarithms"],"topicNames":["Integration","Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2021_Oct_Q03_M08_12_Integration.png","downloadName":"WMA12-01_Y2021_Oct_Q03_M08_12_Integration.png","finalAnswer":"$(a)\\ 10.10.\\quad (b)$ Use more strips. $\\quad (c)(i)\\ 5.05.\\quad (c)(ii)\\ 54.30$.","steps":[{"title":"Find the strip width","body":"Four equal strips from $x=2$ to $x=14$ have width $h=\\dfrac{14-2}{4}=3$."},{"title":"List the ordinates","body":"Use $x=2,5,8,11,14$ and $y=\\log_{10}x$."},{"title":"Apply the trapezium rule","body":"$A\\approx\\dfrac32\\{\\log_{10}2+\\log_{10}14+2(\\log_{10}5+\\log_{10}8+\\log_{10}11)\\}=10.10\\ldots$."},{"title":"Improve the estimate","body":"Use more strips of smaller width to make the trapezium rule estimate more accurate."},{"title":"Estimate the square-root integral","body":"$\\log_{10}\\sqrt{x}=\\dfrac12\\log_{10}x$, so $\\int_2^{14}\\log_{10}\\sqrt{x}\\,dx\\approx\\dfrac12(10.10)=5.05$."},{"title":"Rewrite the second logarithm","body":"$\\log_{10}(100x^3)=\\log_{10}100+\\log_{10}x^3=2+3\\log_{10}x$."},{"title":"Estimate the second integral","body":"$\\int_2^{14}(2+3\\log_{10}x)\\,dx\\approx2(12)+3(10.10)=54.30$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q01","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":1,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q01_M07_12_Integration.png","downloadName":"WMA12-01_Y2022_Jan_Q01_M07_12_Integration.png","finalAnswer":"$(a)\\ 11.79.\\quad (b)(i)\\ 23.57.\\quad (b)(ii)\\ 17.79$.","steps":[{"title":"Identify the strip width","body":"The $x$ values increase by $0.5$, so $h=0.5$."},{"title":"Apply the trapezium rule","body":"$\\int_5^7 2^{5-\\sqrt{x}}\\,dx\\approx\\dfrac{0.5}{2}\\{6.792+5.113+2(6.298+5.858+5.466)\\}$."},{"title":"Calculate the estimate","body":"This gives $11.78725$, so the estimate is $11.79$ to 2 decimal places."},{"title":"Use the factor of two","body":"$2^{6-\\sqrt{x}}=2\\cdot2^{5-\\sqrt{x}}$, so $\\int_5^7 2^{6-\\sqrt{x}}\\,dx\\approx2(11.78725)=23.5745$."},{"title":"Estimate part i","body":"This is $23.57$ to 2 decimal places."},{"title":"Add the constant integral","body":"$\\int_5^7(3+2^{5-\\sqrt{x}})\\,dx=\\int_5^7 3\\,dx+\\int_5^7 2^{5-\\sqrt{x}}\\,dx$."},{"title":"Estimate part ii","body":"The estimate is $3(7-5)+11.78725=17.78725$, so $17.79$ to 2 decimal places."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Jan_Q09","year":2022,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2022","qNo":9,"marks":10,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["12_Integration","11_ApplicationsOfDifferentiation"],"topicNames":["Integration","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2022_Jan_Q09_M10_12_Integration.png","downloadName":"WMA12-01_Y2022_Jan_Q09_M10_12_Integration.png","finalAnswer":"$(a)\\ P=(1-m,\\ m(1-m)).\\quad (b)$ Proven: $\\dfrac{(1-m)^3}{6}$. $\\quad (c)\\ m=1-\\dfrac1{\\sqrt[3]{2}}$.","steps":[{"title":"Find the second intersection","body":"At an intersection, $x-x^2=mx$, so $x(1-m-x)=0$."},{"title":"State P","body":"The non-zero intersection has $x=1-m$, and then $y=m(1-m)$, so $P=(1-m,m(1-m))$."},{"title":"Set up area R one","body":"Region $R_1$ is between the curve and the line from $x=0$ to $x=1-m$."},{"title":"Integrate the difference","body":"$A_{R_1}=\\int_0^{1-m}\\{(x-x^2)-mx\\}\\,dx=\\int_0^{1-m}\\{(1-m)x-x^2\\}\\,dx$."},{"title":"Evaluate","body":"$A_{R_1}=\\left[\\dfrac{1-m}{2}x^2-\\dfrac13x^3\\right]_0^{1-m}=\\dfrac{(1-m)^3}{2}-\\dfrac{(1-m)^3}{3}=\\dfrac{(1-m)^3}{6}$."},{"title":"Use the total curve area","body":"The total area under $y=x-x^2$ from $x=0$ to $x=1$ is $\\int_0^1(x-x^2)\\,dx=\\dfrac16$."},{"title":"Use equal regions","body":"Since $R_1$ and $R_2$ are equal and together make this total area, each has area $\\dfrac{1}{12}$."},{"title":"Solve for m","body":"$\\dfrac{(1-m)^3}{6}=\\dfrac1{12}$, so $(1-m)^3=\\dfrac12$ and $m=1-\\dfrac1{\\sqrt[3]{2}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q02","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":2,"marks":8,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["09_LawsOfLogarithms"],"secondaryTopicNames":["Laws of Logarithms"],"topics":["12_Integration","09_LawsOfLogarithms"],"topicNames":["Integration","Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q02_M08_12_Integration.png","downloadName":"WMA12-01_Y2022_MayJune_Q02_M08_12_Integration.png","finalAnswer":"$(a)\\ y(1)=1.075,\\ y(2)=1.041.\\quad (b)\\ 2.96.\\quad (c)\\ 7.04$.","steps":[{"title":"Complete the missing table values","body":"Using $y=1-\\log_{10}(\\sin x)$ gives $y(1)=1.075$ and $y(2)=1.041$ to 3 decimal places."},{"title":"Identify the strip width","body":"The $x$ values increase by $0.5$, so $h=0.5$."},{"title":"Apply the trapezium rule","body":"$A\\approx\\dfrac{0.5}{2}\\{1.319+1.850+2(1.075+1.001+1.041+1.223)\\}$."},{"title":"Calculate part b","body":"This gives $2.9625\\ldots$, so the estimate is $2.96$ to 2 decimal places."},{"title":"Rewrite the new integrand","body":"Since $y=1-\\log_{10}(\\sin x)$, we have $\\log_{10}(\\sin x)=1-y$."},{"title":"Use the interval length","body":"$3+\\log_{10}(\\sin x)=4-y$, and the interval from $0.5$ to $3$ has length $2.5$."},{"title":"Estimate part c","body":"$\\int_{0.5}^{3}(3+\\log_{10}(\\sin x))\\,dx\\approx4(2.5)-2.9625\\ldots=7.0374\\ldots$, so $7.04$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_MayJune_Q07","year":2022,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2022","qNo":7,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["02_Polynomials"],"secondaryTopicNames":["Polynomials"],"topics":["12_Integration","02_Polynomials"],"topicNames":["Integration","Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2022_MayJune_Q07_M07_12_Integration.png","downloadName":"WMA12-01_Y2022_MayJune_Q07_M07_12_Integration.png","finalAnswer":"$A=\\dfrac12,\\quad B=-28$.","steps":[{"title":"Use the factor condition","body":"Since $(x+2)$ is a factor, $f(-2)=0$."},{"title":"Form the first equation","body":"$A(-2)^3+6(-2)^2-4(-2)+B=0$, so $-8A+32+B=0$ and $B=8A-32$."},{"title":"Set up the integral","body":"$\\int_3^5(Ax^3+6x^2-4x+B)\\,dx=176$."},{"title":"Integrate","body":"$\\left[\\dfrac A4x^4+2x^3-2x^2+Bx\\right]_3^5=176$."},{"title":"Simplify the second equation","body":"This gives $136A+164+2B=176$, so $68A+B=6$."},{"title":"Solve simultaneously","body":"Using $B=8A-32$ in $68A+B=6$ gives $76A=38$, so $A=\\dfrac12$."},{"title":"Find B","body":"$B=8\\left(\\dfrac12\\right)-32=-28$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2022_Oct_Q06","year":2022,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2022","qNo":6,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["12_Integration","11_ApplicationsOfDifferentiation"],"topicNames":["Integration","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2022_Oct_Q06_M07_12_Integration.png","downloadName":"WMA12-01_Y2022_Oct_Q06_M07_12_Integration.png","finalAnswer":"$(a)$ $4.845$. $\\quad (b)\\ 25.2\\%$.","steps":[{"title":"Identify the strip width","body":"The $x$ values increase by $0.5$, so the trapezium-rule width is $h=0.5$."},{"title":"Apply the trapezium rule","body":"$\\displaystyle \\int_0^2 f(x)\\,dx\\approx \\dfrac{0.5}{2}\\left[3+1.92+2(2.6833+2.4+2.1466)\\right]$."},{"title":"Evaluate the estimate","body":"This gives $4.84495$, so the approximation is $4.845$ to 3 decimal places."},{"title":"Find the area under C2","body":"$\\displaystyle \\int_0^2 \\left(2-\\dfrac14x^2\\right)dx=\\left[2x-\\dfrac{x^3}{12}\\right]_0^2=4-\\dfrac{2}{3}=\\dfrac{10}{3}$."},{"title":"Estimate the shaded area","body":"The shaded region lies between $C_1$ and $C_2$, so its estimated area is $4.845-\\dfrac{10}{3}=1.5116\\ldots$."},{"title":"Compare with the rectangle","body":"The rectangle has area $2\\times3=6$."},{"title":"Convert to a percentage","body":"Percentage shaded $=\\dfrac{1.5116\\ldots}{6}\\times100=25.19\\ldots\\%$, so the estimate is $25.2\\%$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q01","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":1,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q01_M06_12_Integration.png","downloadName":"WMA12-01_Y2023_Jan_Q01_M06_12_Integration.png","finalAnswer":"$(a)$ $10.52$. $\\quad (b)(i)\\ 6.52. $\\quad $(b)(ii)\\ 10.52$.","steps":[{"title":"Use the trapezium width","body":"The $x$ values run from $-1$ to $1$ in steps of $0.5$, so $h=0.5$."},{"title":"Apply the trapezium rule","body":"$\\displaystyle \\int_{-1}^{1} f(x)\\,dx\\approx \\dfrac{0.5}{2}\\left[2.287+2.834+2(4.470+6.719+7.291)\\right]$."},{"title":"Evaluate the estimate","body":"This gives $10.52025$, so the estimate is $10.52$ to 2 decimal places."},{"title":"Estimate the shifted-down area","body":"$\\displaystyle \\int_{-1}^{1}(f(x)-2)\\,dx=\\int_{-1}^{1}f(x)\\,dx-\\int_{-1}^{1}2\\,dx$."},{"title":"Subtract the rectangle","body":"The interval has width $2$, so $\\int_{-1}^{1}2\\,dx=4$. Hence the estimate is $10.52-4=6.52$."},{"title":"Use a substitution","body":"For $\\displaystyle \\int_{1}^{3} f(x-2)\\,dx$, let $u=x-2$. When $x=1$, $u=-1$, and when $x=3$, $u=1$."},{"title":"Recognise the same integral","body":"So $\\displaystyle \\int_{1}^{3} f(x-2)\\,dx=\\int_{-1}^{1} f(u)\\,du$, which has the same estimate $10.52$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Jan_Q09","year":2023,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2023","qNo":9,"marks":8,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["02_Polynomials"],"secondaryTopicNames":["Polynomials"],"topics":["12_Integration","02_Polynomials"],"topicNames":["Integration","Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2023_Jan_Q09_M08_12_Integration.png","downloadName":"WMA12-01_Y2023_Jan_Q09_M08_12_Integration.png","finalAnswer":"$(a)$ $D=(0,5)$. $\\quad (b)$ $x_E=1,\\ x_F=3$. $\\quad (c)$ $k=\\dfrac{8}{19}$.","steps":[{"title":"Find D","body":"At the $y$-axis, $x=0$. On $C$, $y=0^2-4(0)+5=5$, so $D=(0,5)$."},{"title":"Find intersections with the line","body":"The line is $y=2$, so solve $x^2-4x+5=2$."},{"title":"Solve the quadratic","body":"$x^2-4x+3=0$, so $(x-1)(x-3)=0$. Hence $x_E=1$ and $x_F=3$."},{"title":"Area of R1","body":"$R_1$ lies between the curve and the line $y=2$ from $x=0$ to $x=1$."},{"title":"Integrate R1","body":"$\\displaystyle R_1=\\int_0^1\\left(x^2-4x+5-2\\right)dx=\\int_0^1(x^2-4x+3)dx$."},{"title":"Evaluate R1","body":"$\\displaystyle R_1=\\left[\\dfrac{x^3}{3}-2x^2+3x\\right]_0^1=\\dfrac13-2+3=\\dfrac43$."},{"title":"Find the line DF","body":"The line through $D=(0,5)$ and $F=(3,2)$ has gradient $-1$, so its equation is $y=5-x$."},{"title":"Split R2","body":"For $0\\le x\\le1$, $R_2$ is between $y=5-x$ and the curve. For $1\\le x\\le3$, it is between $y=5-x$ and $y=2$."},{"title":"Integrate R2","body":"$\\displaystyle R_2=\\int_0^1\\left[(5-x)-(x^2-4x+5)\\right]dx+\\int_1^3\\left[(5-x)-2\\right]dx$."},{"title":"Evaluate R2","body":"$\\displaystyle R_2=\\int_0^1(-x^2+3x)dx+\\int_1^3(3-x)dx=\\dfrac{7}{6}+2=\\dfrac{19}{6}$."},{"title":"Find the ratio","body":"$k=\\dfrac{\\text{area of }R_1}{\\text{area of }R_2}=\\dfrac{4/3}{19/6}=\\dfrac{8}{19}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q01","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":1,"marks":3,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q01_M03_12_Integration.png","downloadName":"WMA12-01_Y2023_MayJune_Q01_M03_12_Integration.png","finalAnswer":"$6.814$.","steps":[{"title":"Identify the interval width","body":"The $x$ values go from $4.0$ to $5.0$ in steps of $0.2$, so $h=0.2$."},{"title":"Apply the trapezium rule","body":"$\\displaystyle \\int_4^5 f(x)\\,dx\\approx \\dfrac{0.2}{2}\\left[9.2+8.6+2(8.4556+3.8512+5.0342+7.8297)\\right]$."},{"title":"Evaluate","body":"The value is $6.81414$, so the approximation is $6.814$ to 3 decimal places."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_MayJune_Q10","year":2023,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2023","qNo":10,"marks":10,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["12_Integration","11_ApplicationsOfDifferentiation"],"topicNames":["Integration","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2023_MayJune_Q10_M10_12_Integration.png","downloadName":"WMA12-01_Y2023_MayJune_Q10_M10_12_Integration.png","finalAnswer":"$(a)$ $a=6,\\ b=-84$. $\\quad (b)$ $k=4$. $\\quad (c)$ Area $=\\dfrac{1683}{10}$.","steps":[{"title":"Expand the integrand","body":"$\\dfrac{(x-k)^2}{\\sqrt{x}}=\\dfrac{x^2-2kx+k^2}{x^{1/2}}=x^{3/2}-2kx^{1/2}+k^2x^{-1/2}$."},{"title":"Integrate","body":"$\\displaystyle \\int \\left(x^{3/2}-2kx^{1/2}+k^2x^{-1/2}\\right)dx=\\dfrac25x^{5/2}-\\dfrac{4k}{3}x^{3/2}+2k^2x^{1/2}$."},{"title":"Substitute the limits","body":"From $1$ to $16$, this gives $\\left(\\dfrac{2048}{5}-\\dfrac{256k}{3}+8k^2\\right)-\\left(\\dfrac25-\\dfrac{4k}{3}+2k^2\\right)$."},{"title":"Simplify the integral","body":"The result is $6k^2-84k+\\dfrac{2046}{5}$, so $a=6$ and $b=-84$."},{"title":"Use point A","body":"Since $A(1,9)$ lies on $C$, $9=\\dfrac{(1-k)^2}{\\sqrt1}=(1-k)^2$."},{"title":"Find k","body":"Thus $1-k=\\pm3$, so $k=4$ or $k=-2$. Since $k$ is positive, $k=4$."},{"title":"Find point B","body":"When $k=4$ and $x=16$, $q=\\dfrac{(16-4)^2}{\\sqrt{16}}=\\dfrac{144}{4}=36$, so $B=(16,36)$."},{"title":"Find the line","body":"The line through $A(1,9)$ and $B(16,36)$ has gradient $\\dfrac{36-9}{16-1}=\\dfrac95$, so $l$ has equation $y=\\dfrac95x+\\dfrac{36}{5}$."},{"title":"Area under the line","body":"$\\displaystyle \\int_1^{16}\\left(\\dfrac95x+\\dfrac{36}{5}\\right)dx=\\left[\\dfrac{9}{10}x^2+\\dfrac{36}{5}x\\right]_1^{16}=\\dfrac{675}{2}$."},{"title":"Area under the curve","body":"From part (a), with $k=4$, $\\displaystyle \\int_1^{16}\\dfrac{(x-4)^2}{\\sqrt{x}}dx=6(4)^2-84(4)+\\dfrac{2046}{5}=\\dfrac{846}{5}$."},{"title":"Subtract curve from line","body":"The shaded area is $\\dfrac{675}{2}-\\dfrac{846}{5}=\\dfrac{1683}{10}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2023_Oct_Q06","year":2023,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2023","qNo":6,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["08_ModellingSequencesSeries"],"secondaryTopicNames":["Modelling with Sequences & Series"],"topics":["12_Integration","08_ModellingSequencesSeries"],"topicNames":["Integration","Modelling with Sequences & Series"],"image":"ial/wma12/questions/WMA12-01_Y2023_Oct_Q06_M06_12_Integration.png","downloadName":"WMA12-01_Y2023_Oct_Q06_M06_12_Integration.png","finalAnswer":"$(a)$ $31.38\\text{ m}^2$. $\\quad (b)$ $2.8\\times10^3\\text{ m}^3$. $\\quad (c)$ Underestimate.","steps":[{"title":"Read the strip width","body":"The $x$ values are $0,3,6,9,12,15$, so the trapezium width is $h=3$."},{"title":"Apply the trapezium rule","body":"$\\text{Area}\\approx \\dfrac32\\left[0+0+2(1.52+2.74+3.12+3.08)\\right]$."},{"title":"Find the cross-sectional area","body":"This gives $31.38\\text{ m}^2$."},{"title":"Convert flow speed to one minute","body":"The speed is $1.5\\text{ m s}^{-1}$, so in one minute the water travels $1.5\\times60=90\\text{ m}$."},{"title":"Estimate volume","body":"Volume per minute $\\approx31.38\\times90=2824.2\\text{ m}^3$."},{"title":"Round the volume","body":"To 2 significant figures, this is $2.8\\times10^3\\text{ m}^3$."},{"title":"State over or under","body":"It is an underestimate, because the curve between the plotted points lies below the straight-line trapezium chords in the diagram, so the true cross-sectional area is larger."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Jan_Q04","year":2024,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2024","qNo":4,"marks":9,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2024_Jan_Q04_M09_12_Integration.png","downloadName":"WMA12-01_Y2024_Jan_Q04_M09_12_Integration.png","finalAnswer":"$(a)$ $y$-intercept $(0,5)$ and asymptote $y=4$. $\\quad (b)$ $69$. $\\quad (c)(i)$ $19$. $\\quad (c)(ii)$ $138$.","steps":[{"title":"Find the y-intercept","body":"For $y=a^{-x}+4$, set $x=0$: $y=a^0+4=5$, so the curve meets the $y$-axis at $(0,5)$."},{"title":"Find the asymptote","body":"Since $a>1$, $a^{-x}\\to0$ as $x\\to\\infty$, so the horizontal asymptote is $y=4$."},{"title":"Describe the sketch","body":"The curve is decreasing, passes through $(0,5)$, and approaches the line $y=4$ from above."},{"title":"Use the trapezium width","body":"The $x$ values increase by $2.5$, so $h=2.5$."},{"title":"Apply the trapezium rule","body":"$\\displaystyle \\int_{-4}^{8.5}\\left(3^{-x/2}+4\\right)dx\\approx \\dfrac{2.5}{2}\\left[13+4.009+2(6.280+4.577+4.146+4.037)\\right]$."},{"title":"Round part b","body":"This gives $68.86125$, so to two significant figures the estimate is $69$."},{"title":"Remove the constant part","body":"$\\displaystyle \\int_{-4}^{8.5}4\\,dx=4(12.5)=50$."},{"title":"Estimate part c i","body":"Using the answer to part (b), $\\displaystyle \\int_{-4}^{8.5}3^{-x/2}dx\\approx69-50=19$."},{"title":"Use symmetry by substitution","body":"For $\\displaystyle \\int_{-8.5}^{4}(3^{x/2}+4)dx$, let $u=-x$. This changes it to the same integral as part (b)."},{"title":"Estimate part c ii","body":"Therefore the two integrals in part (c)(ii) are approximately equal, so the total is $69+69=138$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJune_Q06","year":2024,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2024","qNo":6,"marks":9,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJune_Q06_M09_12_Integration.png","downloadName":"WMA12-01_Y2024_MayJune_Q06_M09_12_Integration.png","finalAnswer":"$(a)$ $y$-intercept $(0,5)$ and asymptote $y=4$. $\\quad (b)$ $2.34$. $\\quad (c)(i)$ $18.84$. $\\quad (c)(ii)$ $4.68$.","steps":[{"title":"Sketch key features","body":"For $y=a^x+4$ with $a>1$, the curve is increasing."},{"title":"Find the y-intercept","body":"At $x=0$, $y=a^0+4=5$, so the $y$-intercept is $(0,5)$."},{"title":"Find the asymptote","body":"As $x\\to-\\infty$, $a^x\\to0$, so the horizontal asymptote is $y=4$."},{"title":"Use the trapezium width","body":"The $x$ values increase by $0.3$, so $h=0.3$."},{"title":"Apply the trapezium rule","body":"$\\displaystyle \\int_2^{3.5}(2^x-2x)dx\\approx\\dfrac{0.3}{2}[0+4.3137+2(0.3246+0.8629+1.6643+2.7896)]$."},{"title":"Round part b","body":"This gives $2.339475$, so the estimate is $2.34$ to 2 decimal places."},{"title":"Estimate part c i","body":"$2^x+2x=(2^x-2x)+4x$, so $\\displaystyle \\int_2^{3.5}(2^x+2x)dx\\approx2.34+\\int_2^{3.5}4x\\,dx$."},{"title":"Add the extra integral","body":"$\\displaystyle \\int_2^{3.5}4x\\,dx=[2x^2]_2^{3.5}=16.5$, so the estimate is $2.34+16.5=18.84$."},{"title":"Estimate part c ii","body":"$2^{x+1}-4x=2(2^x-2x)$, so the estimate is $2(2.34)=4.68$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_MayJuneR_Q02","year":2024,"session":"MayJuneR","paperCode":"WMA12-01","paper":"WMA12/01 May/June R 2024","qNo":2,"marks":5,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2024_MayJuneR_Q02_M05_12_Integration.png","downloadName":"WMA12-01_Y2024_MayJuneR_Q02_M05_12_Integration.png","finalAnswer":"$(a)$ $a=2.21$ to 3 s.f. $\\quad (b)$ $11.6$.","steps":[{"title":"Use the trapezium width","body":"The $x$ values increase by $1.5$, so $h=1.5$."},{"title":"Set up the trapezium estimate","body":"$19.3=\\dfrac{1.5}{2}[4.16+2.28+2(2.91+a+1.73+1.37+1.43)]$."},{"title":"Solve for a","body":"This simplifies to $19.3=15.99+1.5a$, so $a=\\dfrac{3.31}{1.5}=2.206\\ldots$."},{"title":"Round a","body":"Therefore $a=2.21$ to 3 significant figures."},{"title":"Use the transformed integral","body":"$\\displaystyle \\int_{-4}^{5}(2f(x)-3)dx=2\\int_{-4}^{5}f(x)dx-\\int_{-4}^{5}3\\,dx$."},{"title":"Substitute the given estimate","body":"This is $2(19.3)-3(9)=38.6-27=11.6$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q01","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":1,"marks":5,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q01_M05_12_Integration.png","downloadName":"WMA12-01_Y2024_Oct_Q01_M05_12_Integration.png","finalAnswer":"$(a)$ $30.9$. $\\quad (b)$ $90.9$.","steps":[{"title":"Find the strip width","body":"The $x$ values increase by $1.25$, so the trapezium width is $h=1.25$."},{"title":"Apply the trapezium rule","body":"$\\displaystyle \\int_{0.5}^{5.5} f(x)\\,dx\\approx\\dfrac{1.25}{2}\\{3.479+5.182+2(6.101+7.448+6.823)\\}$."},{"title":"Evaluate the estimate","body":"This gives $30.878125$, which is $30.9$ to one decimal place."},{"title":"Split the second integral","body":"$\\displaystyle \\int_{0.5}^{5.5}(f(x)+4x)\\,dx=\\int_{0.5}^{5.5}f(x)\\,dx+\\int_{0.5}^{5.5}4x\\,dx$."},{"title":"Integrate 4x","body":"$\\displaystyle \\int_{0.5}^{5.5}4x\\,dx=[2x^2]_{0.5}^{5.5}=2(5.5)^2-2(0.5)^2=60$."},{"title":"Use part a","body":"Using the estimate from part (a), the required value is $30.9+60=90.9$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2024_Oct_Q08","year":2024,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2024","qNo":8,"marks":8,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["02_Polynomials"],"secondaryTopicNames":["Polynomials"],"topics":["12_Integration","02_Polynomials"],"topicNames":["Integration","Polynomials"],"image":"ial/wma12/questions/WMA12-01_Y2024_Oct_Q08_M08_12_Integration.png","downloadName":"WMA12-01_Y2024_Oct_Q08_M08_12_Integration.png","finalAnswer":"$(a)$ $x_P=1$, $x_Q=3$. $\\quad (b)$ $\\dfrac{16}{3}$.","steps":[{"title":"Equate the curves","body":"$x^2+3=13-\\dfrac9{x^2}$."},{"title":"Clear the denominator","body":"Multiplying by $x^2$ gives $x^4+3x^2=13x^2-9$, so $x^4-10x^2+9=0$."},{"title":"Factor","body":"Let $u=x^2$. Then $u^2-10u+9=(u-1)(u-9)=0$, so $x^2=1$ or $x^2=9$."},{"title":"Use x greater than zero","body":"Since $x>0$, the intersections have $x=1$ and $x=3$. Thus $x_P=1$ and $x_Q=3$."},{"title":"Set up the area","body":"Between $x=1$ and $x=3$, curve $C_2$ is above curve $C_1$, so $R=\\displaystyle\\int_1^3\\left(13-\\dfrac9{x^2}-(x^2+3)\\right)dx$."},{"title":"Simplify the integrand","body":"$R=\\displaystyle\\int_1^3(10-x^2-9x^{-2})\\,dx$."},{"title":"Integrate","body":"$R=\\left[10x-\\dfrac{x^3}{3}+\\dfrac9x\\right]_1^3$."},{"title":"Evaluate","body":"$R=\\left(30-9+3\\right)-\\left(10-\\dfrac13+9\\right)=24-\\dfrac{56}{3}=\\dfrac{16}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Jan_Q09","year":2025,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2025","qNo":9,"marks":12,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["12_Integration","11_ApplicationsOfDifferentiation"],"topicNames":["Integration","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2025_Jan_Q09_M12_12_Integration.png","downloadName":"WMA12-01_Y2025_Jan_Q09_M12_12_Integration.png","finalAnswer":"$(a)$ $M\\left(16,\\dfrac{2304}{5}\\right)$. $\\quad (b)$ $x_P=25$. $\\quad (c)$ $1312.7$.","steps":[{"title":"Rewrite the curve","body":"$y=\\dfrac{9x^2(5-\\sqrt{x})}{5}=9x^2-\\dfrac95x^{5/2}$."},{"title":"Differentiate","body":"$\\dfrac{dy}{dx}=18x-\\dfrac92x^{3/2}=\\dfrac92x(4-\\sqrt{x})$."},{"title":"Find the turning point x coordinate","body":"For the turning point shown away from the origin, set $4-\\sqrt{x}=0$. Hence $x=16$."},{"title":"Find the y coordinate","body":"At $x=16$, $y=\\dfrac{9(16)^2(5-4)}{5}=\\dfrac{2304}{5}$."},{"title":"State M","body":"Therefore $M\\left(16,\\dfrac{2304}{5}\\right)$."},{"title":"Find the positive x intercept","body":"For the positive intercept, $\\dfrac{9x^2(5-\\sqrt{x})}{5}=0$ gives $5-\\sqrt{x}=0$, so $x=25$."},{"title":"Set up the area","body":"The top boundary is $y=\\dfrac{2304}{5}$ and the curve is below it from $x=16$ to $x=25$. So $R=\\displaystyle\\int_{16}^{25}\\left(\\dfrac{2304}{5}-9x^2+\\dfrac95x^{5/2}\\right)dx$."},{"title":"Integrate","body":"$R=\\left[\\dfrac{2304}{5}x-3x^3+\\dfrac{18}{35}x^{7/2}\\right]_{16}^{25}$."},{"title":"Evaluate","body":"$R=\\dfrac{9189}{7}=1312.714\\ldots$, so the area is $1312.7$ to one decimal place."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q03","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":3,"marks":5,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q03_M05_12_Integration.png","downloadName":"WMA12-01_Y2025_MayJune_Q03_M05_12_Integration.png","finalAnswer":"$\\dfrac{27}{2}$.","steps":[{"title":"Find the line PQ","body":"The gradient of $PQ$ is $\\dfrac{5-11}{4-1}=-2$, so the line through $P(1,11)$ is $y-11=-2(x-1)$."},{"title":"Write the line equation","body":"Thus $PQ$ has equation $y=-2x+13$."},{"title":"Set up the area","body":"From $x=1$ to $x=4$, the line segment is above the curve. Hence $R=\\displaystyle\\int_1^4\\left[(-2x+13)-\\left(3x+\\dfrac{16}{x^2}-8\\right)\\right]dx$."},{"title":"Simplify the integrand","body":"$R=\\displaystyle\\int_1^4(21-5x-16x^{-2})\\,dx$."},{"title":"Integrate","body":"$R=\\left[21x-\\dfrac52x^2+\\dfrac{16}{x}\\right]_1^4$."},{"title":"Evaluate","body":"$R=(84-40+4)-\\left(21-\\dfrac52+16\\right)=48-\\dfrac{69}{2}=\\dfrac{27}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_MayJune_Q05","year":2025,"session":"MayJune","paperCode":"WMA12-01","paper":"WMA12/01 May/June 2025","qNo":5,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2025_MayJune_Q05_M06_12_Integration.png","downloadName":"WMA12-01_Y2025_MayJune_Q05_M06_12_Integration.png","finalAnswer":"$(a)$ $18.8$. $\\quad (b)(i)$ $4.7$. $\\quad (b)(ii)$ $51.3$.","steps":[{"title":"Find the strip width","body":"The $x$ values increase by $1.5$, so $h=1.5$."},{"title":"Apply the trapezium rule","body":"$\\displaystyle\\int_{-2}^{7}3\\left(\\dfrac12\\right)^x dx\\approx\\dfrac{1.5}{2}\\{12+0.023+2(4.243+1.5+0.530+0.188+0.066)\\}$."},{"title":"Evaluate","body":"This gives $18.80775$, which is $18.8$ to one decimal place."},{"title":"Use the power shift","body":"$3\\left(\\dfrac12\\right)^{x+2}=\\dfrac14\\cdot3\\left(\\dfrac12\\right)^x$."},{"title":"Estimate part b i","body":"So $\\displaystyle\\int_{-2}^{7}3\\left(\\dfrac12\\right)^{x+2}dx\\approx\\dfrac14(18.80775)=4.7019375$, which is $4.7$."},{"title":"Rewrite part b ii","body":"Since $3\\left(\\dfrac12\\right)^x=3\\cdot2^{-x}$, we have $2^{-x}=\\dfrac13\\cdot3\\left(\\dfrac12\\right)^x$."},{"title":"Estimate part b ii","body":"$\\displaystyle\\int_{-2}^{7}(2^{-x}+2x)dx\\approx\\dfrac{18.80775}{3}+[x^2]_{-2}^{7}=6.26925+45=51.26925$, which is $51.3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q03","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":3,"marks":7,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["09_LawsOfLogarithms"],"secondaryTopicNames":["Laws of Logarithms"],"topics":["12_Integration","09_LawsOfLogarithms"],"topicNames":["Integration","Laws of Logarithms"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q03_M07_12_Integration.png","downloadName":"WMA12-01_Y2025_Oct_Q03_M07_12_Integration.png","finalAnswer":"$(a)$ $k=-16.61$. $\\quad (b)(i)$ $6.63$. $\\quad (b)(ii)$ $4.42$.","steps":[{"title":"Use the point on the curve","body":"Since $P(k,300000)$ lies on $y=3\\times2^{-x}$, $300000=3\\times2^{-k}$."},{"title":"Solve with logarithms","body":"$100000=2^{-k}$, so $-k=\\log_2(100000)$ and $k=-\\log_2(100000)=-16.609\\ldots$."},{"title":"Round k","body":"To $2$ decimal places, $k=-16.61$."},{"title":"Find the strip width","body":"The $x$ values increase by $1.5$, so $h=1.5$."},{"title":"Apply the trapezium rule","body":"$\\displaystyle\\int_{-0.5}^{7}3\\times2^{-x}dx\\approx\\dfrac{1.5}{2}\\{4.243+0.023+2(1.5+0.530+0.188+0.066)\\}$."},{"title":"Evaluate the estimate","body":"This gives $6.6255$, which is $6.63$ to $2$ decimal places."},{"title":"Relate the first new integral","body":"$\\displaystyle\\int_{-0.5}^{7}2^{-x}dx=\\dfrac13\\int_{-0.5}^{7}3\\times2^{-x}dx$."},{"title":"Relate the second new integral","body":"Using the substitution $u=-x$, $\\displaystyle\\int_{-7}^{0.5}2^x dx=\\int_{-0.5}^{7}2^{-u}du$."},{"title":"Estimate the total","body":"The required estimate is therefore $\\dfrac23(6.6255)=4.417$, which is $4.42$ to $2$ decimal places."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2025_Oct_Q07","year":2025,"session":"Oct","paperCode":"WMA12-01","paper":"WMA12/01 October 2025","qNo":7,"marks":10,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":["11_ApplicationsOfDifferentiation"],"secondaryTopicNames":["Applications of Differentiation"],"topics":["12_Integration","11_ApplicationsOfDifferentiation"],"topicNames":["Integration","Applications of Differentiation"],"image":"ial/wma12/questions/WMA12-01_Y2025_Oct_Q07_M10_12_Integration.png","downloadName":"WMA12-01_Y2025_Oct_Q07_M10_12_Integration.png","finalAnswer":"$(a)$ $3x^2-10x^{3/2}-\\dfrac{k}{2\\sqrt{x}}+28$. $\\quad (b)$ Proven. $\\quad (c)$ $248$.","steps":[{"title":"Differentiate","body":"For $y=x^3-4x^{5/2}-kx^{1/2}+28x-44$, $\\dfrac{dy}{dx}=3x^2-10x^{3/2}-\\dfrac{k}{2}x^{-1/2}+28$."},{"title":"Write in simplest form","body":"$\\dfrac{dy}{dx}=3x^2-10x^{3/2}-\\dfrac{k}{2\\sqrt{x}}+28$."},{"title":"Use the stationary point","body":"At $T$, $x=9$ and $\\dfrac{dy}{dx}=0$."},{"title":"Substitute x equals nine","body":"$0=3(9)^2-10(9)^{3/2}-\\dfrac{k}{2\\sqrt9}+28=243-270-\\dfrac{k}{6}+28$."},{"title":"Find k","body":"This simplifies to $0=1-\\dfrac{k}{6}$, so $k=6$."},{"title":"Find the horizontal line","body":"With $k=6$, the $y$ coordinate of $T$ is $9^3-4(9)^{5/2}-6\\sqrt9+28(9)-44=-53$."},{"title":"Set up the area","body":"The line $NT$ is $y=-53$. The region is between the curve and this line from $x=0$ to $x=9$."},{"title":"Write the integral","body":"$R=\\displaystyle\\int_0^9\\left(x^3-4x^{5/2}-6x^{1/2}+28x-44+53\\right)dx$."},{"title":"Integrate","body":"$R=\\left[\\dfrac{x^4}{4}-\\dfrac87x^{7/2}-4x^{3/2}+14x^2+9x\\right]_0^9$."},{"title":"Evaluate","body":"$R=\\dfrac{6939}{28}=247.821\\ldots$, so the area is $248$ to $3$ significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q02","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":2,"marks":6,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q02_M06_12_Integration.png","downloadName":"WMA12-01_Y2026_Jan_Q02_M06_12_Integration.png","finalAnswer":"$(a)\\ 12.35.\\quad (b)$ Use narrower strips, or more trapezia. $\\quad (c)\\ 98.8$.","steps":[{"title":"Find the strip width","body":"The $x$ values increase by $3$, so $h=3$."},{"title":"Apply the trapezium rule","body":"$A\\approx \\dfrac32\\{1.3195+0.4665+2(1.0718+0.8706+0.7071+0.5743)\\}$."},{"title":"Calculate the estimated area","body":"$A\\approx \\dfrac32(8.2336)=12.3504$, so the area is $12.35$ to 2 decimal places."},{"title":"Improve the estimate","body":"A more accurate estimate would use more trapezia, so the strip width is smaller."},{"title":"Use the scale factor in the integral","body":"Since $2^{3-0.1x}=8\\cdot2^{-0.1x}$, the required estimate is $8(12.35)=98.8$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WMA12-01_2026_Jan_Q04","year":2026,"session":"Jan","paperCode":"WMA12-01","paper":"WMA12/01 January 2026","qNo":4,"marks":5,"topic":"12_Integration","topicName":"Integration","primaryTopic":"12_Integration","primaryTopicName":"Integration","secondaryTopics":[],"secondaryTopicNames":[],"topics":["12_Integration"],"topicNames":["Integration"],"image":"ial/wma12/questions/WMA12-01_Y2026_Jan_Q04_M05_12_Integration.png","downloadName":"WMA12-01_Y2026_Jan_Q04_M05_12_Integration.png","finalAnswer":"$k=\\dfrac12$ or $k=3$.","steps":[{"title":"Integrate first","body":"$\\int\\left(\\dfrac{12}{x^2}+4\\right)\\,dx=\\int(12x^{-2}+4)\\,dx=-\\dfrac{12}{x}+4x$."},{"title":"Apply the limits","body":"$\\left[-\\dfrac{12}{x}+4x\\right]_k^{2k}=\\left(-\\dfrac6k+8k\\right)-\\left(-\\dfrac{12}{k}+4k\\right)=\\dfrac6k+4k$."},{"title":"Form a quadratic","body":"Given the integral is $14$, $\\dfrac6k+4k=14$. Multiplying by $k$ gives $4k^2-14k+6=0$, so $2k^2-7k+3=0$."},{"title":"Solve for k","body":"$(2k-1)(k-3)=0$, hence $k=\\dfrac12$ or $k=3$. Both are positive, so both are valid."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"}];
